window.CATALOGUE=[{"ep":1,"topic":"مقدمة في علم التجويد","topic_en":"Introduction to the science of tajweed","url":"https://www.youtube.com/watch?v=H6WTnSZ6G-0&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=1","minutes":23},{"ep":2,"topic":"مقدمة في علم التجويد ـ 2","topic_en":"Introduction to the science of tajweed, part 2","url":"https://www.youtube.com/watch?v=ChtM254qsdU&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=2","minutes":13},{"ep":3,"topic":"باب مخارج الحروف ـ الجوف","topic_en":"Points of articulation: the open space of mouth and throat","url":"https://www.youtube.com/watch?v=Es_a0IGHofc&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=3","minutes":16},{"ep":4,"topic":"باب مخارج الحروف ـ الحلق","topic_en":"Points of articulation: the throat","url":"https://www.youtube.com/watch?v=2BFpfzbBBVo&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=4","minutes":14},{"ep":5,"topic":"باب مخارج الحروف ـ اللسان","topic_en":"Points of articulation: the tongue","url":"https://www.youtube.com/watch?v=vwaWWcV0Z5M&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=5","minutes":37},{"ep":6,"topic":"باب مخارج الحروف ـ اللسان","topic_en":"Points of articulation: the tongue, continued","url":"https://www.youtube.com/watch?v=8zIZQkaySyQ&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=6","minutes":18},{"ep":7,"topic":"باب صفات الحروف ـ الصفات المتضادَّة","topic_en":"Letter characteristics: the opposing pairs","url":"https://www.youtube.com/watch?v=aYO2mrrHqPo&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=7","minutes":18},{"ep":8,"topic":"باب صفات الحروف ـ الشدة والرخاوة والبينية","topic_en":"Letter characteristics: stopped, flowing and in-between sounds","url":"https://www.youtube.com/watch?v=5q5rI3qBLx0&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=8","minutes":29},{"ep":9,"topic":"قياس أزمنة الحروف الصحيحة الساكنة والمتحركة","topic_en":"Measuring how long consonants last, with and without a vowel","url":"https://www.youtube.com/watch?v=AZSlZoUfS9Y&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=9","minutes":35},{"ep":10,"topic":"باب صفات الحروف ـ الاستعلاء والاستفال","topic_en":"Letter characteristics: the back of the tongue raised or lowered","url":"https://www.youtube.com/watch?v=xh_MHe1YOdA&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=10","minutes":31},{"ep":11,"topic":"باب صفات الحروف ـ حكم الألف واللام والراء","topic_en":"Letter characteristics: when alif, lām and rāʾ are heavy or light","url":"https://www.youtube.com/watch?v=MTkmsbjK0Tc&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=11","minutes":44},{"ep":12,"topic":"باب صفات الحروف ـ الإطباق والانفتاح","topic_en":"Letter characteristics: the tongue pressed to the palate, or not","url":"https://www.youtube.com/watch?v=Ydo53V1V1V8&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=12","minutes":15},{"ep":13,"topic":"باب صفات الحروف ـ القلقلة","topic_en":"Letter characteristics: qalqala, the echo on a stopped letter","url":"https://www.youtube.com/watch?v=KgotHP9a7-o&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=13","minutes":35},{"ep":14,"topic":"نصائح لأهل القرآن الكريم","topic_en":"Advice for the people of the Qur'an","url":"https://www.youtube.com/watch?v=Y7Y7g3GIl7Y&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=14","minutes":23},{"ep":15,"topic":"باب صفات الحروف ـ اللين","topic_en":"Letter characteristics: the soft letters (līn)","url":"https://www.youtube.com/watch?v=OJDGrpOFyw8&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=15","minutes":31},{"ep":16,"topic":"باب صفات الحروف ـ الغنة من حيث كونها صفة","topic_en":"Letter characteristics: ghunna as a characteristic","url":"https://www.youtube.com/watch?v=I3-IOD49WgE&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=16","minutes":20},{"ep":17,"topic":"أبرز الأخطاء عند نطق حروف الهجاء","topic_en":"The most common mistakes in pronouncing the letters","url":"https://www.youtube.com/watch?v=_2RZIEq0t6s&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=17","minutes":31},{"ep":18,"topic":"إتمام الحركات","topic_en":"Giving each vowel its full sound","url":"https://www.youtube.com/watch?v=-LxbHpJs9bw&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=18","minutes":28},{"ep":19,"topic":"باب الوقف والابتداء","topic_en":"Stopping and starting","url":"https://www.youtube.com/watch?v=tOW9ZVAI0eU&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=19","minutes":31},{"ep":20,"topic":"باب الوقف والابتداء ـ تنبيهات","topic_en":"Stopping and starting: points to note","url":"https://www.youtube.com/watch?v=bteuCHz-mRM&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=20","minutes":37},{"ep":21,"topic":"مقدمة القسم الثاني من الدورة","topic_en":"Introduction to the second part of the course","url":"https://www.youtube.com/watch?v=KvIwlbpMWIs&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=21","minutes":29},{"ep":22,"topic":"الحرفان الملتقيان","topic_en":"When two letters meet","url":"https://www.youtube.com/watch?v=Z9hDuv7DYMQ&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=22","minutes":35},{"ep":23,"topic":"الحرفان المتقاربان","topic_en":"Two letters close in articulation","url":"https://www.youtube.com/watch?v=LMtDtKjEAzI&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=23","minutes":19},{"ep":24,"topic":"أحكام الميم الساكنة ( الإدغام والإخفاء والإظهار)","topic_en":"Rules of the sākin mīm: merging, hiding and clear pronunciation","url":"https://www.youtube.com/watch?v=gyrtmirqn_M&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=24","minutes":31},{"ep":25,"topic":"أحكام النون الساكنة والتنوين","topic_en":"Rules of the sākin nūn and tanwīn","url":"https://www.youtube.com/watch?v=LYOO-6f3s0U&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=25","minutes":28},{"ep":26,"topic":"أحكام النون الساكنة والتنوين ـ الإخفاء","topic_en":"Rules of the sākin nūn and tanwīn: hiding (ikhfāʾ)","url":"https://www.youtube.com/watch?v=1mydlMCh9eg&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=26","minutes":31},{"ep":27,"topic":"المدود ـ تعريف المد","topic_en":"The madd: what lengthening is","url":"https://www.youtube.com/watch?v=3tL5YYdjnTw&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=27","minutes":30},{"ep":28,"topic":"قياس أزمنة المدود","topic_en":"Measuring the length of a madd","url":"https://www.youtube.com/watch?v=bfbB-YxuDpw&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=28","minutes":16},{"ep":29,"topic":"المدود ـ المد الطبيعي","topic_en":"The madd: the natural madd","url":"https://www.youtube.com/watch?v=d_W1cbLbwM0&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=29","minutes":26},{"ep":30,"topic":"المدود ـ المد الجائز المنفصل","topic_en":"The madd: the optional separated madd","url":"https://www.youtube.com/watch?v=VVoZxsr8uiQ&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=30","minutes":22},{"ep":31,"topic":"الحروف المقطَّعة في القرآن الكريم","topic_en":"The disjoined letters that open some sūras","url":"https://www.youtube.com/watch?v=5za4w-bg6-U&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=31","minutes":19},{"ep":32,"topic":"الحروف المقطَّعة في القرآن الكريم ـ 2","topic_en":"The disjoined letters that open some sūras, part 2","url":"https://www.youtube.com/watch?v=JWjyU5irlF4&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=32","minutes":22},{"ep":33,"topic":"المدود ـ المد العارض للسكون ـ مد اللين","topic_en":"The madd: lengthening caused by stopping, and madd al-līn","url":"https://www.youtube.com/watch?v=lbDV5QSj_vY&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=33","minutes":26},{"ep":34,"topic":"قاعدة أقوى السببين","topic_en":"The rule of the stronger of two causes","url":"https://www.youtube.com/watch?v=1P32Jelgu0A&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=34","minutes":40},{"ep":35,"topic":"التقاء الحرفين الساكنين بكلمة و كلمتين","topic_en":"Two sākin letters meeting, in one word or across two","url":"https://www.youtube.com/watch?v=MEuYX35zBEc&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=35","minutes":17},{"ep":36,"topic":"أبحاث متفرقة ( الإمالة ـ النبر )","topic_en":"Miscellaneous: imāla and stress (nabr)","url":"https://www.youtube.com/watch?v=hLbqfHzw_kI&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=36","minutes":23},{"ep":37,"topic":"كلمات قرآنية لها وضع خاص على رواية حفص","topic_en":"Qur'anic words read in a special way in the riwāya of Ḥafṣ","url":"https://www.youtube.com/watch?v=qBWCZZWsz7I&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=37","minutes":33},{"ep":38,"topic":"الرَّوم والإشمام","topic_en":"Rawm and ishmām: a trace of the vowel when stopping","url":"https://www.youtube.com/watch?v=9MS2pHBYU_s&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=38","minutes":16},{"ep":39,"topic":"ما لا يدخله الرَّوم ولا الإشمام","topic_en":"Where rawm and ishmām are not used","url":"https://www.youtube.com/watch?v=QBa2UXeN-TE&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=39","minutes":18},{"ep":40,"topic":"الألفات السبعة","topic_en":"The seven alifs","url":"https://www.youtube.com/watch?v=WqudUBqqlZQ&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=40","minutes":28},{"ep":41,"topic":"همزة القطع","topic_en":"The hamza that is always pronounced (hamzat al-qaṭʿ)","url":"https://www.youtube.com/watch?v=rySLUV_lcgU&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=41","minutes":14},{"ep":42,"topic":"مراحل تطور وكتابة المصحف الشريف","topic_en":"How the muṣḥaf came to be written","url":"https://www.youtube.com/watch?v=cHDr7oV02nc&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=42","minutes":23},{"ep":43,"topic":"مراحل تطور وكتابة المصحف الشريف ـ 2","topic_en":"How the muṣḥaf came to be written, part 2","url":"https://www.youtube.com/watch?v=PiIsjbNVlS8&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=43","minutes":30},{"ep":44,"topic":"مراحل تطور وكتابة المصحف الشريف ـ 3","topic_en":"How the muṣḥaf came to be written, part 3","url":"https://www.youtube.com/watch?v=X920piSRPgs&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=44","minutes":31},{"ep":45,"topic":"حفظ القرآن الكريم","topic_en":"Memorising the Qur'an","url":"https://www.youtube.com/watch?v=0pVF5wcFOJ8&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=45","minutes":26}];
window.SECTIONS=[{"from":1,"to":2,"en":"Foundations","ar":"المقدمة","tone":"brand"},{"from":3,"to":6,"en":"Points of articulation","ar":"مخارج الحروف","tone":"flow"},{"from":7,"to":16,"en":"Letter characteristics","ar":"صفات الحروف","tone":"stop"},{"from":17,"to":18,"en":"Pronunciation in practice","ar":"الأخطاء وإتمام الحركات","tone":"between"},{"from":19,"to":20,"en":"Stopping and starting","ar":"الوقف والابتداء","tone":"brand"},{"from":21,"to":26,"en":"Part two: when letters meet","ar":"القسم الثاني","tone":"flow"},{"from":27,"to":34,"en":"The madd","ar":"المدود","tone":"stop"},{"from":35,"to":41,"en":"Further rulings","ar":"مباحث متفرقة","tone":"between"},{"from":42,"to":45,"en":"The muṣḥaf and memorisation","ar":"المصحف والحفظ","tone":"brand"}];
window.UNITS=[{"ep":1,"title_en":"Why Tajwīd Exists","title_ar":"مُقَدِّمَةٌ في عِلْمِ التَّجْويد","summary":"Why one mispronounced letter is a real danger to the Qur'an, and where the description of the Arabic letters actually came from.","teach":[{"label_en":"Mould and meaning","title_ar":"الألفاظُ قَوالِبُ المَعاني","body":"Water takes the shape of whatever vessel you pour it into. The wording is the vessel and the meaning is the water - change a letter and the meaning changes shape with it.","tone":"stop"},{"label_en":"The nearest sound","title_ar":"أَقْرَبُ الحُروفِ إِلى لِسانِه","body":"A tongue that never had ح reaches for the nearest sound it already owns. ٱلرَّحْمَٰنِ ٱلرَّحِيمِ comes out الرهمان الرهيم - ح landing on ه - or الرخمان الرخيم, ح landing on خ. The mistake is honest, not careless. Left uncorrected across centuries, that is how a recitation drifts.","tone":"flow"},{"label_en":"No book after it","title_ar":"الكِتابُ الخاتِم","body":"Earlier scriptures were entrusted to people to guard - بِمَا ٱسْتُحْفِظُوا۟ مِن كِتَٰبِ ٱللَّهِ (5:44). That is all the āya says. What came after is history: they were altered. This Book Allah undertook to preserve Himself, and no revelation comes after it to correct it.","tone":"brand"},{"label_en":"Described, not invented","title_ar":"التَّصْويرُ الكِتابيّ","body":"الخليل بن أحمد الفراهيدي listened to the Arabs and wrote down what he found: where each letter comes out, and how it behaves. He invented nothing. The description of the Arabic letters is a photograph of how the Arabs already spoke, taken with the only camera that age had: writing.","tone":"between"},{"label_en":"Two axes","title_ar":"المَخْرَجُ والصِّفَة","body":"Saying \"ب comes from the lips\" does not pin the letter down - م and و come from between the lips too. س، ص and ز share one spot at the tip of the tongue and are still different letters. ه and ح are the mirror case: identical صفات, told apart by place alone. So every letter needs both - where it comes out (مخرج), and how it behaves once it is out (صفة).","tone":"flow"},{"label_en":"Mouth to ear","title_ar":"فَمٌ يَنْطِقُ وَأُذُنٌ تَسْمَع","body":"The Shaykh's mouth speaks and the student's ear listens; then the student's mouth speaks and the Shaykh's ear listens - فإمّا أن يُقِرَّ وإمّا أن يُصَحِّحَ, he either confirms it or corrects it. No copy on a shelf can do that. This is why the Qur'an is taken from a teacher, generation after generation.","tone":"brand"}],"questions":[{"type":"choice","q":"A reciter reads ٱلطَّلَٰقُ as ٱلتَّلَاقُ. What actually changed in his mouth?","ayah":"ٱلطَّلَٰقُ مَرَّتَانِ","ref":"Sūrat al-Baqara 2:229 (part of the āya)","options":["The مخرج moved to a different place","Only the صفات - the مخرج is the same","Both the مخرج and the صفات","Nothing but the spelling"],"answerIndex":1,"why":"ت and ط share one مخرج: طرف اللسان with أصول الثنايا العليا. Only the صفات separate them - and that alone turns طَلَاق into تَلَاق: ٱلطَّلَٰقُ مَرَّتَانِ becomes \"the meeting is twice\", and the other way round يَوْمَ ٱلتَّلَاقِ (40:15), the Day of Meeting, becomes the Day of Divorce."},{"type":"choice","q":"A reciter keeps the مخرج exactly where it belongs but pronounces the س of عَسَىٰ heavy. What word has he just said?","ayah":"عَسَىٰٓ أَن يَبْعَثَكَ رَبُّكَ مَقَامًۭا مَّحْمُودًۭا","ref":"Sūrat al-Isrāʾ 17:79 (part of the āya)","options":["عَصَىٰ","عَزَىٰ","عَسَىٰ","عَشَا"],"arabicOptions":true,"answerIndex":0,"why":"A heavy س is ص. عَسَىٰ is the verb of hope; عَصَىٰ is disobedience - وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ (20:121). A pair of صفات did that much damage without the مخرج moving at all: طرف اللسان stays exactly where it was, and what changes is that the back of the tongue rises to the palate (الاستعلاء والإطباق).","bigArabic":"عَسَىٰ"},{"type":"multi","q":"Non-Arab speakers, the Shaykh said, reach for the nearest sound their own language offers. Tap the two letters they put in place of ح here.","ayah":"ٱلرَّحْمَٰنِ ٱلرَّحِيمِ","ref":"Sūrat al-Fātiḥa 1:3","pool":["ه","خ","ع","ء","ق"],"answers":["ه","خ"],"why":"الرهمان الرهيم puts ه in its place; الرخمان الرخيم puts خ. Those are the neighbours their tongues already know, so the mouth substitutes without meaning to - which is precisely why the sounds had to be written down."},{"type":"choice","q":"What did الخليل بن أحمد actually do for the letters of Arabic?","options":["He invented new rules for reciting the Qur'an","He observed and described sounds the Arabs were already making","He simplified Arabic sounds for non-Arab speakers","He restored letters the Arabs had lost"],"answerIndex":1,"why":"تأمُّل، رصد، تعبير - observe, record, describe. His student سيبويه said of him إن الخليل ذاق الحروف, he tasted the letters: أَخْ، خَا خُو خِي, turning each one fatḥa, ḍamma and kasra with a hand on his throat, then writing down where it came out - خ من أدنى الحلق, ب من الشفتين - until he had mapped them all."},{"type":"choice","q":"Someone objects: \"علم التجويد is an invention of the شيوخ.\" What is the accurate reply?","options":["True, and that is why it can be set aside","False - nobody ever wrote these rules down","They invented nothing; they recorded and codified a language already spoken","True, and the شيوخ were wrong to do it"],"answerIndex":2,"why":"No one invented that ف is مهموسة or that ق is مجهورة - the Arabs spoke that way before anyone described it. The scholars ضبطوا وقعَّدوا: they fixed in writing what was already on the tongue."},{"type":"choice","q":"الخليل said \"الباء من الشفتين\" and then found it was not enough. What was missing?","options":["The letter's حركة","The letter's صفات - how it behaves, not just where it starts","The letter's place in the alphabet","Nothing; the مخرج is the whole description"],"answerIndex":1,"why":"م and و come from between the lips too, so \"from the lips\" does not pin ب down. The مخرج tells you where the sound is born; only the صفات tell you what it is once it is born."},{"type":"multi","q":"Tap the two letters in this pool that come out of the exact same spot (مخرج خاص) and are told apart by صفات alone.","pool":["س","ص","ح","ه","ك","ف"],"answers":["س","ص"],"why":"Both use the same narrow channel between طرف اللسان and the ridge just above the lower front teeth (فويق الثنايا السفلى) - the tip never presses onto the teeth. Two صفات separate them: ص has الاستعلاء والإطباق where س has الاستفال والانفتاح - that pair is all that turns عَسَىٰ into عَصَىٰ. ه and ح are the opposite case: same صفات, two different spots in الحلق."},{"type":"choice","q":"The Prophet ﷺ said to Ubayy ibn Kaʿb: \"Allah has commanded me to recite this sūra to you.\" What does that establish?","ayah":"لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ","ref":"Sūrat al-Bayyina 98:1","options":["The teacher recites and the student listens","The student recites and the teacher listens","Both recite together in unison","The student reads it silently from a copy"],"answerIndex":0,"why":"And to Ibn Masʿūd he ﷺ said اقرأ عليَّ القرآن - the other direction. Both halves make up التلقِّي: فم ينطق وأذن تسمع, then the teacher either confirms or corrects."},{"type":"choice","q":"Ibn Masʿūd recited to the Prophet ﷺ from the opening of Sūrat al-Nisāʾ all the way to this āya. What did the Prophet ﷺ then say to him?","ayah":"فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةٍۭ بِشَهِيدٍۢ وَجِئْنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدًۭا","ref":"Sūrat al-Nisāʾ 4:41","options":["حَسْبُكَ","هٰكَذَا أُنْزِلَتْ","اقْرَأْ وَارْتَقِ","أَعِدْ عَلَيَّ"],"arabicOptions":true,"answerIndex":0,"why":"حَسْبُك - enough. Pages of recitation and not one correction. هٰكَذَا أُنْزِلَتْ belongs to a different incident, when ʿUmar and Hishām ibn Ḥakīm disagreed and each recited before him ﷺ."},{"type":"choice","q":"A companion repeated the bedtime duʿāʾ back and said وَبِرَسُولِكَ ٱلَّذِي أَرْسَلْتَ. The Prophet ﷺ corrected him to وَبِنَبِيِّكَ ٱلَّذِي أَرْسَلْتَ. Why does this belong in a lesson on تجويد?","options":["Because رسول and نبي mean opposite things","Because even between two near-synonyms, in a duʿāʾ, the exact wording was guarded - so how much more كلام الله","Because the companion had forgotten the duʿāʾ entirely","Because that duʿāʾ was revealed as Qur'an"],"answerIndex":1,"why":"رسول and نبي sit close together in meaning, and still the wording was held in place. If a supplication was guarded that closely, كلام الله is owed more care, not less."},{"type":"choice","q":"ٱسْتُحْفِظُوا۟ is built on استفعل. What does the form tell you, and what followed from it?","ayah":"بِمَا ٱسْتُحْفِظُوا۟ مِن كِتَٰبِ ٱللَّهِ","ref":"Sūrat al-Māʾida 5:44 (part of the āya)","options":["They were forced to guard it, and succeeded","They were asked to guard it - the task was handed to people, and it did not survive intact","Allah guarded it Himself, exactly as with the Qur'an","They guarded it faultlessly for generations"],"answerIndex":1,"why":"استفعل here carries الطلب: they were asked to preserve it. The Qur'an's preservation was never handed to أحبار or ربانيين - إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ (15:9)."},{"type":"choice","q":"Earlier scriptures did not stand alone - a later prophet and a later book came after each of them. Why does a drift in pronunciation put the Qur'an in a different position?","options":["Because Arabic is harder to pronounce than other languages","Because no book comes after it to correct it - it is الكِتابُ الخاتِم","Because the Qur'an contains more letters than they did","Because earlier scriptures were never recited aloud"],"answerIndex":1,"why":"Each earlier scripture was followed by a later revelation, confirming and correcting - مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ. After him ﷺ there is no prophet, so the safeguard was built into the transmission itself: mouth to ear, with مخارج and صفات written down."}],"_issues":0,"_state":"verified","url":"https://www.youtube.com/watch?v=H6WTnSZ6G-0&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=1"},{"ep":2,"title_en":"Where Tajwīd Came From","title_ar":"نشأة علم التجويد","summary":"If the rules of tajwīd are simply the rules of the Arabic language, what part of recitation belongs to the Qur'an alone?","teach":[{"label_en":"Twenty-nine sounds","title_ar":"تسعةٌ وعشرون حرفاً","count":"29 spoken / 28 written","body":"Arabic has 29 spoken letters but 28 written ones, because الهمزة had no shape of its own. الخليل بن أحمد الفراهيدي made one by cutting off the head of ع.","tone":"brand"},{"label_en":"The last chapters","title_ar":"أبوابٌ من كتب النحو","body":"مخارج الحروف، صفات الحروف، أحكام النون الساكنة والتنوين - these sat at the end of grammar books such as الكتاب لسيبويه. They were lifted out and written up separately because reciters needed them most.","tone":"flow"},{"label_en":"Four exceptions","title_ar":"خصائص التلاوة","count":"4 things","body":"Strip these four out of recitation and everything left is plain Arabic: إطالة المدود، إطالة الغنة، السكت، والتنغيم وحسن الأداء.","tone":"stop"},{"label_en":"Derived, not invented","title_ar":"علمٌ استنباطي","body":"Nobody designed these rules. Scholars listened to the recitation of the Prophet ﷺ as the Companions carried it on, and described what was already there.","tone":"between"}],"questions":[{"type":"choice","q":"Arabic has 29 spoken letters but only 28 written ones. Which letter accounts for the gap?","options":["ة","ء","لا","ا"],"arabicOptions":true,"answerIndex":1,"why":"الهمزة. It is heard in ءَامَنَ and أَنْعَمْتَ, but the early script gave it no shape of its own - it was written as ا، و or ي, or left unwritten, until الخليل made it a sign. ا is a written letter in its own right (and a حرف مد), so it is not the gap. ة and لا are not extra letters - one is a form of ت، the other two letters joined."},{"type":"multi","q":"Before the hamza had a sign of its own, scribes wrote it as other letters. Tap every letter they used in its place.","pool":["ا","و","ي","ع","ه","ن"],"answers":["ا","و","ي"],"why":"Hence أ، ؤ، ئ - though before الخليل's mark these were not seats but the hamza's own spelling, and sometimes nothing was written at all. A trace of that lightening survives in recitation: حمزة and هشام soften the hamza when stopping - تسهيل or إبدال, never deletion, and for هشام only where it is the word's last letter. In Ḥafṣ it is always pronounced."},{"type":"choice","q":"الخليل بن أحمد الفراهيدي gave the hamza its written sign. Where did the shape come from?","bigArabic":"ء","options":["The head of ع","The tail of ه","The dot of ن","The loop of و"],"answerIndex":0,"why":"He cut the top off ع - a حرف حلقي like the hamza itself - and made it the hamza's mark. Every scribe since has copied him."},{"type":"choice","q":"سيبويه wrote الكتاب as a work of نحو, yet its closing chapters cover مخارج الحروف، صفات الحروف، الهمس، الجهر، القلقلة. What does that show?","options":["سيبويه also wrote a separate book on reciting the Qur'an","Those subjects began as part of the Arabic language, not as rules for reciters","تجويد was unknown until long after سيبويه","سيبويه disagreed with the scholars of tajwīd"],"answerIndex":1,"why":"He was describing how Arabs speak, not how the Qur'an is read. That is the whole point: take the four exceptions out of recitation and what remains is أحكام لغة عربية."},{"type":"choice","q":"Why was علم الفرائض brought up as a parallel?","options":["Because inheritance shares must be recited with tajwīd","Because both sciences go back to الخليل بن أحمد","Because it too was one chapter of a larger science, split off because people needed it so often","Because both of them are فرض عين"],"answerIndex":2,"why":"المواريث sat quietly inside فقه المعاملات until constant need earned it books of its own. The last chapters of كتب النحو were pulled out the same way, for the same reason."},{"type":"choice","q":"علم التجويد is called استنباطي, not اختراعي. Which statement matches that?","options":["Scholars drew the rules out of how the Qur'an was actually recited","Scholars designed the rules, then taught reciters to obey them","The rules were borrowed from Greek phonetics","Each region derived a different set of rules"],"answerIndex":0,"why":"Like someone who studies English and writes down how its verbs behave - he never ordered the English to speak that way. These rules were drawn out of the recitation of the Prophet ﷺ and of the Companions after him."},{"type":"choice","q":"Three of these belong to Qur'anic recitation alone. Which one is ordinary Arabic?","options":["إطالة المدود عن حدها الطبيعي","الإخفاء","إطالة الغنة","التنغيم وحسن الأداء"],"arabicOptions":true,"answerIndex":1,"why":"An Arab tongue does الإخفاء without ever being taught it. The four that recitation owns are إطالة المدود، إطالة الغنة، السكت، والتنغيم وحسن الأداء."},{"type":"choice","q":"This is the example for the first of the four. What is being done to it that ordinary Arabic never does?","ayah":"وَلَا ٱلضَّآلِّينَ","ref":"Sūrat al-Fātiḥa 1:7","options":["Its مد is held far beyond the natural two counts","Its غنة is held for six counts","Its ض is given قلقلة","Its final ن is dropped"],"answerIndex":0,"why":"Arabs stretch a مد طبيعي to two counts and stop there. Here the ألف is held six - مد لازم كلمي مثقل, because a لام مشددة follows it - and that length came down with the recitation itself: so جبريل brought it, so the Prophet ﷺ pronounced it, so the Companions read it back to him."},{"type":"choice","q":"How many مشدد letters in this āya are held with a غنة?","ayah":"مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ","ref":"Sūrat al-Nās 114:6","options":["0","1","2","3"],"answerIndex":2,"why":"Two: the نّ of ٱلْجِنَّةِ and the نّ of ٱلنَّاسِ, where the لام of ال has assimilated into the ن. The نون of مِنَ is not مشددة, so nothing is held on it."},{"type":"choice","q":"An Arab at home talking to his wife would never cut his voice mid-phrase and carry straight on without taking a breath. Which of the four is that?","options":["إطالة المدود","إطالة الغنة","السكت","التنغيم وحسن الأداء"],"arabicOptions":true,"answerIndex":2,"why":"السكت is a brief cut of the voice with no breath taken, and only in the places transmitted in the riwāya. It belongs to recitation, never to conversation."},{"type":"choice","q":"Which pair are the two main pillars of علم التجويد?","options":["الإدغام والإخفاء","المد والقصر","مخارج الحروف وصفات الحروف","اللام الشمسية واللام القمرية"],"arabicOptions":true,"answerIndex":2,"why":"Everything else is تكميلي - أحكام النون الساكنة والتنوين، الميم الساكنة، المد والقصر، اللام الشمسية والقمرية. Where a letter comes from, and what it is like in itself, is the ground everything else stands on."},{"type":"choice","q":"مَنْ يَقُولُ gives إدغام. مِنْ فَضْلِهِ gives إخفاء. جَآءَ gives a long مد. What causes all three?","options":["The rule appears only because of the letter that follows","All three contain a مشدد letter","All three open with a حرف حلقي","All three are heavy words"],"answerIndex":0,"why":"On its own, ن is just ن with its own مخرج and صفات. Put ي after it and you get إدغام, ف after it and you get إخفاء - the تكميلية chapters describe letters in company, not letters alone. (The سكون is written here only to show the نون before the rule applies; the muṣḥaf leaves it bare: مَن يَقُولُ، مِن فَضْلِهِ.)"}],"_issues":0,"_state":"verified","url":"https://www.youtube.com/watch?v=ChtM254qsdU&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=2"},{"ep":3,"title_en":"Three Letters of Air","title_ar":"باب مخارج الحروف ـ الجَوْف","summary":"Where do the three long-vowel letters ا، و، ي actually come from, if not from your chest?","teach":[{"label_en":"Five regions","title_ar":"المَخَارِجُ الرَّئِيسَة","count":"5","body":"Every Arabic letter leaves from one of five regions: الجَوْف، الحَلْق، اللِّسَان، الشَّفَتَان، الخَيْشُوم. The famous seventeen مخارج are the precise outlets sitting inside these five. الخَيْشُوم is the outlet of the غُنَّة.","tone":"brand"},{"label_en":"Not the chest","title_ar":"الجَوْف","body":"الجَوْف is the open air column above the vocal cords: الفَرَاغ الحُلْقُومِيّ plus الفَرَاغ الفَمَوِيّ. It is not the chest and not the belly.","tone":"between"},{"label_en":"Three letters","title_ar":"حُرُوفُ المَدّ","count":"3 letters","letters":"ا و ي","body":"A حرف مد is a ساكن whose preceding حركة matches it: فتحة + ا، ضمة + و، كسرة + ي. These three escape with the least squeeze on the sound, which is why they are credited to the whole air column rather than to one spot.","tone":"flow"},{"label_en":"Always sākina","title_ar":"الأَلِف","count":"1 state","body":"Every other Arabic letter has four states - مفتوح، مضموم، مكسور، ساكن. الألف has one: it is always ساكنة, and the letter before it is always مفتوحة.","tone":"stop"}],"questions":[{"type":"choice","q":"How many main مخارج are there?","options":["3","5","7","17"],"answerIndex":1,"why":"Five: الجَوْف، الحَلْق، اللِّسَان، الشَّفَتَان، الخَيْشُوم. Seventeen is the count of the precise outlets inside them. Letters filed at one outlet - ط، د، ت - share that مخرج and are told apart by their صفات, not by where they come from."},{"type":"multi","q":"Tap the three حروف مد - the letters that come out of الجَوْف.","pool":["ء","ا","ع","و","م","ي","ه","ن"],"answers":["ا","و","ي"],"why":"Only حروف المد. ابن الجزري names them in one line: فَأَلِفُ الجَوْفِ وَأُخْتَاهَا وَهِي … حُرُوفُ مَدٍّ لِلْهَوَاءِ تَنْتَهِي. A و or ي that is not مدية - whether متحركة or لينة (ساكنة بعد فتحة, as in خَوْف) - has its own مخرج: الواو من الشفتين، الياء من وسط اللسان."},{"type":"choice","q":"What is الجَوْف?","bigArabic":"الجَوْف","options":["The chest cavity","The nasal cavity","الفَرَاغ الحُلْقُومِيّ and الفَرَاغ الفَمَوِيّ together","The gap between the lips"],"answerIndex":2,"why":"The throat cavity and the mouth cavity together - the air column running from the vocal cords out to the lips. Nothing is produced down in the chest, so pointing at your chest for حروف المد is a habit worth dropping."},{"type":"choice","q":"Which scholar put الجَوْف on the list of مخارج in the first place?","options":["الخَلِيلُ بْنُ أَحْمَدَ الفَرَاهِيدِيّ","سِيبَوَيْهِ","الفَرَّاء","نَصْرُ بْنُ عَاصِمٍ اللَّيْثِيّ"],"arabicOptions":true,"answerIndex":0,"why":"الخليل, in كتاب العين. Those after him largely dropped it: his student سيبويه left الجوف out and counted sixteen. الفراء also left it out, then merged ل، ن، ر into one مخرج - seventeen minus الجوف is sixteen, minus two more for that merge is fourteen."},{"type":"choice","q":"سيبويه dropped الجَوْف. So where did he say the ألف comes from?","options":["أَقْصَى الحَلْقِ، مَخْرَجِ الهَمْزَة","وَسَطِ اللِّسَان","الشَّفَتَيْن","الخَيْشُوم"],"arabicOptions":true,"answerIndex":0,"why":"He gave الألف to أقصى الحلق alongside الهمزة, the مدية واو to الشفتين, and the مدية ياء to وسط اللسان - the same outlets as their moving counterparts. Removing الجوف is precisely what takes seventeen down to sixteen."},{"type":"choice","q":"Complete the line - how does ابن الجزري qualify his count of seventeen?","verseStem":"مَخَارِجُ الحُرُوفِ سَبْعَةَ عَشَرْ … عَلَى الَّذِي يَخْتَارُهُ مَنِ ــــــ","options":["اخْتَبَرْ","اعْتَبَرْ","اخْتَصَرْ","انْتَشَرْ"],"arabicOptions":true,"answerIndex":0,"why":"مَنِ اخْتَبَرْ - the one who tested it, not merely the one who read it. The qualifier يَخْتَارُهُ marks a choice among views already on the table: ابن الجزري chose الخليل's seventeen over سيبويه's sixteen, and it is his choice that made seventeen the standard count in tajweed teaching."},{"type":"choice","q":"How many حركات - فتحة، ضمة، كسرة - can an ألف carry?","bigArabic":"ا","options":["None","One","Two","Four"],"answerIndex":0,"why":"None. سكون is not a حركة, and الألف takes nothing else: it is ساكنة always, and the letter before it must carry a فتحة."},{"type":"choice","q":"Asked to pronounce an ألف by itself, the grammarians answered لا. Why?","bigArabic":"لا","options":["Because لا is the shortest word in Arabic","Because الألف cannot begin anything - it needs a letter in front of it, and the لام volunteers","Because لام and ألف share one مخرج","Because لا is where the alphabet ends"],"answerIndex":1,"why":"الألف مفتقرة إلى حرف يتقدم عليها. The لام was chosen to repay a favour: لام التعريف is ساكنة and Arabic never begins on a ساكن, so همزة الوصل - written in the shape of an ألف - was brought in to carry it, as in الْبَيْت. Hence لام ألف near the end of the alphabet نصر بن عاصم arranged."},{"type":"choice","q":"Which word carries all three حروف المد?","options":["قَالُوا","إِيمَانًا","نُوحِيهَا","يُوقِنُونَ"],"arabicOptions":true,"answerIndex":2,"why":"نُوحِيهَا packs ضمة + و، كسرة + ي، فتحة + ا into one word (Sūrat Hūd 11:49). قَالُوا has the ألف and the واو but no ياء; إِيمَانًا has the ياء and the ألف but no واو; يُوقِنُونَ has neither ألف nor ياء مدية - its opening يُـ is مضمومة, a moving ياء from وسط اللسان."},{"type":"choice","q":"Which word has a واو مدية?","options":["يَوْمَ","يَقُولُ","خَوْفٌ","ٱلْمَوْتَ"],"arabicOptions":true,"answerIndex":1,"why":"يَقُولُ - the واو is ساكنة after a ضمة, so the vowel before it matches it. In يَوْمَ، خَوْفٌ، ٱلْمَوْتَ the واو is ساكنة after a فتحة: no match, so no حرف مد and no claim on الجوف. These are حروف لين, from الشفتين. (Stopping on one can produce مد اللين - a separate ruling.)"},{"type":"choice","q":"In يُوقِنُونَ, which letter needs the lips rounded forward to come out properly?","ayah":"وَبِٱلْءَاخِرَةِ هُمْ يُوقِنُونَ","ref":"Sūrat al-Baqarah 2:4","options":["الْيَاء","الْوَاو","الْقَاف","النُّون"],"arabicOptions":true,"answerIndex":1,"why":"الواو. The tongue simply rests - وضع الراحة - for the ألف, its middle rises for the ياء, but only the واو asks the lips to move; drop that and يُوقِنُونَ shrinks into a bare ضمة. The rounding is a صفة that must accompany the letter - the مخرج of the واو المدية is still الجوف."},{"type":"choice","q":"Complete the line - what, says ابن الجزري, stands between a reciter and abandoning تجويد?","verseStem":"وَلَيْسَ بَيْنَهُ وَبَيْنَ تَرْكِهِ … إِلَّا رِيَاضَةُ ــــــ","options":["امْرِئٍ بِفَكِّهِ","امْرِئٍ بِنُسْكِهِ","امْرِئٍ بِمِلْكِهِ","امْرِئٍ بِسِلْكِهِ"],"arabicOptions":true,"answerIndex":0,"why":"رِيَاضَةُ امْرِئٍ بِفَكِّهِ - training your own jaw. Nothing in this chapter is theory: the lips either round for the واو or they do not, and the only way across is drilling until the movement arrives on its own."}],"_issues":0,"_state":"verified","url":"https://www.youtube.com/watch?v=Es_a0IGHofc&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=3"},{"ep":4,"title_en":"Six Throat Letters","title_ar":"بَابُ مَخَارِجِ الحُرُوفِ ـ الحَلْق","summary":"Which six letters come out of the throat, and where exactly does each pair sit?","teach":[{"label_en":"The throat","title_ar":"الحَلْق","count":"6 letters","letters":"ء ه ع ح غ خ","body":"The حلق runs from the vocal cords up to اللهاة. It holds three مخارج, two letters each - listed here from the deepest outward.","tone":"brand"},{"label_en":"Deepest","title_ar":"أَقْصَى الحَلْق","letters":"ء ه","mnemonic":"هَمْزٌ هَاءُ","body":"The vocal-cord region. الهمزة is a closure of the cords. الهاء is a partial opening - the breath keeps running, but through a narrow gap, never a wide gust.","tone":"brand"},{"label_en":"Middle","title_ar":"وَسَطُ الحَلْق","letters":"ع ح","mnemonic":"فَعَيْنٌ حَاءُ","body":"لسان المزمار draws back toward the rear wall of the throat. For العين it draws back far enough to squeeze the مخرج without sealing it; for الحاء it draws back less, so the gap stays wide and the sound runs on.","tone":"brand"},{"label_en":"Nearest the mouth","title_ar":"أَدْنَى الحَلْق","letters":"غ خ","mnemonic":"غَيْنٌ خَاؤُهَا","body":"جذر اللسان - further back than أقصى اللسان, where القاف is - raised toward the soft palate by اللهاة. Still counted a throat مخرج. الخاء sits a little higher than الغين, which makes it the last of the six.","tone":"flow"}],"questions":[{"type":"choice","q":"How many مخارج are inside the حلق?","options":["1","2","3","4"],"answerIndex":2,"why":"Three: أقصى الحلق (ء ه), وسط الحلق (ع ح), أدنى الحلق (غ خ) - two letters each, six in all."},{"type":"choice","q":"Complete ابن الجزري's line on the throat.","verseStem":"ثُمَّ لِأَقْصَى الحَلْقِ: هَمْزٌ هَاءُ … ثُمَّ لِوَسْطِهِ: فَـ ‗‗‗","options":["غَيْنٌ خَاءُ","قَافٌ كَافُ","جِيمٌ شِينُ","عَيْنٌ حَاءُ"],"arabicOptions":true,"answerIndex":3,"why":"The next half-line finishes the throat: أَدْنَاهُ: غَيْنٌ خَاؤُهَا. Six letters in a line and a half, ordered from the vocal cords outward."},{"type":"multi","q":"Tap every throat letter that occurs in this āya.","ayah":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","ref":"Sūrat al-Fātiḥah 1:5","pool":["ء","ه","ع","ح","غ","خ"],"answers":["ء","ع"],"why":"الهمزة opens إِيَّاكَ twice, and العين sits in نَعْبُدُ and نَسْتَعِينُ. Leave لسان المزمار forward and نَعْبُدُ comes out with no عين at all."},{"type":"choice","q":"Which مخرج does this letter come from?","bigArabic":"ه","options":["أَدْنَى الحَلْق","وَسَطُ الحَلْق","أَقْصَى الحَلْق","الشَّفَتَان"],"arabicOptions":true,"answerIndex":2,"why":"أقصى الحلق, at the vocal cords, sharing its مخرج with الهمزة. أقصى means furthest from the mouth; أدنى, nearest to it."},{"type":"choice","q":"For a هَمْزَة carrying a حركة, what do the vocal cords do?","bigArabic":"ء","options":["Stay sealed throughout","Seal, then part","Stay wide apart throughout","Part, then seal"],"answerIndex":1,"why":"Sākinah, the closure of the cords is the whole letter and the sound stops dead. With a حركة the cords seal and then release, and the release lets the vowel out."},{"type":"choice","q":"A reader empties his lungs on فِيهِ and still no هاء is heard. What should he have done with the cords?","ayah":"لَا رَيْبَ فِيهِ","ref":"Sūrat al-Baqarah 2:2","options":["Opened them only partially","Shut them completely","Opened them as wide as possible","Sealed and released them, as for a همزة"],"answerIndex":0,"why":"الهاء is انفتاح جزئي - the cords part but stay close. Fling them wide and the air escapes in one gust: much effort, no letter. Held close, the breath still flows - الهاء is مهموسة, so النفس must run - but it flows through a narrow gap instead of being dumped in one gust, so فِيهِ sounds easily without emptying the lungs."},{"type":"choice","q":"Why is العين neither رخو nor شديد?","bigArabic":"ع","options":["Its مخرج closes completely","Its مخرج narrows but does not close","Its مخرج stays wide open","Its مخرج shifts while you say it"],"answerIndex":1,"why":"لسان المزمار pulls back toward the throat wall and squeezes the مخرج without sealing it, so the sound neither runs on nor is cut dead. العين is one of the letters of لِنْ عُمَرْ."},{"type":"choice","q":"الحاء shares وسط الحلق with العين. What does لسان المزمار do differently for it?","bigArabic":"ح","options":["It seals the مخرج","It draws back less, leaving the مخرج much wider","It presses back until the مخرج is squeezed nearly shut","It lifts against the soft palate"],"answerIndex":1,"why":"Same مخرج, less narrowing: لسان المزمار does not draw back as far, so the gap stays wide enough for the sound to keep running - رخو. Say أَعْ then أَحْ and feel the extra room for الحاء."},{"type":"multi","q":"Tap the two letters of أَدْنَى الحَلْق.","pool":["ء","ه","ع","ح","غ","خ"],"answers":["غ","خ"],"why":"أدنى means nearest the mouth - the outermost slice of the throat, where جذر اللسان (further back than أقصى اللسان, where القاف is) approaches the soft palate by اللهاة. Still counted as a throat مخرج, not a tongue one. They are the last two of the six."},{"type":"choice","q":"Of these four, which letter is closest to the mouth?","options":["ء","ح","غ","خ"],"arabicOptions":true,"answerIndex":3,"why":"Running deepest to nearest - ء ه ع ح غ خ - الخاء is the last of the six, just a little higher than الغين."},{"type":"choice","q":"Which of these is NOT a throat letter?","options":["ق","غ","ح","ء"],"arabicOptions":true,"answerIndex":0,"why":"القاف is أقصى اللسان, one notch past أدنى الحلق: the first of the tongue's مخارج, not a throat letter. غ and خ, just behind it, are still counted حلقية."},{"type":"choice","q":"Some early scholars counted seven throat letters, not six. Which letter did they add?","options":["اليَاء","القَاف","الأَلِف","الكَاف"],"arabicOptions":true,"answerIndex":2,"why":"سيبويه placed the ألف at أقصى الحلق, giving seven; الخليل assigned it to الجوف, leaving six - and the Jazariyyah follows الخليل. Nothing in recitation turns on the choice."}],"_issues":0,"_state":"verified","url":"https://www.youtube.com/watch?v=2BFpfzbBBVo&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=4"},{"ep":5,"title_en":"Father of the Letters","title_ar":"بَابُ مَخَارِجِ الحُرُوفِ ـ اللِّسَان","summary":"Which letters come off the tongue, and exactly where does each one strike?","teach":[{"label_en":"Father of letters","title_ar":"اللِّسَان","count":"18 letters - first 9 here","letters":"ق ك ج ش ي ض ل ن ر","body":"Eighteen of the 29 letters come off the tongue - more than the throat, the lips and الجوف put together. This lesson takes the first nine.","tone":"brand"},{"label_en":"The far back","title_ar":"أَقْصَى اللِّسَان","letters":"ق ك","body":"القاف is the deepest letter of the tongue, its back rising to the fleshy palate (الحنك اللحمي). الكاف sits just in front of it and a little lower, its contact reaching the bony palate too - which is why dialects slide so easily from one to the other.","tone":"stop"},{"label_en":"The middle","title_ar":"وَسَط اللِّسَان","letters":"ج ش ي","body":"One مخرج, three degrees of opening: الجيم seals shut, الشين opens and the air spreads (تفشي), الياء opens wider still.","tone":"flow"},{"label_en":"Edge and tip","title_ar":"حَافَة اللِّسَان وطَرَفُه","letters":"ض ل ن ر","body":"الضاد presses from the tongue's edge against the upper molars. Then the tip: اللام from the edge to the very end of the tip, النون a little below it with غنة, الراء neighbouring النون but set deeper.","tone":"between"}],"questions":[{"type":"choice","q":"القاف - where does it strike?","bigArabic":"ق","options":["وَسَطُ اللِّسَانِ","طَرَفُ اللِّسَانِ","أَقْصَى اللِّسَانِ مَعَ الحَنَكِ اللَّحْمِيِّ","حَافَةُ اللِّسَانِ"],"answerIndex":2,"arabicOptions":true,"why":"القاف is the deepest letter of the tongue: the back of the tongue rises to the soft, fleshy palate. Nothing on the tongue lies further back - from here on, every letter moves forward."},{"type":"choice","q":"So what actually separates الكاف from القاف?","options":["الكاف is from وسط اللسان","الكاف is slightly further forward and lower, and its contact reaches the bony palate as well","الكاف is on the identical spot and differs only in صفة","الكاف is from the throat"],"answerIndex":1,"why":"بيت 12 (عجز): «أَقْصَى اللِّسَانِ فَوْقُ، ثُمَّ الكَافُ» - and بيت 13 opens with «أَسْفَلُ»: the كاف sits lower. Next-door neighbours, which is how whole regions come to swap one for the other in speech - but the Qur'an is taken by تلقٍّ from a teacher, never from local dialect."},{"type":"choice","q":"Complete the line of الجزرية.","verseStem":"أَسْفَلُ، وَالوَسْطُ: فَجِيمُ الشِّينُ ...","options":["ضَا","لَا","يَا","رَا"],"answerIndex":2,"arabicOptions":true,"why":"بيت 13 (ترقيم هذه الطبعة): «أَسْفَلُ، وَالوَسْطُ: فَجِيمُ الشِّينُ يَا» - ج، ش، ي all strike وسط اللسان against وسط الحنك الأعلى. The ياء meant here is the consonant; الياء المدية belongs to الجوف."},{"type":"multi","q":"Tap every letter that comes from وسط اللسان.","pool":["ق","ك","ج","ش","ض","ل","ن","ر","ي"],"answers":["ج","ش","ي"],"why":"ج ش ي - one مخرج shared by three letters that sound nothing like each other, because the degree of closure differs every time."},{"type":"choice","q":"Which of those three closes its مخرج completely?","options":["الشِّين","الجِيم","اليَاء","لَا شَيْءَ مِنْهَا"],"answerIndex":1,"arabicOptions":true,"why":"الجيم is شديدة - ابن الجزري counts it in «أَجِدْ قَطٍ بَكَتْ» - so the مخرج seals and the sound is cut. Try to produce that hardness with the tip of the tongue instead of its middle and a دال starts leaking into the ج."},{"type":"choice","q":"التفشي of the ش - in which word do you hear it more clearly?","options":["شَاكِرٌ","تَشْكُرُونَ"],"answerIndex":1,"arabicOptions":true,"why":"A ساكن letter holds its صفات longest, so the spread of air across the mouth is plainest on the ش of تَشْكُرُونَ. In شَاكِرٌ the ش hands straight over to its vowel and the صفة barely has room to show - true of صفات generally, not just التفشي."},{"type":"choice","q":"الضاد - where must the pressure and the lean fall?","bigArabic":"ض","options":["طَرَفُ اللِّسَانِ مَعَ اللِّثَةِ","وَسَطُ اللِّسَانِ","مُقَدَّمُ اللِّسَانِ مَعَ الثَّنَايَا","حَافَةُ اللِّسَانِ مَعَ الأَضْرَاسِ العُلْيَا"],"answerIndex":3,"arabicOptions":true,"why":"من حافة اللسان اليمنى أو اليسرى أو منهما معاً مع ما يحاذيها من الأضراس العليا. The front of the tongue does make contact - but it is not where you lean. Lean there and what comes out is a heavy دال, not a ضاد."},{"type":"choice","q":"الضاد is given both رخاوة and استطالة. Which is which?","ayah":"غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ","ref":"Sūrat al-Fātiḥa 1:7","options":["استطالة is the sound running on; رخاوة is the tongue travelling forward","They are two names for one thing","رخاوة is the sound running on; استطالة is the tongue travelling forward along the مخرج","استطالة means holding the letter for two counts"],"answerIndex":2,"why":"الرخاوة للصوت والاستطالة للمخرج. The sound never stops - so the ض of ٱلضَّآلِّينَ must not have a pocket of silence punched into it - while the tongue itself travels forward along its مخرج."},{"type":"choice","q":"Complete the line of الجزرية.","verseStem":"وَاللَّامُ: أَدْنَاهَا ...","options":["مَعَ الخَيْشُومِ","لِمُنْتَهَاهَا","إِلَى أَقْصَاهَا","فَوْقَ الثَّنَايَا"],"answerIndex":1,"arabicOptions":true,"why":"بيت 14: «وَاللَّامُ: أَدْنَاهَا لِمُنْتَهَاهَا» - from the nearest point of the tongue's two edges right to the end of its tip, against the gum above. The way forward is blocked, so the sound escapes right and left: that is الانحراف - a deviation of the صوت, not of the tongue."},{"type":"choice","q":"النون is two jobs joined into one letter. Which two?","options":["طرف اللسان alone, striking the gum","The two lips, plus a غنة from الخيشوم","طرف اللسان striking the gum, plus a غنة from الخيشوم","أقصى اللسان, plus a غنة from الخيشوم"],"answerIndex":2,"why":"بيت 15: «وَالنُّونُ: مِنْ طَرَفِهِ تَحْتُ اجْعَلُوا» - the tip strikes the gum a little below the مخرج of اللام, and the sound finishes through the nose as غنة. In النون المظهرة the two halves work together. (Later, in الإخفاء and الإدغام بغنة, the tongue's contact drops away and only the غنة remains - the نون is then from الخيشوم alone.)"},{"type":"choice","q":"The tongue-tip strikes for الراء as well - so why has الراء not become a شديد letter?","bigArabic":"ر","options":["Because it carries a غنة, like النون","The tongue hollows as it strikes, leaving a gap in the middle that a thin stream of sound passes through","Because its real مخرج is in the throat","Because it is one of حروف المد"],"answerIndex":1,"why":"Seal that little channel and the مخرج would shut and الراء would turn شديدة; it is in fact متوسطة, one of «لِنْ عُمَرْ» (بيت 22). التكرير is a صفة the راء carries by nature - بيت 26 counts it among its صفات - but it is known in order to be restrained: one contact, not a roll."},{"type":"choice","q":"Complete the line of الجزرية.","verseStem":"وَأَخْفِ تَكْرِيراً إِذَا ...","ayah":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ","ref":"Sūrat al-Fātiḥa 1:1","options":["تُرَقَّقُ","تُفَخَّمُ","تُسَكَّنُ","تُشَدَّدُ"],"answerIndex":3,"arabicOptions":true,"why":"بيت 43: «وَأَخْفِ تَكْرِيراً إِذَا تُشَدَّدُ». A مشددة راء is two راءات - ساكنة then متحركة - so the urge to rattle doubles exactly there. Hold each ر of ٱلرَّحْمَٰنِ ٱلرَّحِيمِ firm and keep the tremble hidden, never a roll."}],"_issues":0,"_state":"verified","url":"https://www.youtube.com/watch?v=vwaWWcV0Z5M&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=5"},{"ep":6,"title_en":"Tip, Lips, Nose","title_ar":"مخارج طرف اللسان والشفتين والخيشوم","summary":"If ط، د and ت all leave the very same مخرج, why is only ط heavy - and what is left to make once the tongue's eighteen letters are done?","teach":[{"label_en":"Three at a time","title_ar":"ثلاثةٌ من مخرجٍ واحد","count":"3 trios","letters":"ط د ت | ص س ز | ظ ذ ث","body":"Each trio leaves one single مخرج: ط د ت at أصول الثنايا العليا, ص س ز just above الثنايا السفلى, ظ ذ ث on أطراف الثنايا العليا.","tone":"stop"},{"label_en":"One heavy in each","title_ar":"الاستعلاء","count":"1 per trio","letters":"ط ص ظ","body":"In every trio exactly one letter is مفخّم: أقصى اللسان lifts toward the roof of the mouth (استعلاء). All three are also مطبقة - بيت ٢٣: وَصَادُ ضَادٌ طَاءُ ظَاءٌ: مُطْبَقَهْ. The other two stay مستفل with the identical tongue tip.","tone":"brand"},{"label_en":"The two lips","title_ar":"الشفتان","count":"4 letters (3 named in بيت ١٩)","letters":"ف و ب م","mnemonic":"لِلشَّفَتَيْنِ: الوَاوُ بَاءٌ مِيمُ","body":"ف is named a line earlier - بيت ١٨: وَمِنْ بَطْنِ الشَّفَهْ … فَالْفَا - the inside of the lower lip against the tips of the upper ثنايا. و (غير المدية) rounds the lips forward; ب and م shut them. الواو المدية is a جوف letter.","tone":"flow"},{"label_en":"The nose","title_ar":"الخيشوم","count":"ن and م only","letters":"ن م","mnemonic":"وَغُنَّةٌ: مَخْرَجُهَا الخَيْشُومُ","body":"الغنة is sound from the nasal cavity, built into ن and م in every state they take. No other Arabic letter carries it.","tone":"between"}],"questions":[{"type":"choice","q":"ط، د and ت all come out of one and the same مخرج. Which one?","options":["طرف اللسان مع أصول الثنايا العليا","طرف اللسان مع أطراف الثنايا العليا","طرف اللسان مع فوق الثنايا السفلى","حافة اللسان مع الأضراس"],"answerIndex":0,"arabicOptions":true,"why":"أصول الثنايا العليا - the roots of the upper front teeth, where they meet the gum. بيت ١٦: وَالطَّاءُ وَالدَّالُ وَتَا: مِنْهُ وَمِنْ … عُلْيَا الثَّنَايَا. The three wrong options are ظ ذ ث، ص س ز and الضاد."},{"type":"choice","q":"ط and ت share that مخرج exactly. So what makes ط heavy?","bigArabic":"ط","options":["The tongue tip moves further back","أقصى اللسان rises toward the roof of the mouth (استعلاء)","The lips round slightly","The upper teeth press harder"],"answerIndex":1,"why":"Tip and teeth are identical in ط and ت. What makes ط heavy is استعلاء - أقصى اللسان lifts toward the palate - reinforced by إطباق, the tongue body closing on the roof of the mouth (ط is one of the four مطبقة: ص ض ط ظ). ط is not simply a heavy ت: ط is مجهور and carries قلقلة (قُطْبُ جَدٍ), ت is مهموس with none."},{"type":"multi","q":"Tap the heavy (مفخّم) letter out of each of the three trios.","pool":["ط","د","ت","ص","س","ز","ظ","ذ","ث"],"answers":["ط","ص","ظ"],"why":"One per trio and never two: ط from ط د ت، ص from ص س ز، ظ from ظ ذ ث. Same tongue tip, same teeth as their neighbours - أقصى اللسان is what makes one of each three heavy. (The trio-mates differ in other صفات too: ت is مهموس and has no قلقلة, ز is مجهور, ث is مهموس.)"},{"type":"choice","q":"Finish the hemistich from بيت ١٧ of the Jazariyyah.","verseStem":"وَالظَّاءُ وَالذَّالُ وَثَا: ____","options":["لِلْعُلْيَا","لِلسُّفْلَى","لِلَّهَاةِ","لِلْأَضْرَاسِ"],"answerIndex":0,"arabicOptions":true,"why":"لِلْعُلْيَا - the upper ثنايا. بيت ١٨ adds مِنْ طَرَفَيْهِمَا: tip of tongue on tip of tooth, edge to edge - neither tucked back inside the mouth nor pushed out past the lips."},{"type":"choice","q":"ص، س and ز are formed against which teeth?","options":["فوق الثنايا السفلى","أصول الثنايا العليا","أطراف الثنايا العليا","الأضراس"],"answerIndex":0,"arabicOptions":true,"why":"The tip drops to the inner face just above the lower incisors - بيت ١٧: مِنْهُ وَمِنْ فَوْقِ الثَّنَايَا السُّفْلَى. These same three are حروف الصفير, the whistling letters."},{"type":"choice","q":"How many letters in total issue from اللسان?","options":["10","15","17","18"],"answerIndex":3,"why":"Eighteen: ق، ك، ج ش ي، ض، ل، ن، ر، ط د ت، ص س ز، ظ ذ ث - from ten مخارج on the tongue (ق and ك are two of them, not one). Seventeen counts مخارج, not letters, and not the mouth alone: مَخَارِجُ الحُرُوفِ سَبْعَةَ عَشَرْ (بيت ٩) - الجوف ١، الحلق ٣، اللسان ١٠، الشفتان ٢، الخيشوم ١."},{"type":"choice","q":"Which two surfaces make ف?","bigArabic":"ف","options":["باطن الشفة السفلى مع أطراف الثنايا العليا","ظاهر الشفة السفلى مع أطراف الثنايا العليا","انطباق الشفتين","انضمام الشفتين إلى الأمام"],"answerIndex":0,"arabicOptions":true,"why":"الباطن - the inner side of the lower lip, the part you cannot see when the mouth is shut normally. بيت ١٨: وَمِنْ بَطْنِ الشَّفَهْ … فَالْفَا مَعَ اطْرَافِ الثَّنَايَا المُشْرِفَهْ. The last two options describe ب/م and و."},{"type":"multi","q":"Tap every letter whose مخرج is the lips.","pool":["ف","و (غير المدية)","ب","م","ث","ن"],"answers":["ف","و (غير المدية)","ب","م"],"why":"Four. بيت ١٩ names three - لِلشَّفَتَيْنِ: الوَاوُ بَاءٌ مِيمُ - with ف named the line before. The و meant here is الواو غير المدية; الواو المدية is a جوف letter (unit 3). ن is a tongue letter - it shares غنة with م but not a مخرج."},{"type":"choice","q":"ب and م both shut the lips completely. What separates them?","options":["م adds غنة from الخيشوم","م closes the lips more firmly","ب is مفخّم and م مرقّق","م uses the lower lip only"],"answerIndex":0,"why":"The closure is the same. In م the sound divides at the lips: part is stopped there, part runs on out through the nose - بيت ١٩: وَغُنَّةٌ: مَخْرَجُهَا الخَيْشُومُ. That escape is why ب is شديد with قلقلة (قُطْبُ جَدٍ) while م is متوسطة (لِنْ عُمَرْ)."},{"type":"choice","q":"الجمهور settled the question: is الغنة a حرف or a صفة?","options":["حرف - it has its own مخرج","صفة لازمة of ن and م","Both, in equal measure","Neither; it is a defect to be removed"],"answerIndex":1,"why":"صفة لازمة: it cannot be uttered on its own, only as a quality of ن and م. مكي بن أبي طالب (ت ٤٣٧ هـ) counted it a حرف in الرعاية, arguing from its مخرج الخيشوم (بيت ١٩); الجعبري answered that having a مخرج does not make a sound a حرف."},{"type":"choice","q":"Every ن and every م carries غنة. How many letters in this āya carry it?","ayah":"ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ","ref":"Sūrat al-Fātiḥa 1:2","options":["1","2","3","4"],"answerIndex":2,"why":"Three: the م of ٱلْحَمْدُ, then the م and the ن of ٱلْعَٰلَمِينَ. They are not equal, but none takes the full two-count غنة - that belongs to المشدد، المدغم and المخفى. The م of ٱلْحَمْدُ is إظهار شفوي: its غنة is أكمل مرتبةً than that of the متحرك م and ن, yet it is the natural غنة and must not be stretched."},{"type":"choice","q":"A reciter lets a nasal hum ride on the و of تَعْمَلُونَ and the ي of نَسْتَعِينُ. Is that right?","options":["Yes - they are حروف مد and hum naturally","No - in Arabic غنة belongs to ن and م alone","Only when stopping on the word","Only inside إخفاء"],"answerIndex":1,"why":"غنة sits in ن and م and nowhere else in Arabic - not on و, not on ي, not on ألف. Other languages do nasalize other letters; importing that into recitation is counted عيبًا من عيوب القراءة."}],"_issues":0,"_state":"verified","url":"https://www.youtube.com/watch?v=8zIZQkaySyQ&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=6"},{"ep":7,"title_en":"Voice and Breath","title_ar":"باب صفات الحروف ـ الصفات المتضادَّة","summary":"If the مخرج only tells you where a letter comes from, what tells you how it should sound?","teach":[{"label_en":"Where vs how","title_ar":"المخرج والصفة","body":"The مخرج tells you where a letter leaves the mouth. The صفة tells you how it is made once it gets there.","tone":"brand"},{"label_en":"Two families","title_ar":"صفات متضادة وصفات لا ضد لها","count":"5 pairs + 7","body":"A صفة متضادة has an opposite, and - with one exception - every letter sits on one side of it: مستعلٍ or مستفل, never neither. The exception is الشدة/الرخاوة: «لِنْ عُمَرْ» (ل ن ع م ر) sit between the two. A صفة لا ضد لها belongs to a short list of letters, and the rest are simply not described by it.","tone":"between"},{"label_en":"Ten breathy letters","title_ar":"الهمس","count":"10 letters","mnemonic":"فَحَثَّهُ شَخْصٌ سَكَتْ","letters":"ف ح ث ه ش خ ص س ك ت","body":"Breath runs freely with the letter - جريان النفس, because the مخرج is pressed lightly. Your throat usually will not buzz on these, which makes a quick test. The other 19 of the 29 letters are مجهورة.","tone":"flow"},{"label_en":"Borrowed from صرف","title_ar":"الإذلاق والإصمات","count":"6 letters","mnemonic":"فَرَّ مِنْ لُبِّ","letters":"ف ر م ن ل ب","body":"al-Jazarī lists this pair with the others, but nothing in recitation turns on it. It is a صرف test: a genuine four- or five-letter Arabic root almost always carries at least one of فَرَّ مِنْ لُبِّ.","tone":"stop"}],"questions":[{"type":"choice","q":"The مخرج tells you where a letter comes from. What does the صفة tell you?","options":["How it is made as it leaves - its هيئة","Which part of the mouth it starts in","Whether it can carry a شدة","Which حركة it takes"],"answerIndex":0,"why":"ط، د and ت all leave from one and the same مخرج. Nothing but their صفات keeps them apart - which is why the مخرج alone can never make the letter correct."},{"type":"choice","q":"Every Arabic letter is either مستعلٍ or مستفل. Why can you not say the same about الصفير?","options":["الصفير belongs to some letters only; the rest get no opposing label","الصفير has an opposite, but it is rarely mentioned","الصفير belongs to علم الصرف","الصفير applies only when the letter is ساكن"],"answerIndex":0,"why":"ص، ز and س are حروف الصفير. The other letters are not the opposite of صفير - there is no opposite to be. That is exactly what صفة لا ضد لها means."},{"type":"choice","q":"Why does this chapter set الإذلاق والإصمات aside?","options":["They belong to علم الصرف and change nothing in how a letter sounds","They apply only to letters that appear in the Qur'an","They were added to the poem by later scholars","They matter only when you stop on a word"],"answerIndex":0,"why":"الإذلاق is a صرف test: a genuine Arabic root of four or five letters almost always carries at least one of فَرَّ مِنْ لُبِّ. None of that reaches the ear, so it is not something a reciter can get wrong."},{"type":"choice","q":"Complete the line from المقدمة الجزرية.","verseStem":"وَ «فَرَّ مِنْ لُبِّ»: الحُرُوفُ ______","options":["المُذْلَقَهْ","المُطْبَقَهْ","المَهْمُوسَهْ","المُسْتَعْلِيَهْ"],"arabicOptions":true,"answerIndex":0,"why":"The first half of the very same بيت names a different corner entirely: وَصَادُ ضَادٌ طَاءُ ظَاءٌ: مُطْبَقَهْ. Two unrelated صفات in one line - al-Jazarī packs tightly."},{"type":"choice","q":"Complete the line from المقدمة الجزرية.","verseStem":"مَهْمُوسُهَا: ______","options":["فَرَّ مِنْ لُبِّ","أَجِدْ قَطٍ بَكَتْ","فَحَثَّهُ شَخْصٌ سَكَتْ","خُصَّ ضَغْطٍ قِظْ"],"arabicOptions":true,"answerIndex":2,"why":"The full بيت: مَهْمُوسُهَا: «فَحَثَّهُ شَخْصٌ سَكَتْ» … شَدِيدُهَا: لَفْظُ «أَجِدْ قَطٍ بَكَتْ». Each of the other three phrases collects a صفة of its own - المذلقة، الشديدة، الاستعلاء."},{"type":"multi","q":"Tap every مهموس letter.","pool":["ب","ت","ج","ح","د","ش","ع","ك","م","ن"],"answers":["ت","ح","ش","ك"],"why":"فَحَثَّهُ شَخْصٌ سَكَتْ - ف ح ث ه ش خ ص س ك ت. The other six are not in that list, so they are مجهورة."},{"type":"choice","q":"مهموس or مجهور?","bigArabic":"ص","options":["مهموس","مجهور"],"arabicOptions":true,"answerIndex":0,"why":"ص sits inside فَحَثَّهُ شَخْصٌ سَكَتْ, so it is مهموس - breath runs with it. That it is also مطبق and مستعلٍ changes nothing: صفات stack on one letter, they do not cancel each other."},{"type":"choice","q":"Say a letter ساكن with a hand on your throat. A clear vibration means the letter is:","options":["مهموس","مجهور","مستعلٍ","مُقلقل"],"arabicOptions":true,"answerIndex":1,"why":"الجهر is تضام الوترين الصوتيين واهتزازهما: the cords close in and buzz, and the breath is held back - the early scholars called that buzz صوت الصدر. The test holds for most letters; ق and ط are counted مجهور for the held-back breath even though they do not buzz as recited today."},{"type":"multi","q":"Tap every مجهور letter.","pool":["س","ز","ت","د","خ","غ","ه","ي"],"answers":["ز","د","غ","ي"],"why":"س/ز، ت/د، خ/غ each share one مخرج, and the vocal cords are what separate them. Hand on the throat: ز، د، غ shake it; س، ت، خ do not."},{"type":"choice","q":"How many مهموس letters are in this āya?","ayah":"كَلَّا سَوْفَ تَعْلَمُونَ","ref":"Sūrat al-Takāthur 102:3","options":["2","3","4","5"],"answerIndex":2,"why":"ك، س، ف، ت - four of the ten. The trap is ع: it leaves from وسط الحلق, the same spot as ح, yet ح is مهموس and ع is مجهور."}],"_issues":0,"_state":"verified","url":"https://www.youtube.com/watch?v=aYO2mrrHqPo&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=7"},{"ep":8,"url":"https://www.youtube.com/watch?v=5q5rI3qBLx0&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=8","title_en":"Stopped, Between, Flowing","title_ar":"باب صفات الحروف ـ الشدة والرخاوة والبينية","summary":"With a sukūn on it, does the sound stop, sit between, or flow?","teach":[{"label_en":"Stopped","title_ar":"الشِّدَّة","count":"8 letters","mnemonic":"أَجِدْ قَطٍ بَكَتْ","letters":"ء ج د ق ط ب ك ت","tone":"stop","body":"The mouth shuts completely and the sound is cut off. Say <span class='ar'>أَقْ</span> and try to hold it - you cannot."},{"label_en":"Between","title_ar":"البَيْنِيَّة","count":"5 letters","mnemonic":"لِنْ عُمَرْ","letters":"ل ن ع م ر","tone":"between","body":"Checked, but not killed. For <span class='ar'>ن</span> and <span class='ar'>م</span> the mouth shuts but the <span class='ar'>غنة</span> escapes through the nose - pinch your nose on <span class='ar'>أَمْ</span> and it stops dead."},{"label_en":"Flowing","title_ar":"الرَّخاوة","count":"16 letters","mnemonic":"ما عدا ذلك","letters":"ا ث ح خ ذ ز س ش ص ض ظ غ ف هـ و ي","tone":"flow","body":"No mnemonic needed - <strong>anything in neither phrase above</strong>. Say <span class='ar'>أَسْ</span> and it runs until your breath does."}],"questions":[{"type":"choice","q":"Which category does this letter belong to?","bigArabic":"ق","options":["شديد","بيني","رخو"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>ق</span> is the qāf of <span class='ar'>قَطٍ</span> in <span class='ar'>أَجِدْ قَطٍ بَكَتْ</span>."},{"type":"choice","q":"Which category does this letter belong to?","bigArabic":"ش","options":["شديد","بيني","رخو"],"arabicOptions":true,"answerIndex":2,"why":"In neither mnemonic - so the residual rule makes it <span class='ar'>رخو</span>."},{"type":"choice","q":"Which category does this letter belong to?","bigArabic":"م","options":["شديد","بيني","رخو"],"arabicOptions":true,"answerIndex":1,"why":"The mīm of <span class='ar'>عُمَرْ</span>. Mouth shut, nose open."},{"type":"choice","q":"Which phrase collects the letters of <span class='ar'>الشدة</span>?","options":["أَجِدْ قَطٍ بَكَتْ","فَحَثَّهُ شَخْصٌ سَكَتْ","لِنْ عُمَرْ"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>فَحَثَّهُ شَخْصٌ سَكَتْ</span> is the mnemonic for <span class='ar'>الهمس</span> - it shares the same <span class='ar'>بيت</span>, which is why the two get confused."},{"type":"multi","q":"Tap the five letters of <span class='ar'>البينية</span>.","pool":["ب","ل","ص","ن","ق","ع","ف","م","ت","ر"],"answers":["ل","ن","ع","م","ر"],"why":"<span class='ar'>لِنْ عُمَرْ</span> - ل ، ن ، ع ، م ، ر."},{"type":"choice","q":"How many letters carry <span class='ar'>الشدة</span>?","options":["5","8","10","16"],"answerIndex":1,"why":"Eight - and 8 + 5 + 16 = 29, the whole alphabet counting <span class='ar'>الألف</span> and <span class='ar'>الهمزة</span> separately."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span> from <span class='ar'>المقدمة الجزرية</span>:","verseStem":"وَبَيْنَ رِخْوٍ وَالشَّدِيدِ:","options":["«لِنْ عُمَرْ»","«قُطْبُ جَدٍ»","«خُصَّ ضَغْطٍ قِظْ»"],"arabicOptions":true,"answerIndex":0,"why":"Ibn al-Jazarī names <span class='ar'>البينية</span> by placing it literally <em>between</em> <span class='ar'>رخو</span> and <span class='ar'>شديد</span> in the line itself."},{"type":"choice","q":"<span class='ar'>لِنْ عُمَرْ</span> is a real Arabic sentence. What does it say?","options":["“Be soft, ʿUmar”","“ʿUmar is gentle”","“The softness of ʿUmar”"],"answerIndex":0,"why":"<span class='ar'>لِنْ</span> is an imperative from <span class='ar'>لانَ يَلينُ</span>; <span class='ar'>عُمَرْ</span> a vocative with the particle dropped. ʿUmar was <span class='ar'>شديد</span> by nature - soften him and he lands between. The mnemonic encodes its own answer."},{"type":"choice","q":"The six <span class='ar'>حروف الحلق</span> share one region of the throat. Which one is <span class='ar'>بينية</span>?","options":["ء","هـ","ع","خ"],"arabicOptions":true,"answerIndex":2,"why":"One <span class='ar'>مخرج</span> region, all three categories inside it - proof that this <span class='ar'>صفة</span> is decided by closure, never by location."},{"type":"choice","q":"How many <span class='ar'>شديد</span> letters are in this āya?","ayah":"وَٱلْعَصْرِ","ref":"Sūrat al-ʿAṣr 103:1","options":["0","1","2","3"],"answerIndex":0,"why":"None. Its letters are <span class='ar'>و ل ع ص ر</span> - and three of those (<span class='ar'>ل ع ر</span>) are from <span class='ar'>لِنْ عُمَرْ</span>."},{"type":"choice","q":"<span class='ar'>ن</span> and <span class='ar'>م</span> shut the mouth completely. So why are they not <span class='ar'>شديد</span>?","options":["The غنة still flows out through the nose","They are pronounced too softly","Their مخرج is not a true closure"],"answerIndex":0,"why":"Two paths at once: the oral <span class='ar'>مخرج</span> is shut, but the <span class='ar'>خيشوم</span> stays open. Neither half describes the letter alone."},{"type":"choice","q":"Stop at the end of this āya. Which letter takes <span class='ar'>قلقلة</span>?","ayah":"أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ","ref":"Sūrat ash-Sharḥ 94:1","options":["the د","the final ك","both","neither"],"answerIndex":0,"why":"<span class='ar'>د</span> is <span class='ar'>شديدة + مجهورة</span> - sound trapped and breath trapped, so it needs the small release. The <span class='ar'>ك</span> is <span class='ar'>شديدة + مهموسة</span>: its breath already escapes. Qalqala is for <span class='ar'>قُطْبُ جَدٍ</span> only, not every <span class='ar'>شديد</span> letter."}],"_state":"verified"},{"ep":9,"title_en":"The Letter Clock","title_ar":"قياس أزمنة الحروف الصحيحة","summary":"How long should each letter be held, and which letters must come out exactly equal?","teach":[{"label_en":"Moving letters","title_ar":"أزمنة الحروف المتحركة","body":"Every letter carrying a ḥaraka takes the same time as the one beside it - شديد or رخو, fatḥa or ḍamma or kasra makes no difference. That equality holds inside one pace of reading: التحقيق (slow), التدوير (middle), الحدر (fast).","tone":"brand"},{"label_en":"Sākin letters","title_ar":"أزمنة الحروف الساكنة","count":"3 ranks","body":"A sākin letter is held in proportion to the sound running through it: رخو longest, بيني in the middle, شديد shortest. Speed up and every number shrinks, but the ratio between the three never changes. This clock measures الحروف الصحيحة only - حروف المد واللين are counted in ḥarakāt instead.","tone":"flow"},{"label_en":"In between","title_ar":"الحروف البينية","count":"5 letters","mnemonic":"لِنْ عُمَرْ","letters":"ل ن ع م ر","body":"Part flow, part stop. Sākin, they are held shorter than a رخو letter and longer than a شديد one - never snapped off like د, never drawn out like ش.","tone":"between"},{"label_en":"Two faults","title_ar":"التمطيط والاختلاس","body":"Dragging one ḥaraka out past its neighbours is التمطيط (some scholars also call it الإدخال); snatching one short - and a shade quieter - is الاختلاس. Both break the evenness the ḥaraka is supposed to guarantee.","tone":"stop"}],"questions":[{"type":"choice","q":"This chapter was called one of the most important in تجويد. What makes it so?","options":["It concerns only حروف المد","It changes the meaning of words","It is measured on every single letter","It concerns only the seven حروف الاستعلاء"],"answerIndex":2,"why":"Scope. التفشي concerns ش alone, الاستطالة ض alone, الصفير only three letters (ص ز س) - but timing is weighed on every letter that leaves your mouth."},{"type":"choice","q":"Complete the line of الجزرية.","verseStem":"وَبَيْنَ رِخْوٍ وَالشَّدِيدِ: ‹‹ ____ ››","options":["أَجِدْ قَطٍ بَكَتْ","لِنْ عُمَرْ","فَرَّ مِنْ لُبِّ","قُطْبُ جَدٍ"],"arabicOptions":true,"answerIndex":1,"why":"لِنْ عُمَرْ gathers ل ن ع م ر, the بينية letters. أَجِدْ قَطٍ بَكَتْ is the شديد set, قُطْبُ جَدٍ the قلقلة set, and فَرَّ مِنْ لُبِّ the مذلقة."},{"type":"choice","q":"In the word خَلَقَكُمْ, how many letters must come out equal in length?","ayah":"ٱلَّذِى خَلَقَكُمْ","ref":"Sūrat al-Baqara 2:21","bigArabic":"خَلَقَكُمْ","options":["2","3","4","5"],"answerIndex":2,"why":"خَ، لَ، قَ، كُ - four ḥarakāt, four equal times, even though خ is رخو, ل is بيني and ق، ك are شديد. The ḥaraka levels them all; only the final sākin م is measured by another rule."},{"type":"choice","q":"Of these four sākin letters, which is held for the SHORTEST time?","ayah":"أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ","ref":"Sūrat ash-Sharḥ 94:1","options":["الميم في أَلَمْ","الشين في نَشْرَحْ","الدال في صَدْرَكَ","الحاء في نَشْرَحْ"],"arabicOptions":true,"answerIndex":2,"why":"د is شديد - the مخرج is shut and no sound escapes, so there is nothing to hold. ش and ح are رخو (the longest, and equal to each other), and م is بيني, sitting between the two."},{"type":"multi","q":"Sūrat ash-Sharḥ. Tap every letter here that is رخو - the ones given the longest hold when sākin.","pool":["ش","ح","ز","ه","غ","م","ع","د","ك"],"answers":["ش","ح","ز","ه","غ"],"why":"نَشْ، رَحْ، وِزْ، ظَهْ (the هـ)، فَرَغْ - in each one the sākin letter keeps its sound running, so all five take the same long hold. م and ع are بيني (لِنْ عُمَرْ); د and ك are شديد and shut off at once."},{"type":"choice","q":"A reciter drags the fatḥa on the م of فَمَن until it almost turns into an ألف. Name the fault.","ayah":"فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ","ref":"Sūrat az-Zalzala 99:7","options":["الِاخْتِلَاس","الْقَلْقَلَة","الْغُنَّة","التَّمْطِيط"],"arabicOptions":true,"answerIndex":3,"why":"التمطيط, which some scholars also call الإدخال: a ḥaraka given more time than the ḥarakāt around it. Pushed far enough a fatḥa becomes ألف, a ḍamma واو, a kasra ياء - كُنْتُمْ drifts into كُونْتُمْ."},{"type":"choice","q":"الاختلاس snatches a ḥaraka short. What else marks the snatched letter?","options":["It gains a قلقلة","It comes out slightly quieter than its neighbours","It is dropped entirely","It is lengthened at the end instead"],"answerIndex":1,"why":"The scholars described it as speed together with a small lowering of the voice - the letter is both quicker and a shade softer than the letters around it. It is the mirror image of التمطيط."},{"type":"choice","q":"Snatching the ḍamma on the ر of يَأْمُرُكُمْ so it is shorter than its neighbours. In حفص عن عاصم, this is:","ayah":"إِنَّ ٱللَّهَ يَأْمُرُكُمْ","ref":"Sūrat an-Nisāʾ 4:58","options":["A mistake - give the ḍamma in full","Required","Optional","Required only when stopping"],"answerIndex":0,"why":"That اختلاس is a genuine transmitted reading - but it belongs to أبو عمرو البصري, not to حفص. Read the riwāya you are actually reading: in حفص each ḥaraka of يَأْمُرُكُمْ is given whole and equal."},{"type":"choice","q":"Two fatḥas should be equal in length. Equal within what?","options":["Across التحقيق، التدوير and الحدر alike","Within one word only","Within one āya only","Within one مرتبة of reading speed"],"answerIndex":3,"why":"التحقيق، التدوير، الحدر - each pace is a world of its own. A fatḥa in الحدر really is shorter than a fatḥa in التحقيق; what never changes is the ratio between رخو، بيني and شديد."},{"type":"choice","q":"ابن الجزري defines تجويد as «إِعْطَاءُ الحُرُوفِ حَقَّهَا … مِنْ صِفَةٍ لَهَا وَمُسْتَحَقَّهَا». Which word covers how long you hold a رخو letter?","options":["حَقَّهَا","مُسْتَحَقَّهَا","حَرَكَتَهَا","مَخْرَجَهَا"],"arabicOptions":true,"answerIndex":1,"why":"حق is the صفة the letter owns - رخاوة، شدة، همس. مستحق is what that صفة then demands of you: رخاوة demands a longer hold, شدة a shorter one, بينية something between."},{"type":"choice","q":"Complete the line of الجزرية.","verseStem":"وَرَدُّ كُلِّ وَاحِدٍ لِأَصْلِهِ … وَاللَّفْظُ فِي نَظِيرِهِ ____","options":["كَشَكْلِهِ","بِمِثْلِهِ","كَمِثْلِهِ","عَلَى مَحَلِّهِ"],"arabicOptions":true,"answerIndex":2,"why":"Like is pronounced like like. In بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ the س of بِسْمِ and the ح of ٱلرَّحْمَٰنِ are both رخو and both sākin - so both are held for exactly the same time."},{"type":"choice","q":"Two sākin letters open this āya: the ل of ٱلْـ and the م of ٱلْحَمْدُ. Which is held longer?","ayah":"ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ","ref":"Sūrat al-Fātiḥa 1:2","options":["Exactly equal","The ل","The م","The ل only when stopping"],"answerIndex":0,"why":"Both ل and م come from لِنْ عُمَرْ, so both are بيني and both take the same hold. Give the م its full بيني time - al-ḥam-du, the م audibly held, not al-ḥamdu with the م snapped straight onto the د."}],"_issues":0,"_state":"verified","url":"https://www.youtube.com/watch?v=AZSlZoUfS9Y&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=9"},{"ep":10,"title_en":"Seven That Rise","title_ar":"الاستعلاء والاستفال","summary":"Why seven letters of the alphabet come out thick, and what decides how thick.","teach":[{"label_en":"Seven rise","title_ar":"الِاسْتِعْلَاء","count":"7 letters","mnemonic":"خُصَّ ضَغْطٍ قِظْ","letters":"خ ص ض غ ط ق ظ","body":"With these seven the back of the tongue drives the sound up to قبة الحنك, the dome of the palate. Of the twenty-nine letters in tajwīd's count, the other twenty-two are مستفلة - the sound runs straight out of the mouth.","tone":"brand"},{"label_en":"Thick","title_ar":"التَّفْخِيم","body":"A fatness that fills the mouth with the letter's echo, produced by the back of the tongue rising until it narrows the mouth and the sound strikes that dome - a thumb over a hose makes the water shoot further. You never add it: it is the مستحق that الاستعلاء earns.","tone":"stop"},{"label_en":"Thin","title_ar":"التَّرْقِيق","body":"No narrowing, no echo: the sound leaves the mouth without ever reaching the dome. It is the مستحق of الاستفال, so كَا stays thin - ألف and all.","tone":"flow"},{"label_en":"Five ranks","title_ar":"مَرَاتِبُ التَّفْخِيم","count":"5 ranks","body":"Ibn al-Jazarī graded تفخيم from heaviest down: مفتوح بعده ألف، مفتوح، مضموم، ساكن، مكسور. Even the bottom rank is heavier than any مستفل letter.","tone":"between"}],"questions":[{"type":"multi","q":"Tap the seven حروف الاستعلاء. Each is paired here with a letter it is easy to confuse it with.","pool":["خ","ح","ص","س","ض","د","غ","ع","ط","ت","ق","ك","ظ","ذ"],"answers":["خ","ص","ض","غ","ط","ق","ظ"],"why":"خ ص ض غ ط ق ظ - the letters of «خُصَّ ضَغْطٍ قِظْ». Each is paired above with a thin letter learners regularly swap it for: ح س د ع ت ك ذ all stay مستفلة."},{"type":"choice","q":"Complete the line that gathers them.","verseStem":"وَبَيْنَ رِخْوٍ وَالشَّدِيدِ: «لِنْ عُمَرْ» … وَسَبْعُ عُلْوٍ: «ـــــ» حَصَرْ","options":["خُصَّ ضَغْطٍ قِظْ","قُطْبُ جَدٍ","أَجِدْ قَطٍ بَكَتْ","فَحَثَّهُ شَخْصٌ سَكَتْ"],"arabicOptions":true,"answerIndex":0,"why":"وَسَبْعُ عُلْوٍ: «خُصَّ ضَغْطٍ قِظْ» حَصَرْ - seven, and حَصَرْ means he shut the door on any eighth. The other three are the mnemonics for قلقلة, شدة and همس."},{"type":"choice","q":"So how many letters are مستفلة?","options":["21","22","23","28"],"answerIndex":1,"why":"Twenty-nine letters in all, seven of them مستعلية, so 22 مستفلة. الاستفال is the default state of the alphabet; الاستعلاء is the short list you memorise."},{"type":"choice","q":"The ق is مستعلية, and it comes out مفخّمة. What is that تفخيم to the ق?","options":["حقّها","مستحقّها","مخرجها","ضدّها"],"arabicOptions":true,"answerIndex":1,"why":"الاستعلاء is the qāf's حق - a صفة it carries whether you like it or not. التفخيم is its مستحق, what that صفة earns it. You do not thicken the qāf; you raise the sound to the dome and the thickness follows."},{"type":"choice","q":"Classify this letter.","bigArabic":"غ","options":["مستعلٍ مطبق","مستعلٍ منفتح","مستفل مطبق","مستفل منفتح"],"answerIndex":1,"why":"غ is in خُصَّ ضَغْطٍ قِظْ, so مستعلٍ - but it is not one of the four مطبقة (ص ض ط ظ), so it is منفتح. The third option can never describe any letter: every مطبق is also مستعلٍ."},{"type":"choice","q":"Complete the line on تفخيم.","verseStem":"وَحَرْفَ الِاسْتِعْلَاءِ فَخِّمْ، وَاخْصُصَا … الإِطْبَاقَ ـــــ؛ نَحْوُ: «قَالَ» وَ «العَصَا»","options":["أَقْوَى","أَخَفَّ","أَدْنَى","أَرَقَّ"],"arabicOptions":true,"answerIndex":0,"why":"Thicken all seven - then single out the four مطبقة as stronger still. إطباق clamps the tongue flat against the palate on top of the rise, which is why the ص of العَصَا outweighs a خ."},{"type":"choice","q":"Counting every occurrence, how many حروف استعلاء are in this āya?","ayah":"قَالُوا۟ رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْمًۭا ضَآلِّينَ","ref":"Sūrat al-Muʾminūn 23:106","options":["3","4","5","6"],"answerIndex":2,"why":"Five: ق three times, plus غ and the ض of ضَآلِّينَ - the heaviest of them, being مستعلٍ and مطبق together. The ع of عَلَيْنَا counts for nothing: depth in the throat is not الاستعلاء."},{"type":"choice","q":"Of these two, only the ك has an ألف after it. Which one is مفخّم - the ك of كَانُوا or the ق of قَلِيلًا?","ayah":"كَانُوا۟ قَلِيلًۭا مِّنَ ٱلَّيْلِ مَا يَهْجَعُونَ","ref":"Sūrat adh-Dhāriyāt 51:17","options":["الكاف","القاف","كلاهما","لا وَاحِدَ مِنْهُمَا"],"arabicOptions":true,"answerIndex":1,"why":"An ألف is never a source of تفخيم - it simply follows the letter before it, so كَا is thin ألف and all. The qāf is thick with no ألف behind it at all; an ألف would only give it room to spread, as in قَالَ."},{"type":"choice","q":"Ibn al-Jazarī graded التفخيم in his كتاب التمهيد. How many ranks did he list?","options":["3","4","5","7"],"answerIndex":2,"why":"Five: مفتوح بعده ألف، مفتوح بلا ألف، مضموم، ساكن، مكسور. The older scale of أبي الأصبغ ابن الطحّان had three - مفتوح، مضموم، مكسور. Ibn al-Jazarī split the مفتوح by the ألف after it and gave the ساكن a rank of its own."},{"type":"choice","q":"On Ibn al-Jazarī's scale, which qāf is the most مفخّم?","options":["قَالَ","قَدْ","قُلْ","قِيلَ"],"arabicOptions":true,"answerIndex":0,"why":"قَالَ - مفتوح with an ألف after it, the top rank. In قَدْ the fatha has nowhere to spread; you are already on the دال. Splitting قَالَ from قَدْ is one of the two things Ibn al-Jazarī added to the older three-rank scale - the other was giving the ساكن a rank of its own."},{"type":"choice","q":"Where does a ساكن حرف استعلاء sit on Ibn al-Jazarī's scale?","options":["Rank four - its own place, whatever vowel comes before it","It copies the vowel on the letter before it","Always the top rank","It leaves تفخيم altogether"],"answerIndex":0,"why":"For Ibn al-Jazarī يَقْطَعُونَ، سُقْنَاهُ and شِقْوَتُنَا all sit together at rank four. The older مذهب of ابن الطحان - which المتولي put into verse - gives the ساكن no rank of its own and files it under the vowel before it, so شِقْوَتُنَا's qāf drops to the weakest rank. Both are read; the weakest rank is still تفخيم either way."},{"type":"choice","q":"This qāf is مكسور - the bottom rank. Is it مفخّم or مرقّق?","bigArabic":"قِيلَ","options":["مفخّم - the bottom rank of تفخيم is still تفخيم","مرقّق - the kasra thins it","Neither; it sits neutral between the two","مرقّق in وصل, مفخّم in وقف"],"answerIndex":0,"why":"A حرف استعلاء never becomes مرقّق. When a teacher says «رقّق الغين» in غِلّ, what he means is stop exaggerating - at its weakest the letter is still decisively heavier than any مستفل letter. The real fault is the opposite one: rounding a مكسور qāf until قِيلَ starts to sound like قُو."}],"_issues":7,"_state":"verified","url":"https://www.youtube.com/watch?v=xh_MHe1YOdA&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=10"},{"ep":11,"title_en":"Alif, Lām, Rāʾ","title_ar":"حُكْمُ الأَلِفِ وَاللَّامِ وَالرَّاءِ","summary":"Three letters refuse to sit still - so what exactly decides whether each one is thickened or thinned?","teach":[{"label_en":"Three exceptions","title_ar":"المُسْتَفِلُ المُفَخَّمُ","count":"3 letters","letters":"ا ل ر","body":"Every مستعلٍ letter is مفخَّم always. Every مستفل letter is مرقَّق always - except three, which change with what sits around them.","tone":"brand"},{"label_en":"The alif copies","title_ar":"الأَلِفُ تَابِعَةٌ لِمَا قَبْلَهَا","body":"الألف has no ruling of its own: مفخَّمة after a مفخَّم letter, مرقَّقة after a مرقَّق one. Say \"after a مفخَّم\" - not \"after a مستعلٍ\" - because the لام of لفظ الجلالة is مستفل yet مفخَّم.","tone":"flow"},{"label_en":"One agreed lām","title_ar":"لَامُ لَفْظِ الجَلَالَةِ","body":"The لام of الله and اللهم is مفخَّمة when a فتحة or ضمة comes before it, and stays مرقَّقة when a كسرة does. Begin the recitation on ٱللَّه itself and it is مفخَّمة - the ابتداء is on a فتحة. In our reading no other لام is ever thickened.","tone":"between"},{"label_en":"Eight, four, two","title_ar":"أَحْكَامُ الرَّاءِ","count":"8 تفخيم · 4 ترقيق · 2 خُلْف","mnemonic":"الفَتْحُ وَالضَّمُّ لِلتَّفْخِيمِ، وَالكَسْرُ لِلتَّرْقِيقِ","body":"That one sentence is the whole باب. Eight cases thicken the راء, four thin it, and in two the reader may do either.","tone":"stop"}],"questions":[{"type":"multi","q":"All of these letters are مستفلة. Tap the three that can still be مفخَّمة.","pool":["ا","ل","ر","ن","م","ب","و","ي"],"answers":["ا","ل","ر"],"why":"Only ألف، لام، راء move. The rest of the مستفلة are مرقَّقة always, and the seven of «خُصَّ ضَغْطٍ قِظْ» are مفخَّمة always - the degree varies, never the ruling."},{"type":"choice","q":"How is the لام of لفظ الجلالة read here?","ayah":"قُلْ هُوَ ٱللَّهُ أَحَدٌ","ref":"Sūrat al-Ikhlāṣ 112:1","options":["مُفَخَّمَة","مُرَقَّقَة"],"answerIndex":0,"arabicOptions":true,"why":"هُوَ ends in a فتحة, so the لام is مفخَّمة - the one لام the Arabs thicken by إجماع. And since that لام is مفخَّم, the ألف after it is مفخَّمة too, even though لام is a مستفل letter."},{"type":"choice","q":"And the ألف of لفظ الجلالة - the مدّ inside ٱللَّه - here?","ayah":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ","ref":"Sūrat al-Fātiḥah 1:1","options":["مُفَخَّمَة","مُرَقَّقَة"],"answerIndex":1,"arabicOptions":true,"why":"A كسرة precedes the لام, so the لام stays مرقَّقة - and the ألف simply copies it. The same بسملة holds both راء rulings: ٱلرَّحْمَٰن مفتوحة فمفخَّمة، وٱلرَّحِيم مكسورة فمرقَّقة."},{"type":"choice","q":"Setting the حركة aside, what do the lips contribute to تفخيم?","options":["Round forward","Spread wide","Nothing - the lips have no part in it"],"answerIndex":2,"why":"تفخيم is made at the back of the mouth: أقصى اللسان rises toward الحنك الأعلى and the mouth fills with the letter's echo. Push your lips forward on خَا and you have thickened nothing - you have tinted the فتحة with a ضمة (إشراب شائبة الضم), a vowel error. Do not call it إشمام: إشمام is ضم الشفتين بعد التسكين, تُرى ولا تُسمع - it makes no sound at all."},{"type":"choice","q":"Which sentence is the skeleton of باب الراءات?","options":["الفَتْحُ وَالضَّمُّ مُوجِبَانِ لِلتَّفْخِيمِ، وَالكَسْرُ مُوجِبٌ لِلتَّرْقِيقِ","الكَسْرُ مُوجِبٌ لِلتَّفْخِيمِ، وَالفَتْحُ وَالضَّمُّ مُوجِبَانِ لِلتَّرْقِيقِ","السُّكُونُ مُوجِبٌ لِلتَّفْخِيمِ، وَالحَرَكَةُ مُوجِبَةٌ لِلتَّرْقِيقِ"],"answerIndex":0,"arabicOptions":true,"why":"Everything else is detail stacked on this: eight cases of تفخيم, four of ترقيق, two where both are read. Learn the sentence and the fourteen stop being a list."},{"type":"choice","q":"You begin reading at this word. How is its راء read?","ayah":"ٱرْجِعُوٓا۟ إِلَىٰٓ أَبِيكُمْ","bigArabic":"اِرْجِعُوا","ref":"Sūrat Yūsuf 12:81","options":["مُفَخَّمَة","مُرَقَّقَة"],"answerIndex":0,"arabicOptions":true,"why":"Starting, you say اِرْجِعُوا - but that كسرة belongs to همزة الوصل, so it is عارضة: join a وَ in front and it is gone, وَٱرْجِعُوا. Only a كسرة that survives both الوصل والابتداء thins a راء: «أَوْ كَانَتِ الكَسْرَةُ لَيْسَتْ أَصْلَا»."},{"type":"choice","q":"A كسرة sits before this راء, yet it is not مرقَّقة. What overrides it?","ayah":"وَإِرْصَادًا لِّمَنْ حَارَبَ ٱللَّهَ وَرَسُولَهُ","bigArabic":"إِرْصَادًا","ref":"Sūrat al-Tawbah 9:107","options":["The راء is مشدَّدة","A حرف استعلاء follows it and is not مكسور","The word begins with a همزة"],"answerIndex":1,"why":"The صاد right after it drags the راء back up: «إِنْ لَمْ تَكُنْ مِنْ قَبْلِ حَرْفِ اسْتِعْلَا». Same in قِرْطَاسٍ (6:7) and فِرْقَةٍ (9:122). Note the wording - غير مكسور, not مفتوح; that precision decides the stop on فِرْقٍ later."},{"type":"choice","q":"You stop on this āya. Is its راء مفخَّمة or مرقَّقة?","ayah":"وَٱلْعَصْرِ","ref":"Sūrat al-ʿAṣr 103:1","options":["مُفَخَّمَة","مُرَقَّقَة"],"answerIndex":0,"arabicOptions":true,"why":"Stopping removes the كسرة. What is left is راء ساكنة, before it صاد ساكنة, before that a فتحة - والفتح موجب للتفخيم. Read the same word joined to what follows and its own كسرة would thin it."},{"type":"choice","q":"You stop on the word خَيْرٌ. Its راء is مرقَّقة - why?","bigArabic":"خَيْرْ","options":["The خاء before it is مستعلٍ","A ياء لينية comes before it","A كسرة comes before it","Because it is ساكنة"],"answerIndex":1,"why":"ابن الجزري defines اللين as «وَاوٌ وَيَاءٌ سُكِّنَا وَانْفَتَحَا … قَبْلَهُمَا». والكسرة بعض الياء - the ياء is the home of the كسرة - so if a كسرة thins a راء, a ياء ساكنة does so all the more."},{"type":"choice","q":"Complete ابن الجزري's line on the one word read two ways even in الوصل.","verseStem":"وَالخُلْفُ فِي «فِرْقٍ»؛ لِـ___ يُوجَدُ","options":["كَسْرٍ","ضَمٍّ","فَتْحٍ","إِطْبَاقٍ"],"answerIndex":0,"arabicOptions":true,"why":"«لِكَسْرٍ يُوجَدُ» - the خلاف exists only because a كسرة is found on the قاف. The قاف's استعلاء pulls the راء up, its كسرة pulls down; readers differ on whether that كسرة weakened the قاف or cancelled it."},{"type":"choice","q":"If you stop on فِرْقٍ here with سكون, how is the راء read?","ayah":"فَكَانَ كُلُّ فِرْقٍ كَٱلطَّوْدِ ٱلْعَظِيمِ","ref":"Sūrat al-Shuʿarāʾ 26:63","options":["تفخيم only","ترقيق only","Either one - both are read"],"answerIndex":0,"why":"Joined - and stopping بالروم, which follows the ruling of الوصل - both ways are read. Stop بالسكون and the قاف loses its كسرة: nothing pulls downward any more, so موجب الترقيق is gone. This is why case eight says «غير مكسور» and not «مفتوح»: a ساكن قاف is covered too."},{"type":"choice","q":"Stopping on مِصْرَ (Sūrat al-Zukhruf 43:51) and on ٱلْقِطْرِ both permit two ways. Which way did ابن الجزري himself choose?","ayah":"وَأَسَلْنَا لَهُ عَيْنَ ٱلْقِطْرِ","ref":"Sūrat Sabaʾ 34:12","options":["تفخيم in both","ترقيق in both","تفخيم in مِصْر and ترقيق in ٱلْقِطْر","ترقيق in مِصْر and تفخيم in ٱلْقِطْر"],"answerIndex":2,"why":"مراعاةً للوصل: joined, مِصْرَ has a راء مفتوحة (مفخَّمة) and ٱلْقِطْرِ a راء مكسورة (مرقَّقة), so each stop preserves the sound the word already had. It is an اختيار, not a binding rule - both ways remain permissible in each word."}],"_issues":5,"_state":"verified","url":"https://www.youtube.com/watch?v=MTkmsbjK0Tc&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=11"},{"ep":12,"title_en":"Trapped or Open","title_ar":"الإطباق والانفتاح، ثم الصفير","summary":"What makes ص ض ط ظ the heaviest letters of all, and why do ص س ز whistle?","teach":[{"label_en":"Trapped","title_ar":"الإطباق","count":"4 letters","letters":"ص ض ط ظ","body":"The tongue rises and faces the upper palate, so the sound is confined between the two and comes back with a ring.","tone":"stop"},{"label_en":"Open","title_ar":"الانفتاح","count":"25 letters","body":"Everything else. The gap between tongue and palate stays open and the sound escapes freely - this is the default state, not something you perform.","tone":"flow"},{"label_en":"Heavy, and heavier","title_ar":"الاستعلاء: مطبق ومنفتح","count":"7 مستعلية = 4 + 3","letters":"ص ض ط ظ ‖ خ غ ق","mnemonic":"خُصَّ ضَغْطٍ قِظْ","body":"All seven حروف الاستعلاء are heavy, but ص ض ط ظ carry الإطباق on top of it, so they are أشد تفخيماً than خ غ ق. The gap between the two groups is widest under a kasra.","tone":"brand"},{"label_en":"The whistle","title_ar":"الصفير","count":"3 letters","letters":"ص س ز","body":"A sharpness in the sound as it is squeezed through the narrow channel at the tip of the tongue and the lower front teeth. It opens the صفات that have no opposite.","tone":"between"}],"questions":[{"type":"choice","q":"الإطباق describes what happens to the sound?","options":["It is confined between the tongue and the upper palate","The tongue drops to the floor of the mouth","The lips round and push forward","It escapes through a narrow gap and whistles"],"answerIndex":0,"why":"The tongue rises and faces the roof of the mouth, so the sound is trapped between the two and returns with a ring. الانفتاح is simply the absence of that trapping - nothing is added, the mouth just stays open."},{"type":"multi","q":"Tap the حروف الإطباق.","pool":["ص","ض","ط","ظ","خ","غ","ق","س","ز"],"answers":["ص","ض","ط","ظ"],"why":"ص ض ط ظ - al-Jazarī gathers them in وَصَادُ ضَادٌ طَاءُ ظَاءٌ: مُطْبَقَهْ. خ غ ق are heavy too, but they are مستعلية منفتحة, not مطبقة."},{"type":"choice","q":"How many letters are منفتحة?","options":["4","7","22","25"],"answerIndex":3,"why":"Four letters are مطبقة, so the other 25 of the 29 are منفتحة. The traps: 7 is the count of حروف الاستعلاء and 22 is the count of حروف الاستفال - different pair of صفات entirely."},{"type":"choice","q":"Classify this letter.","bigArabic":"ق","options":["مستعلٍ مطبق","مستعلٍ منفتح","مستفل منفتح","مستفل مطبق"],"arabicOptions":true,"answerIndex":1,"why":"ق sits in خُصَّ ضَغْطٍ قِظْ, so it is مستعلٍ - but it is not one of ص ض ط ظ, so the sound is never trapped. Note the fourth option can never describe any letter: no حرف is مطبق without also being مستعلياً."},{"type":"choice","q":"Complete al-Jazarī's line on تفخيم.","verseStem":"وَحَرْفَ الِاسْتِعْلَاءِ فَخِّمْ، وَاخْصُصَا … الإِطْبَاقَ ____","options":["أَقْوَى","أَعْلَى","أَتَمَّ","أَخْفَى"],"arabicOptions":true,"answerIndex":0,"why":"الإِطْبَاقَ أَقْوَى - fatten every حرف استعلاء, then single out the مطبق as stronger, because the مطبق stacks a second صفة قوة, الإطباق, on top of الاستعلاء, while خ غ ق have الاستعلاء alone out of that pair."},{"type":"choice","q":"How many مطبق letters appear in this āya, counting each letter once as written?","ayah":"ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ","ref":"Sūrat al-Fātiḥah 1:6","options":["1","2","3","4"],"answerIndex":1,"why":"Two: the ص and the ط. The ق of ٱلْمُسْتَقِيمَ is heavy but منفتح, and the س is a صفير letter with no إطباق at all - whistling and trapping are not the same thing."},{"type":"choice","q":"Both of these letters are مستعلية and both carry a kasra. Which one stays heavier?","ayah":"تِلْكَ إِذًۭا قِسْمَةٌۭ ضِيزَىٰٓ","ref":"Sūrat an-Najm 53:22","options":["الضاد في ضِيزَىٰ","القاف في قِسْمَةٌ"],"arabicOptions":true,"answerIndex":0,"why":"A kasra drops every حرف استعلاء to its weakest rank of تفخيم, so the ضِ and the قِ both lose body - and neither is ever مرقق. الإطباق gives the ض a floor the ق has not, so at that same lowest rank the ض stays audibly fuller. Thinning the قِ is a well-known mistake."},{"type":"choice","q":"One letter belongs to both lists you just met: المطبقة and حروف الصفير. Which?","options":["س","ص","ط","ز"],"arabicOptions":true,"answerIndex":1,"why":"ص. It whistles like س and ز, and it is trapped like ض ط ظ - which is why it is by far the heaviest of the three, and why ص and س can never be swapped for one another."},{"type":"choice","q":"The chapter of الصفات المتضادة closes here and a new list opens. Which of these صفات has no opposite?","options":["الإطباق","الانفتاح","الاستفال","الصفير"],"arabicOptions":true,"answerIndex":3,"why":"الإطباق ↔ الانفتاح and الاستعلاء ↔ الاستفال come in pairs. الصفير heads the الصفات التي لا ضد لها, alongside القلقلة واللين والانحراف والتكرير والتفشي والاستطالة والغنة."},{"type":"choice","q":"What is الصفير?","options":["A sharpness in the sound, produced as it passes through a narrow channel","A bounce heard when the letter is ساكن","The sound running on until the breath is spent","A ring carried in the nose"],"answerIndex":0,"why":"حدة في صوت الحرف - the air is forced through a tight gap at the tip of the tongue and the front teeth, like a traffic officer's whistle. It is a by-product of the مخرج, not an effort you add on top."},{"type":"choice","q":"Complete al-Jazarī's line on الصفير.","verseStem":"صَفِيرُهَا: صَادٌ وَزَايٌ ____","options":["سِينُ","شِينُ","ثَاءُ","ذَالُ"],"arabicOptions":true,"answerIndex":0,"why":"صَادٌ وَزَايٌ سِينُ. The three share one مخرج - the tip of the tongue just above the lower front teeth (فويق الثنايا السفلى), the sound squeezing out through the gap between the upper and lower incisors - and that one narrow channel is what makes all three whistle."},{"type":"choice","q":"Some teachers round and push the lips forward when pronouncing ص. What is the status of that?","bigArabic":"ص","options":["Required, to keep the ص heavy","Recommended for beginners only","Baseless - the lips play no part in ص","Required only when the ص is ساكن"],"answerIndex":2,"why":"No imām ever placed the lips in the مخرج or the صفات of ص; its heaviness comes from الاستعلاء والإطباق of the tongue. Rounding the lips adds an extra sound a listener can hear even with his back turned."}],"_issues":4,"_state":"verified","url":"https://www.youtube.com/watch?v=Ydo53V1V1V8&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=12"},{"ep":13,"title_en":"Neither Still Nor Moving","title_ar":"صِفَةُ القَلْقَلَةِ","summary":"What exactly happens to ق ط ب ج د when they fall ساكنة - and why that shake must carry no trace of a vowel.","teach":[{"label_en":"Five letters","title_ar":"حُرُوفُ القَلْقَلَةِ","count":"5 letters","mnemonic":"قُطْبُ جَدٍ","letters":"ق ط ب ج د","body":"They qalqala only when they carry sukūn. All five sit inside the eight شديد letters أَجِدْ قَطٍ بَكَتْ - حروف القلقلة هي الشديدة المجهورة ما عدا الهمزة, which is why ت, ك and أ are left out.","tone":"stop"},{"label_en":"A shake in place","title_ar":"الحَرَكَةُ الاضْطِرَابِيَّةُ","body":"تَقَلْقَلَتِ القِدْرُ عَلَى النَّارِ - the pot rattles on its stones but never leaves them. You cannot call it ساكنة, and it is not متحركة either.","tone":"between"},{"label_en":"Parting, not striking","title_ar":"التَّبَاعُدُ لَا التَّصَادُمُ","body":"Every other ساكن شديد letter is finished by the two sides of the مخرج meeting and staying met. These five are finished by the two sides parting - the way a vowelled letter is released.","tone":"flow"},{"label_en":"No vowel in it","title_ar":"بِلَا شَائِبَةِ حَرَكَةٍ","body":"No opening of the mouth, no rounding of the lips, no dropping of the jaw. لَقَدْ, إِبْرَاهِيم and تُبْتُمْ all get the same bare shake.","tone":"brand"}],"questions":[{"type":"multi","q":"These are the eight شديد letters of أَجِدْ قَطٍ بَكَتْ. Tap the five that also take قلقلة.","pool":["أ","ج","د","ق","ط","ب","ك","ت"],"answers":["ج","د","ق","ط","ب"],"why":"قُطْبُ جَدٍ - ق ط ب ج د. The three you left (أ ك ت) are شديد but take no قلقلة: a ساكن ت or ك is finished by the مخرج closing and staying shut."},{"type":"choice","q":"Complete the line that names the شديد letters.","verseStem":"مَهْمُوسُهَا: «فَحَثَّهُ شَخْصٌ سَكَتْ» … شَدِيدُهَا: لَفْظُ ......","options":["أَجِدْ قَطٍ بَكَتْ","قُطْبُ جَدٍ","فَرَّ مِنْ لُبِّ","خُصَّ ضَغْطٍ قِظْ"],"answerIndex":0,"arabicOptions":true,"why":"أَجِدْ قَطٍ بَكَتْ gathers the eight شديد letters, and قُطْبُ جَدٍ sits entirely inside it. A fully shut مخرج traps the air - but that alone is not enough: of the eight, only the five that are also مجهورة get jolted (ق ط ب ج د); ت and ك are مهموسان and الهمزة is excluded."},{"type":"choice","q":"تَقَلْقَلَتِ القِدْرُ عَلَى النَّارِ - the Arabs said this of a cooking pot on the fire. What is the pot doing?","options":["Boiling over","Rattling in place without moving","Being lifted off the stones","Cracking from the heat"],"answerIndex":1,"why":"القلقلة in the language is الحركة الاضطرابية - a shake that goes nowhere. The pot cannot be called ساكنة, yet it is not متحركة either, because its place never changes. That is exactly the state of a مقلقل letter."},{"type":"choice","q":"What actually produces the jolt you hear on a قلقلة letter?","options":["The two sides of the مخرج striking together (التصادم)","The two sides of the مخرج parting from each other (التباعد)","A puff of breath released after the letter","A short lengthening of the letter"],"answerIndex":1,"why":"An ordinary ساكن شديد letter ends بالتصادم - the two sides meet and stay met. The Arabs released these five بالتباعد instead, the way a vowelled letter is released, and that parting is the whole of القلقلة."},{"type":"choice","q":"A مقلقل letter is released exactly like a vowelled one - بالتباعد. So what still separates them?","options":["The مقلقل is held longer","The مقلقل has no فتح للفم, no انضمام للشفتين, no انخفاض للفك","The مقلقل occurs only at the end of a word","The مقلقل is مهموس"],"answerIndex":1,"why":"Those three gestures are the vowels themselves: فتحة opens the mouth, ضمة rounds the lips, كسرة raises the middle of the tongue and drops the jaw. Strip all three away and the bare shake is what remains."},{"type":"choice","q":"How many letters in this passage take قلقلة?","ayah":"لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا","ref":"Sūrat al-Baqara 2:286","options":["0","1","2","3"],"answerIndex":0,"why":"Not one of ق ط ب ج د appears in it. Several letters here do carry sukūn - the ف of نَفْسًا, the ل of إِلَّا - but a sukūn is not a قلقلة. The letter has to come from قُطْبُ جَدٍ first."},{"type":"choice","q":"Which letter in this āya takes قلقلة?","ayah":"أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ","ref":"Sūrat ash-Sharḥ 94:1","options":["The م of أَلَمْ","The ش of نَشْرَحْ","The ح of نَشْرَحْ","The د of صَدْرَكَ"],"answerIndex":3,"why":"Four letters here are ساكنة in وصل - م، ش، ح، د - and only the د is from قُطْبُ جَدٍ. The ح is the usual trap: it is strong in the throat, but it is رخو, so its sukūn is simply let go."},{"type":"choice","q":"Reading this āya and stopping at its end, how many قلقلة do you make?","ayah":"لَمْ يَلِدْ وَلَمْ يُولَدْ","ref":"Sūrat al-Ikhlāṣ 112:3","options":["1","2","3","4"],"answerIndex":1,"why":"The first د is already ساكنة in وصل - قلقلة صغرى. The second is ساكنة only because you stopped on it - قلقلة كبرى, and the Jazariyyah says it is plainer there: وَبَيِّنَنْ مُقَلْقَلاً إِنْ سَكَنَا … وَإِنْ يَكُنْ فِي الوَقْفِ كَانَ أَبْيَنَا."},{"type":"choice","q":"Complete the line of the Jazariyyah on stopping.","verseStem":"وَحَاذِرِ الوَقْفَ بِكُلِّ الحَرَكَهْ … إِلَّا إِذَا رُمْتَ فَبَعْضُ ......","options":["الحَرَكَهْ","القَلْقَلَهْ","السَّكْتَهْ","الغُنَّهْ"],"answerIndex":0,"arabicOptions":true,"why":"رَوْم is defined right here as بَعْضُ الحَرَكَة, sounded at the وقف. The next line limits it - إِلَّا بِفَتْحٍ أَوْ بِنَصْبٍ - so رَوْم is for المرفوع والمجرور only, never on a فتحة; الاختلاس is the other named fraction of a vowel. Hold on to that for the next question."},{"type":"choice","q":"Many recite لَقَدْ كَانَ with a whisper of كسرة on the د, or إِبْرَاهِيم with a whisper of فتحة on the ب. What is wrong with it?","options":["Nothing - القلقلة follows the vowel before it","Nothing - القلقلة always leans towards الفتح","A fraction of a vowel already has its own names - رَوْم and اخْتِلَاس - and no imam ever defined القلقلة as بَعْضُ الحَرَكَة","Those two letters are not قلقلة letters"],"answerIndex":2,"why":"بَعْضُ الحَرَكَة already has its own name and place; القلقلة is not that. Three modern opinions circulate - that it leans to الفتح, that it follows the vowel before, that it follows the vowel after. Listen to الحصري or عبد الباسط and you will not hear any of the three: the letter comes out bare."},{"type":"choice","q":"The ب of تُبْتُمْ is ساكنة, with a ضمة before it and a ضمة after. Do the lips round as it is released?","ayah":"وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ","ref":"Sūrat al-Baqara 2:279","options":["Yes - the ضمة on either side carries across","No - the lips simply part, with no rounding"],"answerIndex":1,"why":"Round the lips and you have produced part of a ضمة on a letter that has no vowel. The neighbours' vowels have no claim on a ساكن: it belongs to nothing but its own مخرج."},{"type":"choice","q":"A teacher insisted that in his country حروف الاستعلاء are nine, adding ح and ع to خُصَّ ضَغْطٍ قِظْ. How many are there?","options":["5","7","9","10"],"answerIndex":1,"why":"Seven, and the Jazariyyah shuts the count: وَسَبْعُ عُلْوٍ: «خُصَّ ضَغْطٍ قِظْ» حَصَرْ - حَصَرْ is the verb: he shut the door on any eighth. ح and ع are مستفلة - a local habit of raising them had simply been taught long enough to get written down as a rule."}],"_issues":9,"_state":"verified","url":"https://www.youtube.com/watch?v=KgotHP9a7-o&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=13"},{"ep":14,"title_en":"Two Ranks, Four Errors","title_ar":"نَصَائِحُ لِأَهْلِ القُرْآنِ ـ وَمَرَاتِبُ القَلْقَلَةِ","summary":"Stopping on a قلقلة letter makes it ring plainer - so what fixes its rank, and what are the four ways reciters spoil it?","teach":[{"label_en":"Standing in for the Prophet","title_ar":"نِيَابَةٌ عَنْ رَسُولِ اللهِ ﷺ","tone":"brand","body":"The Qur'an names the Messenger's own work: يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ (آل عمران 3:164). Whoever takes up any part of it - leading the prayer, the khuṭba, teaching tajwīd or fiqh - is standing in for him in that one part."},{"label_en":"Two ranks, not three","title_ar":"الكُبْرَى وَالصُّغْرَى","count":"2 ranks","tone":"stop","body":"كبرى when you stop on the letter; صغرى when it falls inside a word or inside connected speech. Only the letter's position changes - mid-word, mid-speech, or stopped on. Two ranks on Dr Ayman's reading: he rejects the third that some modern books add."},{"label_en":"An absorbed letter stays silent","title_ar":"المُدْغَمُ لَا يُقَلْقَلُ","tone":"between","body":"A قلقلة letter swallowed by an إدغام - the د of قَد دَّخَلُوا - is never released, so it is never shaken. Stop on a مشدد one and the shake belongs to the second letter alone."},{"label_en":"Four ways to spoil it","title_ar":"أَخْطَاءُ القَلْقَلَةِ","count":"4 errors","tone":"flow","body":"Colouring it with a vowel; sealing it with a هَمْزَة, so أَحَدْ comes out as أَحَدْء - the mispronunciation, not a spelling; stretching it, though a شديد letter has no length to give; and cutting it off from the next letter with a silent gap."}],"questions":[{"type":"choice","q":"Dr Ayman asked his first teacher, Shaykh Muḥyī al-Dīn al-Kurdī, when he had begun teaching. The shaykh was about ninety-five at the time, and finally answered: at twenty-five. How long had he been teaching the Book of Allah?","options":["About 25 years","About 50 years","About 70 years","About 95 years"],"answerIndex":2,"why":"He dodged the question twice - offering tea, changing the subject - out of shyness before he gave the number. The point of telling it: seventy years of students arriving and leaving, and he was still putting himself out for them."},{"type":"choice","q":"One man comes to you to have his recitation corrected; another comes wanting an إجازة. Dr Ayman draws a sharp line between the two. What is it?","options":["Correct whoever comes, as far as you are able - but grant an إجازة only if the recitation is completely sound and matches what was transmitted","Refuse both unless the reciter has memorised the whole Qur'an","Grant the إجازة first, then keep correcting him afterwards","Hold both to the same standard and make it easy in each case"],"answerIndex":0,"why":"He is careful to say this is not about making things hard on people. The strictness belongs to مقام التلقي والمشافهة alone, because an إجازة certifies that the pronunciation itself came down unbroken."},{"type":"choice","q":"His table sets three states side by side. A ساكن شديد letter is completed by the two sides of the مخرج meeting; a متحرك one by them parting, with a vowel gesture alongside. What is the مقلقل?","options":["Parting, like the متحرك - but with no vowel gesture at all","Meeting, like the ساكن - with a faint vowel gesture","Parting, like the متحرك - with a shortened vowel gesture","Meeting, like the ساكن - and nothing alongside"],"answerIndex":0,"why":"It half-matches each one: released like a متحرك, bare like a ساكن. That double likeness is the name itself - مقلقل, a letter caught between سكون and حركة."},{"type":"choice","q":"Watch the lips and the jaw. When you release the قلقلة on a ساكنة ب, what moves?","bigArabic":"بْ","options":["The lips part; the jaws stay where they are","The lips and the jaws both part","The jaws part; the lips stay met","Neither - the lips meet and stay met"],"answerIndex":0,"why":"On بَ the jaws open too, and that extra opening is the فتحة. On the ب of ٱرْكَب مَّعَنَا (Sūrat Hūd 11:42) the lips close and do not reopen until the م is done, so there is nothing released and no قلقلة at all."},{"type":"choice","q":"Complete the line of the Jazariyyah on the قلقلة.","verseStem":"وَبَيِّنَنْ مُقَلْقَلاً إِنْ سَكَنَا … وَإِنْ يَكُنْ فِي الوَقْفِ كَانَ ......","options":["أَبْيَنَا","أَهْوَنَا","أَلْيَنَا","أَسْكَنَا"],"arabicOptions":true,"answerIndex":0,"why":"The line settles both ranks at once: shake it whenever the letter is ساكن, and plainer - أَبْيَن - when the sukūn comes from your stopping. That is صغرى and كبرى in a single بيت."},{"type":"choice","q":"You read straight on without stopping. What rank is the قلقلة on the ق?","ayah":"لِيُنفِقْ ذُو سَعَةٍۢ مِّن سَعَتِهِۦ","ref":"Sūrat aṭ-Ṭalāq 65:7","options":["كُبْرَى","صُغْرَى","لَا قَلْقَلَةَ عَلَيْهَا"],"arabicOptions":true,"answerIndex":1,"why":"صغرى is for a قلقلة letter inside a word or inside connected speech - and joining لِيُنفِقْ to ذُو puts the ق in the middle of the speech even though it ends its word. Stop on it and that same ق becomes كبرى."},{"type":"choice","q":"The د of قَد is ساكنة and it is one of the five قلقلة letters. Do you shake it here?","ayah":"وَقَد دَّخَلُوا۟ بِٱلْكُفْرِ وَهُمْ قَدْ خَرَجُوا۟ بِهِۦ","ref":"Sūrat al-Māʾida 5:61","options":["No - it is مدغمة, and shaking it would undo the إدغام","Yes - قلقلة صغرى","Yes, but lighter than an ordinary صغرى","Only if you stop on it"],"answerIndex":0,"why":"An إدغام leaves the first letter with no sound of its own; release it بالتباعد and you have put it back. The very same words prove the contrast - the second قَدْ, before خَرَجُوا, is not absorbed, so its د is shaken."},{"type":"choice","q":"You stop at the end of this āya, on وَتَبّ. The ب is مشددة. Which ب takes the قلقلة?","ayah":"تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ","ref":"Sūrat al-Masad 111:1","options":["The first","The second","Both, one after the other","Neither - a مشدد letter takes no قلقلة"],"answerIndex":1,"why":"The first ب is مدغمة: the lips meet for it and it is never released. Only the second is shaken - which is why Dr Ayman rejects the modern grading of a stopped-on مشدد as a rank above كبرى: the قلقلة in الحجّ is exactly the قلقلة in بَهِيج, the shadda still held in full."},{"type":"choice","q":"Stopping on ٱلصَّمَدْ, many reciters let something extra out behind the د. What is it?","ayah":"ٱللَّهُ ٱلصَّمَدُ","ref":"Sūrat al-Ikhlāṣ 112:2","options":["A هَمْزَة - the vocal folds snapping shut after the letter","A ضَمَّة carried over from the word","A غُنَّة","A slight lengthening"],"answerIndex":0,"why":"The هَمْزَة is precisely that closure of the vocal folds, so sealing the letter this way adds a sound the word does not contain. Once the مخرج has parted, let the voice simply run out."},{"type":"choice","q":"Why can a قلقلة never be drawn out?","options":["Because the قلقلة letters are شديدة, and a شديد letter's sound cannot be held","Because they are مهموسة","Because قلقلة only ever happens at the end of a word","Because a حرف مدّ has to follow it"],"answerIndex":0,"why":"All five sit inside أَجِدْ قَطٍ بَكَتْ: the مخرج is shut and the sound is cut off, so there is nothing there to lengthen. What actually comes out when you stretch it is a vowel - the one thing a قلقلة must not carry."},{"type":"choice","q":"A teacher demonstrates يُبْصِرُونَ as يُبْ … صِرُونَ, pausing after the ب so the shake can be heard. What has the pause put into the word?","ayah":"أَمْ لَهُمْ أَعْيُنٌۭ يُبْصِرُونَ بِهَآ","ref":"Sūrat al-Aʿrāf 7:195","options":["A سَكْت - a silent gap that is not in the recitation","قلقلة كبرى in place of صغرى","An extra مدّ on the يُ","Nothing at all; that is how it is recited"],"answerIndex":0,"why":"Cutting the letter off from what follows is a teaching aid, and the complaint is that students then recite it that way for good. سَكْت is a real thing with its own few named places - this is not one of them."},{"type":"multi","q":"His examples of قلقلة كبرى are الفَلَقْ، مُحِيطْ، كَسَبْ، بَهِيجْ، أَحَدْ - stopped on, each ends in one shaken letter. Tap those five letters.","pool":["ق","ك","ط","ت","ب","ء","ج","ح","د"],"answers":["ق","ط","ب","ج","د"],"why":"قُطْبُ جَدٍ, in order. His صغرى list runs through the same five in the same order - يَقْضِي، يُطْعِمُ، يُبْصِرُونَ، وَتَجْعَلُونَ، يَدْخُلُونَ - only there the letter sits in the middle of the word. Nothing about the letter changes between the two lists; only its position does."}],"_issues":7,"_state":"verified","url":"https://www.youtube.com/watch?v=Y7Y7g3GIl7Y&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=14"},{"ep":15,"title_en":"Bend, Shiver, Spread, Stretch","title_ar":"باب صفات الحروف ـ اللين والانحراف والتكرير والتفشي والاستطالة","summary":"Which letters slip out soft, and which ones bend, shiver, scatter or stretch the sound?","teach":[{"label_en":"Soft Exit","title_ar":"اللِّين","count":"2 letters","letters":"و ي","tone":"flow","body":"A <span class='ar'>و</span> or <span class='ar'>ي</span> carrying sukūn with a <span class='ar'>فتحة</span> before it - <span class='ar'>خَوْف</span>، <span class='ar'>بَيْت</span>. The passage is never fully shut, so the letter slips out with ease.","mnemonic":"سُكون + فتحة قبله"},{"label_en":"Deflection","title_ar":"الانْحِراف","count":"2 letters","letters":"ل ر","tone":"between","body":"The tongue blocks the sound's straight path, so the sound bends around it. In <span class='ar'>ل</span> it escapes over the two sides of the tongue; in <span class='ar'>ر</span> it turns inward through a narrow gap."},{"label_en":"The Tremor","title_ar":"التَّكْرير","count":"1 letter","letters":"ر","tone":"stop","body":"The <span class='ar'>ر</span>'s <span class='ar'>مخرج</span> is so narrow that the tip of the tongue shivers faintly. The tremor belongs to the letter; what is forbidden is exaggerating it until more than one <span class='ar'>ر</span> is heard."},{"label_en":"Spread & Stretch","title_ar":"التَّفَشِّي والاسْتِطالة","count":"1 letter each","letters":"ش ض","tone":"brand","body":"One hemistich pairs them: <span class='ar'>وَلِلتَّفَشِّي: الشِّينُ، ضَاداً: اسْتَطِلْ</span>. The breath of <span class='ar'>ش</span> scatters through the mouth until it strikes the inner faces of the front teeth; the <span class='ar'>ض</span> stretches along the edge of the tongue, which is thrust forward until its tip reaches the roots of the upper front teeth."}],"questions":[{"type":"choice","q":"Which letters can be <span class='ar'>حروف اللين</span>?","options":["و ي","ا و ي","ل ر","ش ض"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>الألف</span> never qualifies: the only vowel that can precede it is a <span class='ar'>فتحة</span>, which is homogeneous with it - so <span class='ar'>الألف</span> is always a <span class='ar'>حرف مد</span>."},{"type":"choice","q":"Both words here contain a <span class='ar'>و</span> with sukūn. Which one is a <span class='ar'>حرف لين</span>?","ayah":"ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ","ref":"Sūrat Quraysh 106:4","options":["جُوعٍ","خَوْفٍ"],"arabicOptions":true,"answerIndex":1,"why":"Same letter, different vowel before it. A <span class='ar'>ضمة</span> before a sākin <span class='ar'>و</span> is homogeneous, giving <span class='ar'>مد</span>; a <span class='ar'>فتحة</span> gives <span class='ar'>لين</span>."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span> from <span class='ar'>المقدمة الجزرية</span>:","verseStem":"وَاوٌ وَيَاءٌ سُكِّنَا وَانْفَتَحَا … ـــــــــ","options":["قَبْلَهُمَا، وَالِانْحِرَافُ صُحِّحَا","بَعْدَهُمَا، وَالِانْحِرَافُ صُحِّحَا","قَبْلَهُمَا، وَالِاسْتِطَالَةُ صُحِّحَا"],"arabicOptions":true,"answerIndex":0,"why":"The <span class='ar'>فتحة</span> comes <em>before</em> the letter, never after. One <span class='ar'>بيت</span> finishes <span class='ar'>اللين</span> and hands straight over to <span class='ar'>الانحراف</span>."},{"type":"choice","q":"Where does the deflected sound go in each of the two <span class='ar'>حرفي الانحراف</span>?","options":["ل - out over the two sides of the tongue; ر - inward","ل - inward; ر - out over the two sides of the tongue","Both deflect out over the two sides","Both deflect inward"],"answerIndex":0,"why":"This is why some say <span class='ar'>اللام</span> has much <span class='ar'>انحراف</span> and <span class='ar'>الراء</span> little: the <span class='ar'>لام</span>'s sound has two open sides to take, the <span class='ar'>راء</span> only a narrow gap."},{"type":"multi","q":"Two lines of <span class='ar'>المقدمة الجزرية</span> name four <span class='ar'>صفات</span>: <span class='ar'>الانحراف، التكرير، التفشي، الاستطالة</span>. Tap every letter the poem assigns one of them to.","pool":["ل","ر","ش","ض","ك","ظ","ن","م","ي","ط"],"answers":["ل","ر","ش","ض"],"why":"<span class='ar'>الانحراف</span> is shared by <span class='ar'>ل</span> and <span class='ar'>ر</span>; <span class='ar'>التكرير</span> is <span class='ar'>ر</span>'s alone; <span class='ar'>التفشي</span> is <span class='ar'>ش</span>'s; <span class='ar'>الاستطالة</span> is <span class='ar'>ض</span>'s."},{"type":"choice","q":"What is <span class='ar'>التكرير</span>?","bigArabic":"ر","options":["A faint shiver of the tip of the tongue on the ر","Saying the ر twice wherever it is doubled","Rolling the ر against the upper front teeth"],"answerIndex":0,"why":"The shiver is produced by the narrowness of the <span class='ar'>ر</span>'s <span class='ar'>مخرج</span>, not by anything the reciter adds."},{"type":"choice","q":"Exaggerating <span class='ar'>التكرير</span> produces which audible fault?","options":["More than one ر is heard","The ر picks up a غنة","The ر turns into a لام"],"answerIndex":0,"why":"<span class='ar'>التكرير</span> is a fixed <span class='ar'>صفة</span> of the <span class='ar'>ر</span>. What the reciter is warned against is overdoing it, not having it."},{"type":"choice","q":"A reciter clamps the tongue tight and closes the <span class='ar'>ر</span>'s <span class='ar'>مخرج</span> completely. What comes out?","options":["A ر that sounds شديدة, its passage blocked","A ر that sounds like a لام","A ر that gains تفشي"],"answerIndex":0,"why":"The <span class='ar'>ر</span> needs its small gap. Shut it and the sound is trapped; leave the tongue too far away and the gap widens into a loose, floating sound."},{"type":"choice","q":"Which <span class='ar'>صفة</span> does this letter carry?","bigArabic":"ش","options":["التفشي","الاستطالة","الانحراف","التكرير"],"arabicOptions":true,"answerIndex":0,"why":"The breath of <span class='ar'>ش</span> scatters until part of it strikes the inner faces of the upper and lower front teeth and rebounds into the mouth."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span> from <span class='ar'>المقدمة الجزرية</span>:","verseStem":"فِي اللَّامِ وَالرَّا، وَبِتَكْرِيرٍ جُعِلْ … وَلِلتَّفَشِّي: الشِّينُ، ضَاداً: ــــــ","options":["اسْتَطِلْ","انْحَرِفْ","اعْتَدِلْ"],"arabicOptions":true,"answerIndex":0,"why":"The chapter closes by naming the letter and its <span class='ar'>صفة</span> in two words: <span class='ar'>ضَاداً: اسْتَطِلْ</span>."},{"type":"choice","q":"A learner holds the <span class='ar'>ض</span> sound out long and says that is <span class='ar'>الاستطالة</span>. Is he right?","bigArabic":"ض","options":["No - sound running on is الرخاوة; الاستطالة is the stretch along the edge of the tongue","Yes - holding the sound out is exactly الاستطالة","No - that is القلقلة"],"answerIndex":0,"why":"<span class='ar'>الرخاوة</span> is about the sound continuing; <span class='ar'>الاستطالة</span> is about the tongue being pushed forward by the air trapped behind it."},{"type":"choice","q":"Some readers let air out through the nose on this <span class='ar'>ض</span>. Why is that wrong?","ayah":"… غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ","ref":"Sūrat al-Fātiḥah 1:7","options":["الغنة belongs to م and ن alone - there is no third letter","الغنة only ever attaches to a مشدد letter","The ض is مهموسة, so no nasal sound can attach to it"],"answerIndex":0,"why":"<span class='ar'>الغنة</span> lives in the <span class='ar'>خيشوم</span> and is the property of <span class='ar'>م</span> and <span class='ar'>ن</span> only."},{"type":"choice","q":"Pressing hard with the <em>tip</em> of the tongue while saying <span class='ar'>ض</span> produces what?","options":["A heavy دال","A ظاء","A زاي"],"answerIndex":0,"why":"The pressure belongs on the two edges of the tongue; the front of the edge comes along without bearing down. Letting the tongue travel on to the tips of the front teeth is the other error - that one turns <span class='ar'>ض</span> into <span class='ar'>ظ</span>."}],"_state":"verified","url":"https://www.youtube.com/watch?v=OJDGrpOFyw8&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=15"},{"ep":16,"title_en":"Four Lengths of Ghunna","title_ar":"مَراتِب الغُنَّة وأزمِنَتُها","summary":"The <span class='ar'>غنة</span> is built into <span class='ar'>ن</span> and <span class='ar'>م</span> - so what decides how long you hold it?","teach":[{"label_en":"Always There","title_ar":"الغُنَّة صِفة لازِمة","letters":"ن م","tone":"flow","body":"The <span class='ar'>غنة</span> is part of <span class='ar'>ن</span> and <span class='ar'>م</span> themselves - present whether they are voweled or <span class='ar'>ساكنة</span>, <span class='ar'>مظهرة</span>, <span class='ar'>مدغمة</span>, <span class='ar'>مخفاة</span> or <span class='ar'>مقلوبة</span>. What changes from case to case is only its length. The one exception is <span class='ar'>إدغام النون في اللام والراء</span>, where the <span class='ar'>غنة</span> goes entirely."},{"label_en":"Four Lengths","title_ar":"مَراتِب الغُنَّة","count":"4 ranks","mnemonic":"أَكْمَل ← كامِلة ← ناقِصة ← أَنْقَص","tone":"brand","body":"Longest first: <span class='ar'>أكمل</span> in the <span class='ar'>مشدَّدة</span> and the <span class='ar'>مدغمة بغنة</span>, <span class='ar'>كاملة</span> in the <span class='ar'>مخفاة</span> and the <span class='ar'>مقلوبة</span>, <span class='ar'>ناقصة</span> in <span class='ar'>الساكِنة المُظهَرة</span>, <span class='ar'>أنقص</span> in the <span class='ar'>متحرِّكة</span>. Some books split the top rank in two and count five, keeping the <span class='ar'>مشدَّدة</span> above the <span class='ar'>مدغمة</span>."},{"label_en":"No Counting","title_ar":"المِيزان مَرِن","tone":"between","body":"The <span class='ar'>شروح</span> of the Jazariyyah rank the four states against <em>each other</em> rather than counting <span class='ar'>حركات</span>: fuller in the <span class='ar'>ساكن</span> than the <span class='ar'>متحرك</span>, in the <span class='ar'>مخفى</span> than the <span class='ar'>مظهر</span>, in the <span class='ar'>مدغم</span> than the <span class='ar'>مخفى</span>. Later works do attach figures, but the comparison is the safer guide - the actual duration stretches and shrinks with your pace, longest in <span class='ar'>تحقيق</span>, shorter in <span class='ar'>تدوير</span>, shorter still in <span class='ar'>حدر</span>."},{"label_en":"When It Binds","title_ar":"حُكم الالتِزام بالتَّجويد","tone":"stop","body":"<span class='ar'>مخارج الحروف</span>, and any <span class='ar'>صفة</span> whose loss turns one letter into another, bind every reciter without exception. Purely beautifying <span class='ar'>صفات</span> bind in <span class='ar'>التلقي والمشافهة</span>; in ordinary <span class='ar'>تلاوة</span> they are a blemish in a trained reciter and no sin on the layman."}],"questions":[{"type":"choice","q":"Which rank of <span class='ar'>غنة</span> does the <span class='ar'>ميم</span> of <span class='ar'>حَمَّالَةَ</span> take?","ayah":"وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ","ref":"Sūrat al-Masad 111:4","options":["أَكْمَل","كامِلة","ناقِصة","أَنْقَص"],"arabicOptions":true,"answerIndex":0,"why":"A <span class='ar'>مشدَّدة</span> is two mīms, the first <span class='ar'>ساكنة</span> merged into the second - which is why it tops the scale alongside the <span class='ar'>مدغمة بغنة</span>."},{"type":"choice","q":"The <span class='ar'>نون</span> of <span class='ar'>أَنفُسَكُمْ</span> is <span class='ar'>مخفاة</span> before the <span class='ar'>فاء</span>. Which rank?","ayah":"وَتَنسَوْنَ أَنفُسَكُمْ","ref":"Sūrat al-Baqara 2:44","options":["أَكْمَل","كامِلة","ناقِصة","أَنْقَص"],"arabicOptions":true,"answerIndex":1,"why":"<span class='ar'>كاملة</span> - one step below the top. In <span class='ar'>إخفاء</span> the tongue never reaches the <span class='ar'>مخرج</span> of the <span class='ar'>نون</span>, so what you are holding is the <span class='ar'>غنة</span> and little else."},{"type":"choice","q":"Both the <span class='ar'>نْ</span> and the <span class='ar'>مْ</span> here are <span class='ar'>ساكنة</span> and <span class='ar'>مُظهَرة</span>. Which rank of <span class='ar'>غنة</span>?","ayah":"صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ","ref":"Sūrat al-Fātiḥa 1:7","options":["أَكْمَل","كامِلة","ناقِصة","أَنْقَص"],"arabicOptions":true,"answerIndex":2,"why":"<span class='ar'>ناقصة</span>. Shorter than the <span class='ar'>مخفاة</span>, yet clearly audible - a <span class='ar'>ساكن</span> letter is held longer than a voweled one."},{"type":"choice","q":"And when <span class='ar'>ن</span> and <span class='ar'>م</span> carry a vowel - <span class='ar'>نَ نُ نِ</span>, <span class='ar'>مَ مُ مِ</span>?","bigArabic":"نَ","options":["أَكْمَل","كامِلة","ناقِصة","أَنْقَص"],"arabicOptions":true,"answerIndex":3,"why":"The shortest of the four - but never zero. A voweled <span class='ar'>نون</span> is still nasal, which is why “the <span class='ar'>غنة</span> only exists on the <span class='ar'>ساكنة</span>” is inaccurate."},{"type":"choice","q":"Compare the <span class='ar'>نون</span> of <span class='ar'>مِن وَلِىٍّۢ</span>, which is <span class='ar'>مدغمة بغنة</span>, with the <span class='ar'>مخفاة</span> of <span class='ar'>أَنفُسَكُمْ</span>. Which is held longer?","ayah":"مِن وَلِىٍّۢ وَلَا نَصِيرٍ","ref":"Sūrat al-Baqara 2:107","options":["the <span class='ar'>مدغمة</span>","the <span class='ar'>مخفاة</span>","exactly the same length"],"answerIndex":0,"why":"The commentators state it as a comparison, not a number: fuller in the <span class='ar'>مدغم</span> than in the <span class='ar'>مخفى</span>, and fuller in the <span class='ar'>مخفى</span> than in the <span class='ar'>مظهر</span>."},{"type":"multi","q":"Tap every letter that carries <span class='ar'>غنة</span>.","pool":["ن","م","ب","ل","و","ي","ر","ء"],"answers":["ن","م"],"why":"The <span class='ar'>غنة</span> comes out of the <span class='ar'>خيشوم</span>, and only these two open that passage. In <span class='ar'>إدغام بغنة</span> the nasal sound you hear on <span class='ar'>و</span> and <span class='ar'>ي</span> belongs to the <span class='ar'>نون</span> being merged, not to them. And <span class='ar'>ب</span> shares the lips with <span class='ar'>م</span> yet has no nasal outlet at all."},{"type":"choice","q":"How do the classical commentaries on <span class='ar'>المقدمة الجزرية</span> measure the <span class='ar'>غنة</span>?","options":["As a fixed count of <span class='ar'>حركات</span>","By ranking its states against one another","By the length of one full breath"],"answerIndex":1,"why":"The <span class='ar'>شروح</span> express it as a comparison - fuller in the <span class='ar'>ساكن</span> than the <span class='ar'>متحرك</span>, in the <span class='ar'>مخفى</span> than the <span class='ar'>مظهر</span>, in the <span class='ar'>مدغم</span> than the <span class='ar'>مخفى</span> - not as a count. Later and modern works do attach figures (commonly two <span class='ar'>حركات</span> for the top ranks, one for the bottom); this lesson holds the comparison to be the safer guide, since the scale moves with your pace."},{"type":"choice","q":"You move from <span class='ar'>تحقيق</span> down to <span class='ar'>حدر</span>. What happens to the four ranks?","options":["Every rank shortens, and their order is unchanged","The four ranks collapse into two","The <span class='ar'>غنة</span> is dropped altogether in <span class='ar'>حدر</span>"],"answerIndex":0,"why":"The scale is relative, so it shrinks as a whole. Even at full speed the <span class='ar'>مشدَّدة</span> still outlasts the <span class='ar'>مخفاة</span> in the very same recitation."},{"type":"choice","q":"A reciter cannot yet produce <span class='ar'>ح</span> and says <span class='ar'>ٱلرَّهْمَٰنِ ٱلرَّهِيمِ</span>. What is the ruling?","options":["Binding on every reciter without exception - he must learn it","Acceptable from a layman reciting at home","A concern only inside a session of <span class='ar'>تلقٍّ ومشافهة</span>"],"answerIndex":0,"why":"<span class='ar'>مخارج الحروف</span> admit no concession at any level, because the wording is the vessel of the meaning: change the letter and you have changed the word."},{"type":"choice","q":"Someone recites <span class='ar'>بِٱلسَّٰلِحِينَ</span> in place of <span class='ar'>بِٱلصَّٰلِحِينَ</span>. Which category does this fall under?","ayah":"رَبِّ هَبْ لِى حُكْمًۭا وَأَلْحِقْنِى بِٱلصَّٰلِحِينَ","ref":"Sūrat ash-Shuʿarāʾ 26:83","options":["Binding on everyone - the <span class='ar'>صفة</span> lost has produced a different letter","Beautifying only - the letter is still a <span class='ar'>صاد</span>","Blameworthy in an expert, excused in a layman"],"answerIndex":0,"why":"Strip the <span class='ar'>إطباق</span> and <span class='ar'>استعلاء</span> from <span class='ar'>ص</span> and what comes out is <span class='ar'>س</span> - another letter, another word. The same category as <span class='ar'>عَسَىٰ</span> turning into <span class='ar'>عَصَىٰ</span>."},{"type":"choice","q":"An ordinary Muslim reciting for himself does not give the <span class='ar'>قلقلة</span> its full release. What is the ruling?","options":["He has left the more complete way, and nothing is upon him","Sinful and deserving of punishment","Identical to a <span class='ar'>مخرج</span> error"],"answerIndex":0,"why":"The same lapse is judged by its setting: a blemish in a trained reciter who knows better, and forbidden in <span class='ar'>تلقٍّ ومشافهة</span>, where granting an <span class='ar'>إجازة</span> on it would misreport what was actually heard."}],"_issues":10,"_state":"verified","url":"https://www.youtube.com/watch?v=I3-IOD49WgE&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=16"},{"ep":17,"title_en":"Where Letters Go Wrong","title_ar":"أَبْرَزُ الأَخْطاءِ عِنْدَ نُطْقِ حُروفِ الهِجاءِ","summary":"When a letter comes out wrong, what exactly went wrong - and which fix does it need?","teach":[{"label_en":"The Measure","title_ar":"قَدْرُ الصِّفَةِ: لا زِيادَةَ ولا نُقْصان","tone":"brand","body":"Half the errors in this chapter are one error wearing two faces: the wrong <em>amount</em> of a <span class='ar'>صفة</span>. Lips barely rounded on <span class='ar'>تَعْمَلُونَ</span> and lips clenched tight on <span class='ar'>يَقُولُونَ</span> are the same fault in opposite directions."},{"label_en":"A Different Letter","title_ar":"إِبْدالُ الحَرْفِ بِغَيْرِهِ","tone":"stop","body":"The gravest class, because the word itself changes: <span class='ar'>ض</span> read as <span class='ar'>ظ</span>, <span class='ar'>ج</span> as <span class='ar'>د</span> or <span class='ar'>ش</span> or <span class='ar'>ي</span>, <span class='ar'>ع</span> as <span class='ar'>ء</span>, <span class='ar'>ح</span> as <span class='ar'>ه</span>. The substitute is always a close neighbour - in <span class='ar'>مخرج</span> or in <span class='ar'>صفة</span> - which is exactly what makes the slip easy."},{"label_en":"Caught From a Neighbour","title_ar":"التَّأَثُّرُ بِالحَرْفِ المُجاوِر","tone":"between","body":"<span class='ar'>التفخيم</span> is catching. The <span class='ar'>همزة</span> of <span class='ar'>أَصَٰبِعَهُمْ</span> beside a <span class='ar'>صاد</span>, the <span class='ar'>هاء</span> of <span class='ar'>ٱللَّهُ</span> after the heavy <span class='ar'>لام</span>, the <span class='ar'>شين</span> beside a <span class='ar'>طاء</span> - each stays <span class='ar'>مرقَّقًا</span> however heavy its neighbour is."},{"label_en":"Nasal Leak","title_ar":"فَتْحُ الخَيْشومِ في غَيْرِ مَحَلِّهِ","letters":"ن م","tone":"flow","body":"The <span class='ar'>خيشوم</span> opens for <span class='ar'>ن</span> and <span class='ar'>م</span> and for nothing else. Pushing the sound up into the nose on the <span class='ar'>ألف</span> of <span class='ar'>ٱلرَّحْمَٰنِ</span>, the <span class='ar'>واو</span> of <span class='ar'>ٱلظَّٰلِمُونَ</span> or the <span class='ar'>ياء</span> of <span class='ar'>ٱلدُّنْيَا</span> (whose own <span class='ar'>نون ساكنة</span> keeps its <span class='ar'>غنة</span>) smears a <span class='ar'>غنة</span> onto letters that own none."}],"questions":[{"type":"choice","q":"<span class='ar'>ظَلَّ</span> and <span class='ar'>ضَلَّ</span> are both real words. Which one means “went astray”?","ayah":"وَإِذَا بُشِّرَ أَحَدُهُم بِٱلْأُنثَىٰ ظَلَّ وَجْهُهُۥ مُسْوَدًّۭا وَهُوَ كَظِيمٌۭ","ref":"Sūrat an-Naḥl 16:58","options":["ظَلَّ","ضَلَّ"],"arabicOptions":true,"answerIndex":1,"why":"<span class='ar'>ظَلَّ</span> means “he remained”, as the āya shows. Reading a <span class='ar'>ضاد</span> as a <span class='ar'>ظاء</span> is not a blurred sound - it hands you a different root."},{"type":"multi","q":"A reciter who cannot yet produce the <span class='ar'>حاء</span> of <span class='ar'>ٱلْحَمْدُ</span> typically substitutes one of two other letters. Tap both.","pool":["خ","هـ","ع","غ","ق","ء"],"answers":["خ","هـ"],"why":"<span class='ar'>ه</span> sits deeper in the throat than <span class='ar'>ح</span>, <span class='ar'>خ</span> nearer the mouth, with <span class='ar'>ح</span> between them at <span class='ar'>وسط الحلق</span>. What picks these two out of the pool is that only they share the <span class='ar'>حاء</span>'s <span class='ar'>همس</span> and <span class='ar'>رخاوة</span> - <span class='ar'>ع</span> and <span class='ar'>غ</span> are <span class='ar'>مجهورة</span>, <span class='ar'>ء</span> is <span class='ar'>شديدة</span>, and the voice gives them away."},{"type":"choice","q":"The <span class='ar'>كاف</span> <span class='ar'>ساكنة</span> in <span class='ar'>ذِكْرَكَ</span> is cut off dead, with no breath heard after it. Which <span class='ar'>صفة</span> has been dropped?","ayah":"وَرَفَعْنَا لَكَ ذِكْرَكَ","ref":"Sūrat ash-Sharḥ 94:4","options":["الهمس","الجهر","القلقلة","الاستطالة"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>ك</span> is <span class='ar'>شديدة مهموسة</span>: the closure stops the sound, and then the breath must still be heard running out after it. Without that breath the letter arrives mute."},{"type":"choice","q":"Some reciters release a puff of breath along with the <span class='ar'>قاف</span> of <span class='ar'>قَالُوا</span>. Why is that wrong?","bigArabic":"ق","options":["The Arabic <span class='ar'>قاف</span> is <span class='ar'>مجهورة</span> - no breath runs with it","The <span class='ar'>قاف</span> is <span class='ar'>مهموسة</span>, but only when it is <span class='ar'>ساكنة</span>","Breath is allowed, but only when stopping on it"],"answerIndex":0,"why":"<span class='ar'>الهمس</span> belongs to the letters of <span class='ar'>فَحَثَّهُ شَخْصٌ سَكَتْ</span>, and <span class='ar'>ق</span> is not among them. Aspirate it and it drifts toward the <span class='ar'>كاف</span>, which is the breathed letter of the pair."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span> from <span class='ar'>المقدمة الجزرية</span>:","verseStem":"وَالخُلْفُ فِي «فِرْقٍ»؛ لِكَسْرٍ يُوجَدُ … وَأَخْفِ تَكْرِيراً إِذَا","options":["تُشَدَّدُ","تُسَكَّنُ","تُرَقَّقُ"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>التكرير</span> is a <span class='ar'>صفة</span> the <span class='ar'>راء</span> already carries; the instruction is to conceal it, never to perform it - and most of all on a doubled <span class='ar'>راء</span> like <span class='ar'>ٱلرَّزَّاقُ</span>."},{"type":"choice","q":"In <span class='ar'>أَصَٰبِعَهُمْ</span> the <span class='ar'>همزة</span> sits immediately before a <span class='ar'>صاد</span>. How is it read?","ayah":"يَجْعَلُونَ أَصَٰبِعَهُمْ فِىٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلْمَوْتِ","ref":"Sūrat al-Baqara 2:19 (part of the āya)","options":["<span class='ar'>مرقَّقة</span>, exactly as it is everywhere else","<span class='ar'>مفخَّمة</span>, taking the weight of the <span class='ar'>صاد</span>","Halfway between the two"],"answerIndex":0,"why":"The <span class='ar'>همزة</span> is never thickened in Arabic. A <span class='ar'>حرف استعلاء</span> beside it raises the back of the tongue for its own sake and lends the <span class='ar'>همزة</span> nothing."},{"type":"choice","q":"Ibn al-Jazarī lists <span class='ar'>سَبِّحْهُ</span> among the words he orders you to <span class='ar'>أَبِنْ</span> - to make plain. What is he forbidding?","ayah":"وَمِنَ ٱلَّيْلِ فَٱسْجُدْ لَهُۥ وَسَبِّحْهُ لَيْلًۭا طَوِيلًا","ref":"Sūrat al-Insān 76:26","options":["Letting the <span class='ar'>حاء</span> <span class='ar'>ساكنة</span> melt into the <span class='ar'>هاء</span> after it","Stopping on the <span class='ar'>هاء</span>","Reading the <span class='ar'>حاء</span> with <span class='ar'>تفخيم</span>"],"answerIndex":0,"why":"The line before it orders <span class='ar'>إدغام</span> of the first of two like or kindred letters; this line is the list of what must be shown plainly instead. <span class='ar'>ح</span> and <span class='ar'>ه</span> sit close enough in the throat that the first vanishes unless you deliberately sound it."},{"type":"choice","q":"You stop on <span class='ar'>نَسْتَعِينُ</span>. Chopping the final <span class='ar'>نون</span>'s <span class='ar'>غنة</span> off and dragging it out are both named as errors. So what is the measure?","ayah":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","ref":"Sūrat al-Fātiḥa 1:5","options":["The letter's own natural <span class='ar'>غنة</span> - no more and no less","No <span class='ar'>غنة</span> at all, now that the <span class='ar'>نون</span> is <span class='ar'>ساكنة</span>","Held as long as the breath allows"],"answerIndex":0,"why":"A <span class='ar'>نون ساكنة</span> carries a <span class='ar'>غنة ناقصة</span>: clearly audible, and short. Amputating it and stretching it are two failures around a single measure."},{"type":"choice","q":"A reciter's <span class='ar'>مَٰلِكِ</span> comes out leaning toward a <span class='ar'>ياء</span>. What is his tongue doing?","bigArabic":"ا","options":["Raising its middle","Pressing its tip against the palate","Drawing its back toward the throat"],"answerIndex":0,"why":"<span class='ar'>الألف</span> has no contact point of its own - it takes the shape of the cavity the sound passes through, so a raised tongue tilts it toward <span class='ar'>ي</span>. Left flat and at rest, it comes out pure."},{"type":"choice","q":"<span class='ar'>قَالُوا</span> read so that the <span class='ar'>واو</span> tips toward an <span class='ar'>ألف</span>. What went wrong?","bigArabic":"و","options":["The lips were not rounded, so the mouth stayed open as for <span class='ar'>ألف</span>","The <span class='ar'>خيشوم</span> was opened","The tip of the tongue touched the teeth"],"answerIndex":0,"why":"<span class='ar'>واو المد</span> runs through the mouth cavity with the lips rounded - that rounding is what separates it from the open <span class='ar'>ألف</span>. Relax them and it falls back toward that <span class='ar'>ألف</span>; clench them and it distorts the other way."},{"type":"choice","q":"The <span class='ar'>جيم</span> of <span class='ar'>ٱلرَّجِيمِ</span> is read with its sound allowed to run on. Which <span class='ar'>صفة</span> has been lost?","ayah":"فَإِذَا قَرَأْتَ ٱلْقُرْءَانَ فَٱسْتَعِذْ بِٱللَّهِ مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ","ref":"Sūrat an-Naḥl 16:98","options":["الشدة","الجهر","الإطباق"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>ج</span> is one of <span class='ar'>أَجِدْ قَطٍ بَكَتْ</span>: the sound must be stopped at the <span class='ar'>مخرج</span>, not let through. Let it run and the <span class='ar'>جيم</span> drifts toward <span class='ar'>ش</span>, which shares the very same <span class='ar'>مخرج</span>."},{"type":"choice","q":"A reciter leaves a small silence inside <span class='ar'>وَلَا ٱلضَّآلِّينَ</span> and calls it <span class='ar'>الاستطالة</span>. Why is it not?","ayah":"صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ","ref":"Sūrat al-Fātiḥa 1:7","options":["<span class='ar'>الاستطالة</span> is sound travelling along the tongue; a gap is the absence of sound","<span class='ar'>الاستطالة</span> belongs to the <span class='ar'>ظاء</span>, not the <span class='ar'>ضاد</span>","<span class='ar'>الاستطالة</span> applies only when the <span class='ar'>ضاد</span> is <span class='ar'>متحركة</span>"],"answerIndex":0,"why":"The <span class='ar'>ضاد</span> stretches from the edge of the tongue along the molars - you hear it travel, you never hear a pause. And because it is <span class='ar'>رخوة</span>, nothing is trapped inside it to bounce either."}],"_state":"verified","url":"https://www.youtube.com/watch?v=_2RZIEq0t6s&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=17"},{"ep":18,"title_en":"Finish Every Vowel","title_ar":"إِتْمامُ الحَرَكات وتَخْليصُ الحُروف","summary":"What has to happen in the mouth before a fatḥa, ḍamma or kasra counts as finished?","teach":[{"label_en":"Four States","title_ar":"أحوالُ الحرفِ الأربعة","count":"4 states","tone":"brand","body":"Every Arabic letter is one of four: <span class='ar'>ساكن</span>, <span class='ar'>مفتوح</span>, <span class='ar'>مضموم</span>, <span class='ar'>مكسور</span>. Pronouncing a <strong>vowelled</strong> letter is two jobs at once - bring it out of its <span class='ar'>مخرج</span>, then let the mouth finish its vowel. A <span class='ar'>ساكن</span> letter is only the first job."},{"label_en":"Three Shapes","title_ar":"الفَتْحةُ والضَّمّةُ والكَسْرة","count":"3 movements","mnemonic":"الفَتْحةُ أَلِفٌ قصيرة، والضَّمّةُ واوٌ قصيرة، والكَسْرةُ ياءٌ قصيرة","letters":"ـَ ـُ ـِ","tone":"flow","body":"<span class='ar'>فتحة</span> - the jaws part into a middle opening. <span class='ar'>ضمة</span> - the lips round fully but without exaggeration, as if starting a <span class='ar'>واو</span>. <span class='ar'>كسرة</span> - the lower jaw drops and the middle of the tongue rises, as if starting a <span class='ar'>ياء</span>."},{"label_en":"Sukūn Adds Nothing","title_ar":"الحَرْفُ السّاكن","tone":"stop","body":"The <span class='ar'>ساكن</span> letter leaves its <span class='ar'>مخرج</span> and nothing follows it - no opening, no rounding, no drop of the jaw. <span class='ar'>أَفْ، أَسْ، أَمْ</span>. The five <span class='ar'>قلقلة</span> letters (<span class='ar'>قُطْبُ جَدٍ</span>) are the one exception: their sukūn is released with a bounce, which is not a vowel."},{"label_en":"Keep Them Apart","title_ar":"تَخْليصُ الحُروف","tone":"between","body":"When a <span class='ar'>مفخم</span> letter sits beside a <span class='ar'>مرقق</span> one, each keeps its own weight and neither leaks into the other. <span class='ar'>مَخْمَصَةٍ</span> - the mīm before the <span class='ar'>خ</span> and the mīm wedged between the <span class='ar'>خ</span> and the <span class='ar'>ص</span> both stay light."}],"questions":[{"type":"choice","q":"A letter carrying a <span class='ar'>فتحة</span> - what must accompany it out of its <span class='ar'>مخرج</span>?","bigArabic":"بَ","options":["The jaws part into a middle opening","The lips round firmly","The lower jaw drops and the tongue rises","Nothing at all"],"answerIndex":0,"why":"The fatḥa is the jaw's work, and the measure matters: Abū ʿAmr ad-Dānī described the Arabic fatḥa as <span class='ar'>فَتْحٌ وَسَط</span> - a middle opening, never a stretched one."},{"type":"choice","q":"A letter carrying a <span class='ar'>كسرة</span> - what must accompany it out of its <span class='ar'>مخرج</span>?","bigArabic":"بِ","options":["The lower jaw drops and the middle of the tongue rises","The lips round firmly","The jaws part into a middle opening","The tongue tip presses the front teeth"],"answerIndex":0,"why":"Two movements, and the raised tongue is the one readers skip - the middle of the tongue rising is the <span class='ar'>مخرج</span> of the <span class='ar'>ياء</span>, which the kasra is a short form of."},{"type":"choice","q":"A letter carrying a <span class='ar'>سكون</span> - what accompanies it out of its <span class='ar'>مخرج</span>?","bigArabic":"فْ","options":["Nothing at all","A slight opening of the mouth","A slight rounding of the lips","A slight drop of the lower jaw"],"answerIndex":0,"why":"A sākin letter takes its <span class='ar'>مخرج</span> and stops there. Any opening, rounding or jaw-drop added to it turns it into a vowelled letter. <span class='ar'>القلقلة</span> is a <span class='ar'>صفة</span> of the letter, not a <span class='ar'>حركة</span>."},{"type":"choice","q":"The <span class='ar'>ضمة</span> is a shortened form of which letter?","options":["الألف","الواو","الياء"],"arabicOptions":true,"answerIndex":1,"why":"Each <span class='ar'>حركة</span> is its <span class='ar'>حرف مد</span> cut short - same sound, less time. That is why rounding the lips is not decoration on a ḍamma but the ḍamma itself."},{"type":"choice","q":"The <span class='ar'>ص</span> of <span class='ar'>ٱلصِّرَٰطَ</span> is <span class='ar'>مشدَّدة</span>, and its second half carries a kasra. If the jaw does not drop and the tongue does not rise, what does the listener hear instead?","ayah":"ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ","ref":"Sūrat al-Fātiḥa 1:6","options":["A سكون","A ضمة","A فتحة","An ألف"],"answerIndex":0,"why":"<span class='ar'>خلط الكسرة بالسكون</span> - <span class='ar'>عدم رفع وسط اللسان وعدم خفض الفك السفلي بالمقدار المطلوب</span>: the kasra needs both movements, and a half-made one is heard as no vowel at all."},{"type":"choice","q":"The <span class='ar'>ل</span> here carries a <span class='ar'>شدة</span>. What is a <span class='ar'>مشدَّد</span> letter made of?","ayah":"وَلَا ٱلضَّآلِّينَ","ref":"Sūrat al-Fātiḥa 1:7","options":["A sākin letter followed by the same letter vowelled","One letter simply held twice as long","Two vowelled letters of the same kind"],"answerIndex":0,"why":"So there are two lāms here: the first takes nothing at all, the second takes a full kasra. Give the second one its dropped jaw and both lāms become audible."},{"type":"choice","q":"<span class='ar'>مَخْمَصَةٍ</span> has two mīms - one before the <span class='ar'>خ</span>, one between the <span class='ar'>خ</span> and the <span class='ar'>ص</span>. How are they pronounced?","ayah":"فَمَنِ ٱضْطُرَّ فِى مَخْمَصَةٍ","ref":"Sūrat al-Māʾida 5:3","options":["Both مرققة","Both مفخمة","The first مفخمة, the second مرققة"],"answerIndex":0,"why":"The <span class='ar'>ميم</span> is never <span class='ar'>مفخمة</span>. Sitting next to a heavy letter does not make it heavy - that leakage is precisely what this chapter is guarding against."},{"type":"choice","q":"The early writers had a name for keeping a heavy letter from bleeding into its light neighbour. What is it?","options":["تَخْليصُ الحُروف","إتمامُ الحَرَكات","تَمْكينُ الحُروف"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>تخليص</span> is extraction: pulling the <span class='ar'>مفخم</span> clear of the <span class='ar'>مرقق</span> and the <span class='ar'>مرقق</span> clear of the <span class='ar'>مفخم</span>, letter by letter - as in <span class='ar'>ٱلَّذِى خَلَقَكُمْ</span>, where heavy and light alternate straight through the word."},{"type":"choice","q":"The <span class='ar'>لام</span> of <span class='ar'>لفظ الجلالة</span> here is <span class='ar'>مفخمة</span>. What about the <span class='ar'>واو</span> in front of it?","ayah":"وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ","ref":"Sūrat Āl ʿImrān 3:189","options":["It stays مرققة","It becomes مفخمة, following the لام","It is lightly مفخمة, between the two"],"answerIndex":0,"why":"The non-madd <span class='ar'>واو</span> is a light letter and stays light beside any heavy one. Rounding the lips for it is required; thickening it is not - the two are different jobs."},{"type":"choice","q":"When is the <span class='ar'>باء</span> pronounced <span class='ar'>مفخمة</span>?","bigArabic":"ب","options":["Never","When it neighbours a مفخم letter","When it carries a فتحة"],"answerIndex":0,"why":"In <span class='ar'>أَبْصَٰرَهُمْ</span> the <span class='ar'>ب</span> sits right against a <span class='ar'>ص</span> and still stays light. The fault to watch on the <span class='ar'>ب</span> is the opposite one - letting its <span class='ar'>قلقلة</span> go when it is sākin."},{"type":"multi","q":"Tap the three <span class='ar'>حروف الصفير</span>.","pool":["ص","س","ز","ث","ذ","ظ","ش","ج"],"answers":["ص","س","ز"],"why":"A whistle rides on all three, and thinning that whistle away is a named error. They part company elsewhere: <span class='ar'>ص</span> is <span class='ar'>مفخمة</span>, while <span class='ar'>س</span> and <span class='ar'>ز</span> are <span class='ar'>مرققتان</span>."},{"type":"multi","q":"Tap the three letters made with the tip of the tongue against the edges of the upper front teeth.","pool":["ث","ذ","ظ","ض","ط","ز","س"],"answers":["ث","ذ","ظ"],"why":"The tip meets the edge of the teeth - not thrust out well past them, not pulled back behind them. Both extremes are common faults, and both change the letter."}],"_state":"verified","url":"https://www.youtube.com/watch?v=-LxbHpJs9bw&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=18"},{"ep":19,"title_en":"Stopping Without Breaking","title_ar":"بَابُ الوَقْفِ وَالِابْتِدَاءِ","summary":"You have to stop before the āya ends - where may you stop, and where may you start again?","teach":[{"label_en":"What It Guards","title_ar":"عِلْمُ الوَقْفِ وَالِابْتِدَاءِ","tone":"brand","body":"<span class='ar'>التجويد</span> guards the Qur'an at the level of the letter - its <span class='ar'>مخرج</span> and its <span class='ar'>صفة</span>. This science guards it at the level of the sentence: that no word is cut off from its own clause or attached to the next one."},{"label_en":"Three Circumstances","title_ar":"اخْتِيَارِيٌّ، اضْطِرَارِيٌّ، اخْتِبَارِيٌّ","count":"3 kinds","tone":"flow","body":"<span class='ar'>اختياري</span> - you chose it. <span class='ar'>اضطراري</span> - a cough or a spent breath forced it. <span class='ar'>اختباري</span> - a teacher asked you to show how the word is stopped on. Only the first one gets graded."},{"label_en":"Two Links, Four Grades","title_ar":"التَّامُ وَالكَافِي وَالحَسَنُ وَالقَبِيحُ","count":"4 grades","tone":"stop","body":"These four grade the <span class='ar'>اختياري</span> stop only. Ask two questions about the word you stopped on and the word after it: is there a grammatical link (<span class='ar'>تعلق لفظي</span>)? a link of meaning (<span class='ar'>تعلق معنوي</span>)? Neither → <span class='ar'>تام</span>؛ meaning only → <span class='ar'>كافٍ</span>؛ both, yet the sense already stands → <span class='ar'>حسن</span>؛ both, and the sense is broken → <span class='ar'>قبيح</span>. Ibn al-Jazarī counts three - <span class='ar'>تام، كافٍ، حسن</span> - because he is naming the ones that are permitted; <span class='ar'>القبيح</span> is the one that is not."},{"label_en":"May You Start Again?","title_ar":"الِابْتِدَاءُ بِمَا بَعْدَهُ","tone":"between","body":"<span class='ar'>تام</span> and <span class='ar'>كافٍ</span>: stop, then begin from the next word. <span class='ar'>حسن</span>: stop, but go back and reconnect - unless you stopped at a <span class='ar'>رأس آية</span>. <span class='ar'>قبيح</span>: never on purpose; if forced, go back and re-read."}],"questions":[{"type":"choice","q":"What does <span class='ar'>علم الوقف والابتداء</span> protect the recitation from?","options":["A word being joined to a sentence it does not belong to","A letter being pronounced from the wrong <span class='ar'>مخرج</span>","A <span class='ar'>مد</span> being stretched to the wrong length"],"answerIndex":0,"why":"The other two are the business of <span class='ar'>التجويد</span>. This science works one level up - on the clause, not the letter."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span> from <span class='ar'>المقدمة الجزرية</span>:","verseStem":"وَبَعْدَ تَجْوِيدِكَ لِلْحُرُوفِ …","options":["لَا بُدَّ مِنْ مَعْرِفَةِ الوُقُوفِ","إِظْهَارٌ، ادْغَامٌ، وَقَلْبٌ، إِخْفَا","فِي اللَّامِ وَالرَّا لَا بِغُنَّةٍ لَزِمْ"],"arabicOptions":true,"answerIndex":0,"why":"He does not say it is preferable - he says <span class='ar'>لا بد</span>. The chapter on stopping opens the moment the chapters on the letters close."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span>. How many divisions does Ibn al-Jazarī name here?","verseStem":"وَالِابْتِدَاءِ، وَهْيَ تُقْسَمُ إِذَنْ …","options":["ثَلَاثَةً: تَامٌ، وَكَافٍ، وَحَسَنْ","أَرْبَعَةً: تَامٌ، وَكَافٍ، وَحَسَنٌ، وَقَبِيحْ","قِسْمَيْنِ: جَائِزٌ وَغَيْرُ جَائِزٍ"],"arabicOptions":true,"answerIndex":0,"why":"Three, because he is listing the stops that are allowed. The <span class='ar'>قبيح</span> comes a few <span class='ar'>أبيات</span> later, at <span class='ar'>وَغَيْرُ مَا تَمَّ قَبِيحٌ، وَلَهُ … الوَقْفُ مُضْطَرّاً؛ وَيَبْدَا قَبْلَهُ</span>."},{"type":"choice","q":"You stop at the end of this āya. The next āya begins <span class='ar'>إِنَّ ٱلَّذِينَ كَفَرُوا۟</span>. What kind of stop is this?","ayah":"أُو۟لَٰٓئِكَ عَلَىٰ هُدًۭى مِّن رَّبِّهِمْ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ","ref":"Sūrat al-Baqara 2:5","options":["تَامّ","كَافٍ","حَسَن","قَبِيح"],"arabicOptions":true,"answerIndex":0,"why":"Different people and a different sentence: neither the <span class='ar'>إعراب</span> nor the meaning carries across. So you may stop here and begin afresh with what follows."},{"type":"choice","q":"You stop at <span class='ar'>لَا يُؤْمِنُونَ</span>. The next āya begins <span class='ar'>خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ</span>. What kind of stop is this?","ayah":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ","ref":"Sūrat al-Baqara 2:6","options":["تَامّ","كَافٍ","حَسَن","قَبِيح"],"arabicOptions":true,"answerIndex":1,"why":"<span class='ar'>خَتَمَ ٱللَّهُ</span> starts a complete new sentence, so no grammatical link reaches back. But it still describes the same people - the link of meaning remains. Meaning only = <span class='ar'>كافٍ</span>."},{"type":"choice","q":"A reciter stops at <span class='ar'>ٱلْحَمْدُ لِلَّهِ</span>, before <span class='ar'>رَبِّ ٱلْعَٰلَمِينَ</span>. What kind of stop is this?","ayah":"ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ","ref":"Sūrat al-Fātiḥa 1:2","options":["تَامّ","كَافٍ","حَسَن","قَبِيح"],"arabicOptions":true,"answerIndex":2,"why":"The sense already stands - <span class='ar'>مبتدأ</span> and <span class='ar'>خبر</span> are both there. But <span class='ar'>رَبِّ</span> is a <span class='ar'>صفة</span> of what precedes it, so the grammatical link is still open."},{"type":"choice","q":"He stopped at <span class='ar'>ٱلْحَمْدُ لِلَّهِ</span> and took a breath. What is the nearest word he may resume from?","options":["<span class='ar'>ٱلْحَمْدُ</span> - he goes back","<span class='ar'>رَبِّ</span> - he carries on from there","<span class='ar'>لِلَّهِ</span> - he repeats only the word he stopped on"],"answerIndex":0,"why":"The rule for <span class='ar'>الحسن</span>: <span class='ar'>يوقف عليه ولا يبتدأ بما بعده</span>. Stopping was permitted; starting at <span class='ar'>رَبِّ</span> is not, because that word still hangs on <span class='ar'>لِلَّهِ</span>."},{"type":"choice","q":"He stops at the end of <span class='ar'>ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ</span>. May he now begin the next āya at <span class='ar'>ٱلرَّحْمَٰنِ ٱلرَّحِيمِ</span>, although it is a <span class='ar'>صفة</span> of <span class='ar'>رَبِّ</span>?","options":["Yes - it is a <span class='ar'>رأس آية</span>","No - he must go back to <span class='ar'>ٱلْحَمْدُ لِلَّهِ</span>","No - one may never begin with a <span class='ar'>مجرور</span>"],"answerIndex":0,"why":"Ibn al-Jazarī's own exception: <span class='ar'>إِلَّا رُؤُوسَ الآيِ جَوِّزْ</span>. Without it you could never begin an āya with a <span class='ar'>مجرور</span> like <span class='ar'>ٱلرَّحْمَٰنِ</span>."},{"type":"choice","q":"A reciter stops at <span class='ar'>لَا يَغْفِرُ</span>. What kind of stopping-place is this?","ayah":"إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدِ ٱفْتَرَىٰٓ إِثْمًا عَظِيمًا","ref":"Sūrat an-Nisāʾ 4:48","options":["تَامّ","كَافٍ","حَسَن","قَبِيح"],"arabicOptions":true,"answerIndex":3,"why":"Both links are still open, and cutting here makes the words say the opposite of the āya. No one stops there on purpose - <span class='ar'>فإن وقف عليه مضطرًّا أعاد</span>."},{"type":"choice","q":"Your teacher asks you to show how you would stop on a particular word. What kind of stop is that?","options":["اخْتِيَارِيّ","اضْطِرَارِيّ","اخْتِبَارِيّ"],"arabicOptions":true,"answerIndex":2,"why":"<span class='ar'>اختباري</span> is a stop made under examination. <span class='ar'>اضطراري</span> is the one a cough or a spent breath forces on you - neither is a free choice, so neither is judged by the four grades."},{"type":"choice","q":"An imam recites this āya, then says <span class='ar'>الله أكبر</span> and bows. What has he done wrong?","ayah":"فَوَيْلٌۭ لِّلْمُصَلِّينَ","ref":"Sūrat al-Māʿūn 107:4","options":["He ended his recitation there - that is <span class='ar'>قطع</span>, not <span class='ar'>وقف</span>","He stopped on a <span class='ar'>رأس آية</span>, and those may not be stopped on","He separated two āyāt that must always be recited together"],"answerIndex":0,"why":"<span class='ar'>الوقف</span> cuts the sound intending to resume; <span class='ar'>القطع</span> cuts it intending to leave the recitation. Pausing for breath here and then continuing with <span class='ar'>ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ</span> is sound."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span> from <span class='ar'>المقدمة الجزرية</span>:","verseStem":"وَلَيْسَ فِي القُرْآنِ مِنْ وَقْفٍ وَجَبْ …","options":["وَلَا حَرَامٌ؛ غَيْرُ مَا لَهُ سَبَبْ","أَوْ عَرَضَ السُّكُونُ وَقْفاً مُسْجَلَا","فِي المُصْحَفِ الإِمَامِ فِيمَا قَدْ أَتَى"],"arabicOptions":true,"answerIndex":0,"why":"No stop in the Qur'an is in itself obligatory or forbidden - nobody is sinful for passing one by. <span class='ar'>غَيْرُ مَا لَهُ سَبَبْ</span> is the exception: the stop that ruins the meaning."}],"_state":"verified","url":"https://www.youtube.com/watch?v=tOW9ZVAI0eU&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=19"},{"ep":20,"title_en":"Marks Above the Line","title_ar":"عَلَامَاتُ الوَقْفِ فِي المُصْحَفِ","summary":"Those small marks printed above the line - مـ، لا، ج، صلى، قلى and the three dots - what is each one actually telling you to do?","teach":[{"label_en":"Never Split These","title_ar":"لَا يُوقَفُ عَلَى...","mnemonic":"حُرًّا مُخْتَارًا","tone":"stop","body":"Not between a <span class='ar'>فعل</span> and its <span class='ar'>فاعل</span>, a <span class='ar'>فاعل</span> and its <span class='ar'>مفعول</span>, a <span class='ar'>مضاف</span> and its <span class='ar'>مضاف إليه</span>, a <span class='ar'>مبتدأ</span> and its <span class='ar'>خبر</span>, a <span class='ar'>موصوف</span> and its <span class='ar'>صفة</span>, a <span class='ar'>حرف جر</span> and its <span class='ar'>مجرور</span>, a <span class='ar'>معطوف عليه</span> and its <span class='ar'>معطوف</span>, a <span class='ar'>صاحب الحال</span> and its <span class='ar'>حال</span>, an <span class='ar'>عدد</span> and its <span class='ar'>معدود</span>, a <span class='ar'>مؤكَّد</span> and its <span class='ar'>توكيد</span>. Every one of these describes a stop you <em>choose</em>."},{"label_en":"Stop / Don't Stop","title_ar":"مـ ولا","letters":"مـ   لا","tone":"stop","body":"<span class='ar'>مـ</span> is <span class='ar'>الوقف اللازم</span>: stop, because joining on would hand the ear a meaning the āya does not carry. <span class='ar'>لا</span> is the opposite warning - the sense is not finished at this word."},{"label_en":"Which Is Better","title_ar":"صلى وقلى","letters":"صلى   قلى","tone":"between","body":"Both marks leave the choice with you and only name the better option. <span class='ar'>صلى</span> = <span class='ar'>الوصل أولى</span>, <span class='ar'>قلى</span> = <span class='ar'>الوقف أولى</span> - each is carved from its own phrase, so the <span class='ar'>ص</span> is the <span class='ar'>ص</span> of <span class='ar'>وصل</span> and the <span class='ar'>ق</span> is the <span class='ar'>ق</span> of <span class='ar'>وقف</span>."},{"label_en":"Equal, or Either-Or","title_ar":"ج والمُعَانَقَة","letters":"ج   ∴ … ∴","tone":"flow","body":"<span class='ar'>ج</span> means the two sides are equally sound - stop or join as you wish. Three dots printed twice mark <span class='ar'>وقف المعانقة</span>: take one of the two places, never both."}],"questions":[{"type":"choice","q":"You meet this mark above the line. What is it telling you?","bigArabic":"مـ","options":["Stop here - joining on would distort the meaning","Do not stop here","Stopping and joining are equally good","Joining is better, but you may stop"],"answerIndex":0,"why":"<span class='ar'>الوقف اللازم</span>. The <span class='ar'>لزوم</span> is <span class='ar'>اصطلاحي</span> - a convention of the scholars of waqf to guard the meaning. Don't confuse it with the <span class='ar'>مـ</span> of <span class='ar'>الإقلاب</span>: this one is flat, with a <span class='ar'>مطة</span> and no lower part; that one drops a tail below the line."},{"type":"choice","q":"The muṣḥaf prints <span class='ar'>مـ</span> after <span class='ar'>يَسْمَعُونَ</span>. What goes wrong if you read straight through?","ayah":"إِنَّمَا يَسْتَجِيبُ ٱلَّذِينَ يَسْمَعُونَ ۘ وَٱلْمَوْتَىٰ يَبْعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ","ref":"Sūrat al-Anʿām 6:36","options":["<span class='ar'>وَٱلْمَوْتَىٰ</span> would be heard as a second group who respond","<span class='ar'>يَسْمَعُونَ</span> would be left without its <span class='ar'>فاعل</span>","<span class='ar'>ٱلَّذِينَ</span> would be cut off from its <span class='ar'>صلة</span>"],"answerIndex":0,"why":"Joined, the ear takes <span class='ar'>وَٱلْمَوْتَىٰ</span> as coupled to <span class='ar'>ٱلَّذِينَ يَسْمَعُونَ</span>. The stop keeps it as the opening of a fresh sentence whose <span class='ar'>خبر</span> is <span class='ar'>يَبْعَثُهُمُ ٱللَّهُ</span>."},{"type":"choice","q":"<span class='ar'>لا</span> stands after <span class='ar'>وَصَدَّقَ بِهِۦٓ</span>. Why is a chosen stop refused there?","ayah":"وَٱلَّذِى جَآءَ بِٱلصِّدْقِ وَصَدَّقَ بِهِۦٓ ۙ أُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ","ref":"Sūrat az-Zumar 39:33","options":["<span class='ar'>أُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ</span> is the <span class='ar'>خبر</span> of <span class='ar'>وَٱلَّذِى</span>","<span class='ar'>وَصَدَّقَ</span> is still waiting for its <span class='ar'>فاعل</span>","<span class='ar'>بِهِۦٓ</span> is a <span class='ar'>جار ومجرور</span> and can never end a stop"],"answerIndex":0,"why":"<span class='ar'>وَٱلَّذِى</span> opens as <span class='ar'>مبتدأ</span> and nothing has yet been said about it. The whole clause <span class='ar'>أُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ</span> is its <span class='ar'>خبر</span>, and a <span class='ar'>مبتدأ</span> is not cut from its <span class='ar'>خبر</span>."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span> from <span class='ar'>المقدمة الجزرية</span>:","verseStem":"وَلَيْسَ فِي القُرْآنِ مِنْ وَقْفٍ وَجَبْ …","options":["وَلَا حَرَامٌ؛ غَيْرُ مَا لَهُ سَبَبْ","وَلَا مُبَاحٌ؛ غَيْرُ مَا لَهُ سَبَبْ","وَلَا مَكْرُوهٌ؛ غَيْرُ مَا لَهُ سَبَبْ"],"arabicOptions":true,"answerIndex":0,"why":"Ibn al-Jazarī denies both extremes in one line: no stop in the Qur'an is in itself <span class='ar'>واجب</span> and none is in itself <span class='ar'>حرام</span>. That is why <span class='ar'>مـ</span> is called <span class='ar'>لازم</span> by convention and <span class='ar'>لا</span> is a warning about meaning."},{"type":"choice","q":"The mark before <span class='ar'>فَٱرْجِعِ ٱلْبَصَرَ</span> is <span class='ar'>صلى</span>. What is it telling you?","ayah":"ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍۢ طِبَاقًۭا ۖ مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَٰنِ مِن تَفَٰوُتٍۢ ۖ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍۢ","ref":"Sūrat al-Mulk 67:3","options":["You may stop, but joining is better","You may join, but stopping is better","You must join here","The two choices are exactly equal"],"answerIndex":0,"why":"<span class='ar'>فَٱرْجِعِ ٱلْبَصَرَ</span> can stand as a fresh sentence, which is what makes a stop permissible. But the invitation to look again points back at <span class='ar'>خَلَقَ سَبْعَ سَمَٰوَٰتٍۢ طِبَاقًۭا ۖ مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَٰنِ</span> just before it, so the two halves are better kept together."},{"type":"choice","q":"<span class='ar'>قلى</span> stands after <span class='ar'>فَٱقْتُلُوهُمْ</span>. Which reading does it recommend?","ayah":"فَإِن قَٰتَلُوكُمْ فَٱقْتُلُوهُمْ ۗ كَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ","ref":"Sūrat al-Baqara 2:191 (part of the āya)","options":["Stop - that is better, though joining is allowed","Join - that is better, though stopping is allowed","Stop - joining is not allowed here"],"answerIndex":0,"why":"<span class='ar'>قلى</span> is carved from <span class='ar'>الوقف أولى</span>. Joining stays open, but <span class='ar'>كَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ</span> gives the reason behind the ruling rather than continuing it, and the stop keeps the two apart."},{"type":"choice","q":"<span class='ar'>ج</span> is printed after <span class='ar'>عَمَلًۭا</span>. What does it mean?","ayah":"ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًۭا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ","ref":"Sūrat al-Mulk 67:2","options":["Either choice is sound - the two sides stand level","Stopping is required","Joining is better, stopping allowed","Stopping is better, joining allowed"],"answerIndex":0,"why":"Read <span class='ar'>وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ</span> as a <span class='ar'>جملة حالية</span> and you must join. Read the <span class='ar'>واو</span> as beginning a new sentence, with <span class='ar'>هو</span> as <span class='ar'>مبتدأ</span>, and you may stop. Both are sound, so neither outranks the other."},{"type":"multi","q":"Tap the three marks that leave the choice to you.","pool":["مـ","لا","ج","صلى","قلى"],"answers":["ج","صلى","قلى"],"why":"<span class='ar'>ج</span>، <span class='ar'>صلى</span> and <span class='ar'>قلى</span> all permit both stopping and joining; only <span class='ar'>صلى</span> and <span class='ar'>قلى</span> go further and name a preference. <span class='ar'>مـ</span> and <span class='ar'>لا</span> each push you one way."},{"type":"choice","q":"The three dots appear twice in this āya. What do they permit?","ayah":"ذَٰلِكَ ٱلْكِتَٰبُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًۭى لِّلْمُتَّقِينَ","ref":"Sūrat al-Baqara 2:2","options":["A stop at one of the two places, never at both","A stop at both places","A stop at neither place","A stop at the first place only"],"answerIndex":0,"why":"<span class='ar'>وقف المعانقة</span>, also called <span class='ar'>وقف المراقبة</span> - the two spots watch each other. Spending one forfeits the other."},{"type":"choice","q":"Suppose you stop at <span class='ar'>لَا رَيْبَ</span> and begin again. Where does <span class='ar'>فِيهِ</span> then belong?","ayah":"ذَٰلِكَ ٱلْكِتَٰبُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًۭى لِّلْمُتَّقِينَ","ref":"Sūrat al-Baqara 2:2","options":["With <span class='ar'>هُدًۭى</span> - guidance <em>in it</em> for the God-fearing","With <span class='ar'>لَا رَيْبَ</span> - no doubt <em>in it</em>","With <span class='ar'>ذَٰلِكَ ٱلْكِتَٰبُ</span>"],"answerIndex":0,"why":"Each stop fixes one <span class='ar'>إعراب</span>. Take the other stop instead and <span class='ar'>فِيهِ</span> swings back to <span class='ar'>لَا رَيْبَ</span>, leaving <span class='ar'>هُدًۭى</span> as the <span class='ar'>خبر</span> of an unspoken <span class='ar'>هو</span>. The mark exists because both readings are sound."},{"type":"choice","q":"The rule “do not stop on the <span class='ar'>معطوف عليه</span> without the <span class='ar'>معطوف</span>” - which kind of <span class='ar'>عطف</span> is it about?","options":["عطف المفردات","عطف الجمل","Both alike"],"arabicOptions":true,"answerIndex":0,"why":"In <span class='ar'>إِنَّ ٱلْمُسْلِمِينَ وَٱلْمُسْلِمَٰتِ وَٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ …</span> (الأحزاب 33:35) the words are links in one chain, and breaking off mid-chain leaves the sense hanging. In <span class='ar'>إِذَا جَآءَكَ ٱلْمُنَٰفِقُونَ قَالُوا۟ نَشْهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِ ۗ وَٱللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشْهَدُ إِنَّ ٱلْمُنَٰفِقِينَ لَكَٰذِبُونَ</span> (المنافقون 63:1) each <span class='ar'>واو</span> opens a complete sentence - the muṣḥaf even prints <span class='ar'>قلى</span> just before the first of them, so a stop is available there."},{"type":"choice","q":"Every one of these “do not stop” rules carries the same qualifier. What is it?","options":["They govern the stop you choose - <span class='ar'>حرًّا مختارًا</span>","They apply only outside of prayer","They apply only at <span class='ar'>رؤوس الآي</span>"],"answerIndex":0,"why":"Breath runs out and you stop where you must. The rules then tell you what to do next: go back and begin again from a place where the sense starts clean."}],"_state":"verified","url":"https://www.youtube.com/watch?v=bteuCHz-mRM&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=20"},{"ep":21,"title_en":"How It Reached Us","title_ar":"مقدمة القسم الثاني ـ التلقي المكتوب والتلقي المنطوق","summary":"Fifteen centuries and a hundred dialects on, why do skilled reciters everywhere sound like they sat with one teacher?","teach":[{"label_en":"Written","title_ar":"التلقي المكتوب","tone":"stop","body":"What the imams set down: the <span class='ar'>مخارج</span>, the <span class='ar'>صفات</span>, the timings of <span class='ar'>المدود</span> and <span class='ar'>الغنن</span>. It is the rail - it moves nothing itself, but it stops the train swerving."},{"label_en":"Spoken","title_ar":"التلقي المنطوق","tone":"flow","body":"What you take mouth-to-mouth from a teacher whose chain reaches the Prophet ﷺ. Neither half works alone: books without a teacher make you <span class='ar'>مُطَّلِعًا</span>, not <span class='ar'>مُقْرِئًا</span>."},{"label_en":"Two kinds of error","title_ar":"اللحن الجلي واللحن الخفي","tone":"between","body":"<span class='ar'>الجلي</span> changes a letter or a ḥaraka, so the word itself changes - corrected for everyone. <span class='ar'>الخفي</span> breaks a rule while the word stays intact - taught gently, pressed hard only in <span class='ar'>مقام التلقي والمشافهة</span>."},{"label_en":"A testimony","title_ar":"الإجازة","tone":"brand","body":"<span class='ar'>أَجَزْتُكَ</span> means: I bear witness that your recitation matches the recitation I read to my own teacher. A word too heavy to say unless it is true."}],"questions":[{"type":"choice","q":"He names two things that together carried the <em>pronunciation</em> of the Qur'an intact across fifteen centuries. Which pair?","options":["<span class='ar'>التلقي المكتوب</span> and <span class='ar'>التلقي المنطوق</span>","<span class='ar'>الرسم العثماني</span> and <span class='ar'>علامات الضبط</span>","<span class='ar'>علم الأصوات الحديث</span> and <span class='ar'>فيزياء الأصوات</span>"],"answerIndex":0,"why":"What the imams wrote is the rail; what you take from a living teacher is the train on it. Neither moves straight without the other."},{"type":"choice","q":"A respected contemporary shaykh teaches a pronunciation no imam ever recorded, saying: this is how I received it. What follows?","options":["It is not taken - no one may bring what the imams did not record","It is taken, because oral transmission outranks books","It is taken as long as he can name his isnād"],"answerIndex":0,"why":"The oral chain is authoritative <em>inside</em> what the books describe, never outside it."},{"type":"choice","q":"Years of studying tajwīd books at home, never once reading aloud to a teacher. What does that make him?","options":["مُقْرِئ","مُطَّلِع","مُجَاز"],"arabicOptions":true,"answerIndex":1,"why":"<span class='ar'>مُطَّلِع</span> - well-read on the imams' words. <span class='ar'>المُقْرِئ</span> is the one whose own letters were corrected by ear, by a teacher with a connected chain."},{"type":"choice","q":"A reader pronounces the <span class='ar'>ت</span> of the last word as a <span class='ar'>ط</span>. What has he committed?","ayah":"لِيُنذِرَ يَوْمَ ٱلتَّلَاقِ","ref":"Sūrat Ghāfir 40:15","options":["<span class='ar'>لحن جلي</span>","<span class='ar'>لحن خفي</span>","No error - only a weak <span class='ar'>أداء</span>"],"answerIndex":0,"why":"<span class='ar'>التلاق</span> is the Day of Meeting; <span class='ar'>الطلاق</span> is divorce. One letter and the word is gone."},{"type":"choice","q":"Which one does he say we press on with full strictness only in <span class='ar'>مقام التلقي والمشافهة</span>?","options":["<span class='ar'>اللحن الخفي</span>","<span class='ar'>اللحن الجلي</span>","Both, equally"],"answerIndex":0,"why":"<span class='ar'>الجلي</span> is corrected for every reader, because it changes the word. <span class='ar'>الخفي</span> leaves the word intact - so the general reader is taught it gently, while the student seeking <span class='ar'>إجازة</span> is asking to become a copy of his teacher, and there nothing is let through."},{"type":"choice","q":"He tells of a man who meant <span class='ar'>مِنْ أَخَصِّ تَلَامِيذِ أُسْتَاذِنَا</span> - 'one of our teacher's closest students' - but out came <span class='ar'>أَخَسّ</span>, 'basest'. What did he fail to give the letter?","bigArabic":"ص","options":["<span class='ar'>الإطباق والاستعلاء (التفخيم)</span>, so it collapsed into a <span class='ar'>س</span>","<span class='ar'>القلقلة</span> at the stop","Its full length","Its <span class='ar'>غنة</span>"],"answerIndex":0,"why":"<span class='ar'>ص</span>, <span class='ar'>ز</span> and <span class='ar'>س</span> share one <span class='ar'>مخرج</span> and all three whistle (<span class='ar'>صفير</span>); what lifts <span class='ar'>ص</span> away from <span class='ar'>س</span> is <span class='ar'>الاستعلاء والإطباق</span> - let the tongue lie flat and you have said a different word."},{"type":"choice","q":"Which mnemonic does this <span class='ar'>بيت</span> of <span class='ar'>المقدمة الجزرية</span> give for <span class='ar'>القلقلة</span>?","verseStem":"صَفِيرُهَا: صَادٌ وَزَايٌ سِينُ … قَلْقَلَةٌ:","options":["«قُطْبُ جَدٍ»","«أَجِدْ قَطٍ بَكَتْ»","«خُصَّ ضَغْطٍ قِظْ»","«فَرَّ مِنْ لُبِّ»"],"arabicOptions":true,"answerIndex":0,"why":"He quoted this very mnemonic to make his point about new books: you may change the cup, never the drink. <span class='ar'>القلقلة</span> was <span class='ar'>قُطْبُ جَدٍ</span> before us and stays <span class='ar'>قُطْبُ جَدٍ</span> after us."},{"type":"multi","q":"Tap the letters of <span class='ar'>القلقلة</span>.","pool":["ق","ت","ط","ك","ب","ز","ج","س","د","ء"],"answers":["ق","ط","ب","ج","د"],"why":"Five - <span class='ar'>قُطْبُ جَدٍ</span>. The same line lists them straight after <span class='ar'>حروف الصفير</span> (<span class='ar'>ص ز س</span>), which is why the two get run together from memory."},{"type":"choice","q":"Sībawayh said of his own teacher: <span class='ar'>ذَاقَ الحُرُوفَ</span> - 'he tasted the letters.' Who?","options":["الخليل بن أحمد الفراهيدي","ابن الجزري","مكي بن أبي طالب القيسي","أبو عمرو الداني"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>الخليل</span> arranged his dictionary <span class='ar'>كتاب العين</span> by <span class='ar'>مخرج</span> rather than by alphabet - letters described from inside the mouth, not listed from outside it."},{"type":"choice","q":"<span class='ar'>أَجَزْتُكَ</span> - what is the teacher actually saying?","options":["'I bear witness that your recitation matches the recitation I read to my teacher'","'You have finished the book with me'","'You are now permitted to teach beginners'"],"answerIndex":0,"why":"That is why he calls it <span class='ar'>أمانة</span>: it is testimony, given before Allah, about someone else's mouth."},{"type":"choice","q":"Correct recitation is not the end of the road. By the āya he cited, it is the road to what?","ayah":"كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ مُبَٰرَكٌۭ لِّيَدَّبَّرُوٓا۟ ءَايَٰتِهِۦ","ref":"Sūrat Ṣād 38:29","options":["التدبر","الحفظ","الإجازة"],"arabicOptions":true,"answerIndex":0,"why":"The āya states the purpose of the sending down itself - <span class='ar'>لِّيَدَّبَّرُوٓا۟ ءَايَٰتِهِۦ</span>. Sound recitation clears the road to the meaning; it is not a substitute for arriving."}],"_state":"verified","url":"https://www.youtube.com/watch?v=KvIwlbpMWIs&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=21"},{"ep":22,"title_en":"One Strike, Not Two","title_ar":"باب الحرفين الملتقيين والإدغام","summary":"When two letters meet, when does the first vanish into the second?","teach":[{"label_en":"Four Ways to Meet","title_ar":"الحرفان الملتقيان","count":"4 cases","tone":"brand","body":"Any two neighbouring letters are either the same letter (<span class='ar'>متماثلان</span>), one <span class='ar'>مخرج</span> with some <span class='ar'>صفات</span> differing (<span class='ar'>متجانسان</span>), close without being identical - in <span class='ar'>المخرج</span>, in <span class='ar'>الصفات</span>, or in both (<span class='ar'>متقاربان</span>) - or unrelated (<span class='ar'>متباعدان</span>). Every ruling in this chapter is read off that map."},{"label_en":"One Strike","title_ar":"الإدغام","tone":"flow","body":"In the language it means insertion - <span class='ar'>أَدْغَمْتُ السَّيْفَ فِي غِمْدِهِ</span>, I slid the sword into its sheath. In recitation: a sākin letter is joined to the <span class='ar'>متحرك</span> after it, and the <span class='ar'>مخرج</span> is struck once instead of twice. When the merger is complete the two become one <span class='ar'>مشدد</span> letter of the <strong>second</strong> letter's kind; when it is <span class='ar'>ناقص</span>, the first letter keeps some of its <span class='ar'>صفات</span>."},{"label_en":"Twins","title_ar":"المتماثلان","tone":"stop","body":"The same letter twice with the first sākin: merging is obligatory - leaving it clear is broken Arabic, not merely weak tajwīd. The exception in this chapter: a <span class='ar'>حرف مد</span> is never merged. (Ḥafṣ also reads <span class='ar'>مَالِيَهْ</span> … <span class='ar'>هَلَكَ</span> with a <span class='ar'>سكتة</span>, keeping those two <span class='ar'>هـ</span> clear.)"},{"label_en":"Eight Meetings","title_ar":"المتجانسان","count":"8 cases","letters":"ذ ← ظ ، د ← ت ، ت ← د ، ت ← ط ، ل ← ر ، ث ← ذ ، ب ← م ، ط ← ت","tone":"between","body":"One <span class='ar'>مخرج</span>, some <span class='ar'>صفات</span> differing - and the chapter counts eight pairings where such a meeting actually occurs. The fifth, <span class='ar'>ل</span> into <span class='ar'>ر</span>, is counted here <span class='ar'>على رأي الفراء والمبرد</span>; <span class='ar'>على مذهب الخليل</span> it belongs with <span class='ar'>المتقاربان</span>. The last, <span class='ar'>ط</span> into <span class='ar'>ت</span>, is <span class='ar'>إدغام ناقص</span>: the <span class='ar'>إطباق</span> of the <span class='ar'>ط</span> survives the merger."}],"questions":[{"type":"choice","q":"Two letters meet and they are the same letter - one <span class='ar'>مخرج</span>, the same <span class='ar'>صفات</span>. What are they called?","options":["متماثلان","متجانسان","متقاربان","متباعدان"],"arabicOptions":true,"answerIndex":0,"why":"The other three name the other outcomes of a meeting: one <span class='ar'>مخرج</span> with some <span class='ar'>صفات</span> differing, close <span class='ar'>مخارج</span>, and no relation at all."},{"type":"choice","q":"<span class='ar'>متجانسان</span> share a single <span class='ar'>مخرج</span>. How do they differ?","options":["في بعض الصفات","في جميع الصفات","في المخرج","في الحركة"],"arabicOptions":true,"answerIndex":0,"why":"The word <span class='ar'>بعض</span> is what makes the definition accurate: <span class='ar'>د</span> and <span class='ar'>ت</span> are both <span class='ar'>شديدة</span> - both sit in <span class='ar'>«أَجِدْ قَطٍ بَكَتْ»</span> - so they cannot differ in every <span class='ar'>صفة</span>."},{"type":"choice","q":"Why can two <span class='ar'>ألف</span> never stand side by side?","bigArabic":"ا","options":["Every ألف needs a fatḥa on the letter before it, and an ألف can never carry a fatḥa","الألف has no مخرج of its own","الألف is always متحركة, and only a sākin letter can be merged"],"answerIndex":0,"why":"<span class='ar'>الألف</span> is the one letter that is always sākin and always preceded by a fatḥa. That is why this chapter works with 28 letters that can meet a twin, not 29."},{"type":"multi","q":"A sākin letter merging into its twin is obligatory - unless it is a <span class='ar'>حرف مد</span>. Tap the three <span class='ar'>حروف المد</span>.","pool":["ا","و","ي","ه","ء","ر","ل","ن"],"answers":["ا","و","ي"],"why":"Merging a <span class='ar'>حرف مد</span> would swallow the very length it exists to carry, so it is excluded by definition."},{"type":"choice","q":"The <span class='ar'>و</span> ending <span class='ar'>قَالُوا</span> meets the <span class='ar'>و</span> of <span class='ar'>وَهُمْ</span>. What is read?","ayah":"قَالُوا وَهُمْ فِيهَا يَخْتَصِمُونَ","ref":"Sūrat ash-Shuʿarāʾ 26:96","options":["إظهار - the first و is a حرف مد","إدغام, giving one doubled و","إخفاء with غنة"],"answerIndex":0,"why":"Ibn al-Jazarī names this exact phrase among the exceptions: <span class='ar'>وَأَبِنْ … «قَالُوا وَهُمْ»</span>. Merging it would cost the <span class='ar'>مد</span> its length."},{"type":"choice","q":"Here the <span class='ar'>و</span> of <span class='ar'>عَفَوا</span> IS merged into the <span class='ar'>و</span> after it. Why?","ayah":"حَتَّىٰ عَفَوا وَّقَالُوا","ref":"Sūrat al-Aʿrāf 7:95","options":["It is a واو لينة, not a واو مدية","Because the second و carries a fatḥa","Because the two sit in different words"],"answerIndex":0,"why":"A sākin <span class='ar'>و</span> after a fatḥa is <span class='ar'>لينة</span>; it is <span class='ar'>مدية</span> only after a ḍamma. Only the <span class='ar'>مدية</span> one is protected from merging."},{"type":"choice","q":"What is the relationship between the <span class='ar'>د</span> and the <span class='ar'>ت</span> here?","ayah":"قَد تَّبَيَّنَ","ref":"Sūrat al-Baqara 2:256","options":["متماثلان","متجانسان","متقاربان","متباعدان"],"arabicOptions":true,"answerIndex":1,"why":"<span class='ar'>د</span> and <span class='ar'>ت</span> come out of one <span class='ar'>مخرج</span> - the tongue-tip against the roots of the upper front teeth - but differ in some <span class='ar'>صفات</span>: <span class='ar'>د</span> is <span class='ar'>مجهورة</span> with <span class='ar'>قلقلة</span>, <span class='ar'>ت</span> is <span class='ar'>مهموسة</span>. Same <span class='ar'>مخرج</span>, some <span class='ar'>صفات</span> differing, is exactly <span class='ar'>متجانسان</span>. Stop on the first word and the <span class='ar'>د</span> comes straight back."},{"type":"multi","q":"Which letters come out of the tongue-tip against the roots of the upper front teeth?","pool":["ط","د","ت","ظ","ذ","ث","س","ز","ل","ن","ر"],"answers":["ط","د","ت"],"why":"<span class='ar'>الجزرية</span>: <span class='ar'>«وَالطَّاءُ وَالدَّالُ وَتَا: مِنْهُ وَمِنْ … عُلْيَا الثَّنَايَا»</span>. Sharing that one <span class='ar'>مخرج</span> is exactly what makes them <span class='ar'>متجانسة</span> with one another."},{"type":"choice","q":"Joined up, the <span class='ar'>ب</span> merges into the <span class='ar'>م</span>. Now stop on <span class='ar'>ٱرْكَب</span> - what do you say?","ayah":"يَٰبُنَىَّ ٱرْكَب مَّعَنَا","ref":"Sūrat Hūd 11:42","options":["a clear ب, released with قلقلة","a م","a ب with no قلقلة"],"answerIndex":0,"why":"<span class='ar'>ب</span> and <span class='ar'>م</span> are both from the lips and differ in some <span class='ar'>صفات</span>, so they are <span class='ar'>متجانسان</span>. Stopping removes the <span class='ar'>م</span> that caused the merger, and the poem ties the <span class='ar'>قلقلة</span> to exactly this case: <span class='ar'>«وَبَيِّنَنْ مُقَلْقَلاً إِنْ سَكَنَا … وَإِنْ يَكُنْ فِي الوَقْفِ كَانَ أَبْيَنَا»</span>."},{"type":"choice","q":"The <span class='ar'>ط</span> merges into the <span class='ar'>ت</span> - but only partly. What survives?","ayah":"فَقَالَ أَحَطتُ بِمَا","ref":"Sūrat an-Naml 27:22","options":["الإطباق of the ط","القلقلة of the ط","Nothing - the merger is complete"],"answerIndex":0,"why":"This is <span class='ar'>الإدغام الناقص</span>: the stronger letter does not vanish entirely into the weaker one. It occurs in four words only - <span class='ar'>بَسَطتَ، فَرَّطتُمْ، أَحَطتُ، فَرَّطتُ</span> - and the <span class='ar'>ط</span> takes no <span class='ar'>قلقلة</span> in them."},{"type":"choice","q":"Every case in this chapter needs the first letter to be sākin. What is it called when the first letter is <span class='ar'>متحرك</span> instead?","options":["الإدغام الكبير","الإدغام الناقص","الإدغام الصغير"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>الإدغام الكبير</span> as a running system is related from Abū ʿAmr al-Baṣrī; Ḥafṣ has only a handful of fixed cases - <span class='ar'>تَأْمَنَّا</span> (12:11), <span class='ar'>مَكَّنِّى</span> (18:95), <span class='ar'>نِعِمَّا</span>. Everything in this chapter is <span class='ar'>صغير</span> - the first letter already carries its <span class='ar'>سكون</span>."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span> from <span class='ar'>المقدمة الجزرية</span>:","verseStem":"وَأَوَّلَيْ مِثْلٍ وَجِنْسٍ إِنْ سَكَنْ …","options":["أَدْغِمْ","أَظْهِرْ","أَخْفِ"],"arabicOptions":true,"answerIndex":0,"why":"The <span class='ar'>عجز</span> then supplies its own examples - <span class='ar'>«قُلْ رَبِّ»</span> and <span class='ar'>«بَلْ لَا»</span> - before <span class='ar'>وَأَبِنْ</span> turns to the letters you must keep clear."}],"_state":"verified","url":"https://www.youtube.com/watch?v=Z9hDuv7DYMQ&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=22"},{"ep":23,"title_en":"Close Enough To Merge","title_ar":"بابُ الحرفين المتقاربين والمتباعدين ولامِ التعريف","summary":"When two letters are merely neighbours: which merges does every qārīʾ agree on - and which belong to القراءات?","teach":[{"label_en":"Near Neighbours","title_ar":"الحرفان المتقاربان","tone":"between","body":"Two letters close to one another in <span class='ar'>المخرج</span> and in <span class='ar'>الصفات</span> - like <span class='ar'>ق</span> and <span class='ar'>ك</span>, or <span class='ar'>ل</span> and <span class='ar'>ر</span>. Most of their <span class='ar'>إدغام</span> is disputed between the <span class='ar'>قراء</span>, so it belongs to <span class='ar'>علم القراءات</span> rather than to tajwīd."},{"label_en":"The Agreed Four","title_ar":"المتفق عليه","count":"4 cases","tone":"brand","body":"Only four merges of <span class='ar'>المتقاربين</span> are agreed by every <span class='ar'>قارئ</span>, and only these are taught in tajwīd: <span class='ar'>ل</span> into <span class='ar'>ر</span>, <span class='ar'>ق</span> into <span class='ar'>ك</span> in <span class='ar'>نَخْلُقكُّم</span>, <span class='ar'>لام التعريف</span> before thirteen of the <span class='ar'>شمسية</span> letters (the fourteenth, <span class='ar'>ل</span>, is <span class='ar'>متماثلين</span>), and <span class='ar'>النون الساكنة والتنوين</span> into <span class='ar'>ي ر م ل و</span>."},{"label_en":"Sun and Moon","title_ar":"لام التعريف","count":"14 + 14","mnemonic":"ابْغِ حَجَّكَ وَخَفْ عَقِيمَهُ","letters":"أ ب غ ح ج ك و خ ف ع ق ي م ه","tone":"flow","body":"<span class='ar'>ال</span> is a sākin lām carried in by a hamzat waṣl. Before the fourteen letters of this phrase it is pronounced - <span class='ar'>قمرية</span>; before the other fourteen it merges into them - <span class='ar'>شمسية</span>."},{"label_en":"Reading The Marks","title_ar":"علامات الضبط","tone":"stop","body":"<span class='ar'>إدغام كامل</span>: the first letter bare of any sukūn, the next carrying a shadda. <span class='ar'>إدغام ناقص</span> and <span class='ar'>الإخفاء</span>: the first letter still bare, but the next with no shadda on it - and nothing else written above it. A small <span class='ar'>مـ</span> above the first letter means <span class='ar'>الإقلاب</span> instead."}],"questions":[{"type":"choice","q":"Which two letters of <span class='ar'>المتقاربين</span> are merged into one another in this āya?","ayah":"أَلَمْ نَخْلُقكُّم مِّن مَّآءٍ مَّهِينٍ","ref":"Sūrat al-Mursalāt 77:20","options":["ق في ك","ك في ق","خ في ل","ق في خ"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>ق</span> and <span class='ar'>ك</span> both issue from <span class='ar'>أقصى اللسان</span>, one just forward of the other - neighbouring <span class='ar'>مخرجان</span>, and every <span class='ar'>قارئ</span> merges them here."},{"type":"choice","q":"In the riwāya of Ḥafṣ, by both the Shāṭibiyya and the Ṭayyiba, this idghām is:","bigArabic":"نَخْلُقكُّم","options":["إدغام كامل - a pure doubled kāf, no trace of the qāf","إدغام ناقص - keeping the qāf's استعلاء","إظهار - the qāf stays fully audible"],"answerIndex":0,"why":"The muṣḥaf settles it: the qāf bare of sukūn, the kāf carrying shadda and ḍamma. The incomplete reading, which keeps the <span class='ar'>استعلاء</span>, is transmitted for Ḥafṣ elsewhere - but by no ṭarīq of these two."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span> from <span class='ar'>المقدمة الجزرية</span>:","verseStem":"وَبَيِّنِ الإِطْبَاقَ مِنْ «أَحَطْتُ» مَعْ …","options":["«بَسَطْتَ»، وَالخُلْفُ بِـ «نَخْلُقْكُمْ» وَقَعْ","«بَسَطْتَ»، وَالخُلْفُ بِـ «يَلْهَثْ ذَلِكَ» وَقَعْ","«بَسَطْتَ»، وَالخُلْفُ بِـ «ارْكَبْ مَعَنَا» وَقَعْ"],"arabicOptions":true,"answerIndex":0,"why":"The <span class='ar'>خلف</span> Ibn al-Jazarī points to in <span class='ar'>نَخْلُقْكُمْ</span> is between a complete and an incomplete idghām - not between idghām and iẓhār. He is describing the qurrāʾ at large, not Ḥafṣ alone."},{"type":"choice","q":"In the muṣḥaf, what marks an <span class='ar'>إدغام كامل</span>?","options":["The first letter bare of any sukūn, the next carrying a shadda","The first letter carrying a sukūn, the next a shadda","Both letters bare, with no shadda anywhere","A small مـ written above the first letter"],"answerIndex":0,"why":"The bare letter says it has vanished; the shadda says the next letter has fully absorbed it."},{"type":"choice","q":"The first letter bare of sukūn, the following letter with <em>no</em> shadda, and nothing written above either. Which two rulings share this one mark?","options":["إدغام ناقص and الإخفاء","إدغام كامل and الإقلاب","الإظهار and إدغام كامل","الإقلاب and الإظهار"],"answerIndex":0,"why":"No shadda is written because something of the first letter survives in both cases - so the second letter was never fully doubled."},{"type":"choice","q":"What happens to the <span class='ar'>لام</span> of <span class='ar'>قُل</span> here?","ayah":"قُل رَّبِّ إِمَّا تُرِيَنِّى مَا يُوعَدُونَ","ref":"Sūrat al-Muʾminūn 23:93","options":["تُدغَم في الراء","تُظهَر","تُخفى","تُقلَب"],"arabicOptions":true,"answerIndex":0,"why":"Not one qāriʾ pronounces that lām. The books disagree only over the filing - some place <span class='ar'>ل</span> with <span class='ar'>ر</span> under <span class='ar'>المتقاربين</span>, others under <span class='ar'>المتجانسين</span> - never over the ruling."},{"type":"choice","q":"How does Ḥafṣ read the <span class='ar'>ت</span> of <span class='ar'>كَذَّبَتْ</span> before the <span class='ar'>ث</span>?","ayah":"كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ","ref":"Sūrat ash-Shams 91:11","options":["بالإظهار","بالإدغام","بالإخفاء"],"arabicOptions":true,"answerIndex":0,"why":"Some qurrāʾ do merge it, and the merged form is easier on the tongue - but recitation rests on <span class='ar'>التلقي والرواية</span>, never on ease or analogy."},{"type":"choice","q":"The disputed merges of <span class='ar'>المتقاربين</span> - the <span class='ar'>ذ</span> into <span class='ar'>ز</span> here, or the <span class='ar'>د</span> into <span class='ar'>ض</span> elsewhere - are studied in which science?","ayah":"وَإِذْ زَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ","ref":"Sūrat al-Anfāl 8:48","options":["علم القراءات","علم التجويد","علم النحو"],"arabicOptions":true,"answerIndex":0,"why":"Tajwīd carries what the qurrāʾ agree on; where they part ways the question moves to <span class='ar'>القراءات</span>. Ḥafṣ pronounces both of these letters clearly."},{"type":"choice","q":"<span class='ar'>الحرفان المتباعدان</span> - two letters far apart in both <span class='ar'>المخرج</span> and <span class='ar'>الصفات</span>, like the <span class='ar'>ء</span> and the <span class='ar'>م</span> of <span class='ar'>يُؤْمِنُونَ</span>. What is the ruling?","options":["الإظهار","الإدغام","الإخفاء","الإقلاب"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>الإظهار</span> is the default whenever two letters meet. Idghām and ikhfāʾ are the exceptions, and they need closeness to earn themselves."},{"type":"multi","q":"Tap the letters after which <span class='ar'>لام التعريف</span> is <em>pronounced</em>.","pool":["ب","ت","ج","د","ر","س","ط","غ","ف","ك","ل","ن"],"answers":["ب","ج","غ","ف","ك"],"why":"<span class='ar'>ابْغِ حَجَّكَ وَخَفْ عَقِيمَهُ</span> gathers all fourteen <span class='ar'>قمرية</span> letters. The rest of this pool - <span class='ar'>ت د ر س ط ل ن</span> - are <span class='ar'>شمسية</span>."},{"type":"choice","q":"The two occurrences of <span class='ar'>لام التعريف</span> in this āya are:","ayah":"ٱقْتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلْقَمَرُ","ref":"Sūrat al-Qamar 54:1","options":["the first شمسية, the second قمرية","the first قمرية, the second شمسية","both شمسية","both قمرية"],"answerIndex":0,"why":"<span class='ar'>س</span> is not in <span class='ar'>ابْغِ حَجَّكَ وَخَفْ عَقِيمَهُ</span>, so the lām merges; <span class='ar'>ق</span> is in it, so the lām is heard. Look at the muṣḥaf and the marks say the same thing."},{"type":"choice","q":"Thirteen of the fourteen <span class='ar'>شمسية</span> letters give an <span class='ar'>إدغام متقاربين</span>. Which one gives <span class='ar'>إدغام متماثلين</span> instead?","options":["ل","ر","ن","د"],"arabicOptions":true,"answerIndex":0,"why":"In <span class='ar'>الليل</span> the lām of <span class='ar'>ال</span> meets another lām - the same letter twice over, which is <span class='ar'>متماثلان</span> by definition, not merely close."}],"_state":"verified","url":"https://www.youtube.com/watch?v=LMtDtKjEAzI&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=23"},{"ep":24,"title_en":"Lips Together, Lightly","title_ar":"بابُ النون والميم المشددتين وأحكام الميم الساكنة","summary":"When a mīm carries sukūn, do the lips merge it, hide it, or show it - and how much غنة goes with each?","teach":[{"label_en":"Doubled","title_ar":"النون والميم المشددتان","letters":"نّ  مّ","tone":"brand","body":"Wherever a <span class='ar'>ن</span> or a <span class='ar'>م</span> carries a shadda, the <span class='ar'>غنة</span> is held <span class='ar'>أكمل ما تكون</span> - at its fullest. No exceptions, mid-word or at a stop."},{"label_en":"Merged","title_ar":"الإدغام الشفوي","count":"1 letter","letters":"م","tone":"stop","body":"A <span class='ar'>ميم ساكنة</span> followed by another <span class='ar'>م</span>. The lips make and release one closure for both, and the <span class='ar'>غنة</span> is held full."},{"label_en":"Hidden","title_ar":"الإخفاء الشفوي","count":"1 letter","letters":"ب","tone":"between","body":"<span class='ar'>نطق بحرف بصفة بين الإظهار والإدغام، عارٍ عن التشديد، مع بقاء الغنة في الحرف الأول</span> - one gentle lip closure serves both letters, yet the <span class='ar'>م</span>’s own sound survives, slightly diminished, and its <span class='ar'>غنة</span> is held its full length, never clipped."},{"label_en":"Shown","title_ar":"الإظهار الشفوي","count":"26 letters","letters":"ما عدا الميم والباء","tone":"flow","body":"<span class='ar'>إخراج كل حرف من مخرجه من غير زيادة في الغنة</span> - note <em>without extra</em> <span class='ar'>غنة</span>, not <em>without</em> <span class='ar'>غنة</span>. Guard it hardest at <span class='ar'>و</span> and <span class='ar'>ف</span>."}],"questions":[{"type":"choice","q":"What is the ruling on the <span class='ar'>ميم</span> of <span class='ar'>هُم</span> here?","ayah":"وَمَا هُم بِمُؤْمِنِينَ","ref":"Sūrat al-Baqara 2:8 (part of the āya)","options":["إظهار شفوي","إخفاء شفوي","إدغام شفوي"],"arabicOptions":true,"answerIndex":1,"why":"<span class='ar'>م</span> and <span class='ar'>ب</span> share one <span class='ar'>مخرج</span> - <span class='ar'>انطباق الشفتين</span> - so they are <span class='ar'>متجانسان</span>: same <span class='ar'>مخرج</span>, different <span class='ar'>صفات</span>. The <span class='ar'>ب</span> is <span class='ar'>شديد ومقلقل</span>; the <span class='ar'>م</span> is <span class='ar'>متوسط</span> because its sound escapes through the <span class='ar'>الخيشوم</span> as <span class='ar'>غنة</span>. The lips close once for both, and the <span class='ar'>م</span> hides inside that closure, keeping its own <span class='ar'>غنة</span> and never turning into the <span class='ar'>ب</span>."},{"type":"choice","q":"And the <span class='ar'>ميم</span> of <span class='ar'>وَلَكُم</span>?","ayah":"وَلَكُم مَّا كَسَبْتُمْ","ref":"Sūrat al-Baqara 2:134 (part of the āya)","options":["إظهار شفوي","إخفاء شفوي","إدغام شفوي"],"arabicOptions":true,"answerIndex":2,"why":"The muṣḥaf tells you before your ear does: the first <span class='ar'>م</span> bare of any sukūn, the second carrying a shadda. Hold the <span class='ar'>غنة</span> full - clipping it here is the commonest fault."},{"type":"multi","q":"Tap the letters after which a <span class='ar'>ميم ساكنة</span> is <em>not</em> <span class='ar'>مظهرة</span>.","pool":["ب","م","و","ف","ن","ل","ت","ي"],"answers":["ب","م"],"why":"Only these two. The other 26 letters all take <span class='ar'>إظهار شفوي</span> - and <span class='ar'>و</span> and <span class='ar'>ف</span> sit in the pool because they are exactly where the mistake gets made."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span> from <span class='ar'>المقدمة الجزرية</span>:","verseStem":"وَأَظْهِرَنْهَا عِنْدَ: بَاقِي الأَحْرُفِ … وَاحْذَرْ لَدَى وَاوٍ وَفَا:","options":["«أَنْ تَخْتَفِي»","«أَنْ تُدْغَمَا»","«مِنْ كَزِّهَا»"],"arabicOptions":true,"answerIndex":0,"why":"The whole instruction for <span class='ar'>و</span> and <span class='ar'>ف</span> is a prohibition - beware that the <span class='ar'>ميم</span> <em>be hidden</em> there. Everything else in the line is plain <span class='ar'>إظهار</span>."},{"type":"choice","q":"Some tajwīd books write that the <span class='ar'>ميم</span> is <span class='ar'>أشد إظهاراً</span> - ‘more strongly shown’ - at <span class='ar'>و</span> and <span class='ar'>ف</span>. What did the imāms actually say?","options":["<span class='ar'>واحذر</span> - beware of hiding it there; there are no degrees of <span class='ar'>إظهار</span>","That it is <span class='ar'>إظهار</span> plus a little extra <span class='ar'>غنة</span>","That it is a fourth ruling, sitting between <span class='ar'>إظهار</span> and <span class='ar'>إخفاء</span>"],"answerIndex":0,"why":"<span class='ar'>الإظهار</span> is one thing: the letter out of its <span class='ar'>مخرج</span>, cleanly. Ibn al-Jazarī’s word is a warning, not a grade."},{"type":"choice","q":"Why are <span class='ar'>و</span> and <span class='ar'>ف</span> singled out for that warning?","options":["<span class='ar'>و</span> comes from the same two lips as <span class='ar'>م</span>, and <span class='ar'>ف</span> from right beside them","Both letters carry a <span class='ar'>غنة</span> of their own","Both are <span class='ar'>حروف مد</span>"],"answerIndex":0,"why":"<span class='ar'>اتحاد</span> with the <span class='ar'>و</span>, <span class='ar'>قرب</span> with the <span class='ar'>ف</span> - whose <span class='ar'>مخرج</span> is the inside of the lower lip against the tips of the upper front teeth. Nearness is what tempts the lips to blur."},{"type":"choice","q":"<span class='ar'>الإخفاء</span> is defined as <span class='ar'>عارٍ عن التشديد</span>. What does that clause rule out here?","ayah":"تَرْمِيهِم بِحِجَارَةٍۢ مِّن سِجِّيلٍۢ","ref":"Sūrat al-Fīl 105:4","options":["Fusing the <span class='ar'>م</span> into the <span class='ar'>ب</span> as one doubled letter","Giving the <span class='ar'>م</span> any <span class='ar'>غنة</span> at all","Letting the lips meet"],"answerIndex":0,"why":"That single clause is the whole line between <span class='ar'>إخفاء</span> and <span class='ar'>إدغام</span>. In the muṣḥaf the <span class='ar'>ب</span> here carries no shadda, and the <span class='ar'>غنة</span> stays in the first letter."},{"type":"choice","q":"In <span class='ar'>الإخفاء الشفوي</span>, what do the lips do?","options":["Meet gently, without squeezing","Stay slightly apart, leaving a <span class='ar'>فرجة</span> - the modern practice","Press firmly shut"],"answerIndex":0,"why":"The imāms’ wording is <span class='ar'>فليسكّن الميم بتلطف من غير ثقل ولا تعصّف</span>, and what they forbade is <span class='ar'>كزّ الشفتين</span> - the squeeze, not the closing. The <span class='ar'>فرجة</span> is a twentieth-century innovation."},{"type":"choice","q":"The <span class='ar'>ميم</span> of <span class='ar'>أَنْعَمْتَ</span> is <span class='ar'>مظهرة</span>. How much <span class='ar'>غنة</span> does it get?","ayah":"صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ","ref":"Sūrat al-Fātiḥa 1:7 (part of the āya)","options":["Only the <span class='ar'>م</span>’s own natural <span class='ar'>غنة</span> - nothing added","A full, held <span class='ar'>غنة</span>","None whatsoever"],"answerIndex":0,"why":"This is why the definition says <span class='ar'>من غير زيادة في الغنة</span> and not <span class='ar'>من غير غنة</span>: no <span class='ar'>ميم</span> and no <span class='ar'>نون</span> is ever stripped of its <span class='ar'>غنة</span>. Stretching it here is the single most audible error in this chapter."},{"type":"choice","q":"How many <span class='ar'>ميم ساكنة</span> take <span class='ar'>إظهار شفوي</span> in this portion?","ayah":"سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ","ref":"Sūrat al-Baqara 2:6 (part of the āya)","options":["3","4","5","6"],"answerIndex":2,"why":"Five - <span class='ar'>عَلَيْهِمْ ءَأَنذَرْتَهُمْ</span>، <span class='ar'>ءَأَنذَرْتَهُمْ أَمْ</span>، <span class='ar'>أَمْ لَمْ</span>، <span class='ar'>لَمْ تُنذِرْهُمْ</span>، <span class='ar'>تُنذِرْهُمْ لَا</span>. Each <span class='ar'>ميم</span> wears the head of a <span class='ar'>خاء</span>, the muṣḥaf’s sukūn sign, which over a <span class='ar'>ميم</span> means: show it."},{"type":"choice","q":"How many places in this āya call for the <span class='ar'>غنة</span> held <span class='ar'>أكمل ما تكون</span>?","ayah":"مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ","ref":"Sūrat an-Nās 114:6","options":["1","2","3"],"answerIndex":1,"why":"The <span class='ar'>ن</span> of <span class='ar'>ٱلْجِنَّةِ</span> and the <span class='ar'>ن</span> of <span class='ar'>وَٱلنَّاسِ</span> - every shadda’d <span class='ar'>ن</span> or <span class='ar'>م</span>, wherever it falls: <span class='ar'>وأَظْهِرِ الغُنَّةَ مِنْ: نُونٍ، وَمِنْ … مِيمٍ؛ إِذَا مَا شُدِّدَا، وَأَخْفِيَنْ</span>."},{"type":"choice","q":"In <span class='ar'>الإظهار</span> the two letters leave their <span class='ar'>مخرج</span> with two separate releases - <span class='ar'>ارتفاعتان</span>. How many does <span class='ar'>الإخفاء الشفوي</span> use?","options":["One","Two","Three"],"answerIndex":0,"why":"One release, like <span class='ar'>الإدغام</span> - but unlike <span class='ar'>الإدغام</span>, the first letter’s sound is not turned into the second; it survives, like <span class='ar'>الإظهار</span>. That is what <span class='ar'>بصفة بين الإظهار والإدغام</span> means in the mouth."}],"_state":"verified","url":"https://www.youtube.com/watch?v=gyrtmirqn_M&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=24"},{"ep":25,"title_en":"Clear, Merged, Flipped","title_ar":"أحكام النون الساكنة والتنوين ـ الإظهار والإدغام والقلب","summary":"When a nūn sākina or a tanwīn meets the letter after it, does it stay clear, merge into it, or flip into a mīm? The fourth ruling - hiding it behind the letter - is taken up next.","teach":[{"label_en":"What tanwīn is","title_ar":"التَّنْوِين","tone":"brand","body":"A nūn sākina the Arabs attach to the end of a noun - spoken but never written, and only when you join on, never when you stop. Its written sign is a doubled ḥaraka: the first is the letter's own vowel, the second stands in for that unwritten nūn."},{"label_en":"Kept clear","title_ar":"الإِظْهَار","count":"6 letters","letters":"ء هـ ع ح غ خ","tone":"stop","body":"The six letters of the throat. The nūn is made at the tip of the tongue, far from all of them, so nothing blends - each letter is given its own clean exit, the nūn keeping its own <span class='ar'>غنة</span> without drawing it out."},{"label_en":"Merged in","title_ar":"الإِدْغَام","count":"6 letters","mnemonic":"يَرْمَلُونَ","letters":"ي ر م ل و ن","tone":"flow","body":"Into <span class='ar'>ل</span> and <span class='ar'>ر</span> the nūn goes <span class='ar'>بغير غنة</span> - nothing of it survives. Into <span class='ar'>ي ن م و</span> it goes <span class='ar'>بغنة</span>, and with <span class='ar'>ي</span> and <span class='ar'>و</span> the ringing left behind is what makes that <span class='ar'>إدغام</span> <span class='ar'>ناقص</span>."},{"label_en":"Flipped to mīm","title_ar":"القَلْب","count":"1 letter","letters":"ب","tone":"between","body":"Before <span class='ar'>ب</span> the nūn or tanwīn becomes a mīm, held with <span class='ar'>غنة</span> and hidden at the lips. The mīm is the bridge - it shares <span class='ar'>غنة</span> with <span class='ar'>ن</span> and shares the two lips with <span class='ar'>ب</span>."}],"questions":[{"type":"choice","q":"A nūn sākina is followed by this letter. Which ruling applies?","bigArabic":"غ","options":["إظهار","إدغام","قلب","إخفاء"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>غ</span> is one of the six throat letters. Distance is the reason: the nūn is formed at the tip of the tongue, nowhere near them, so there is nothing to blend into."},{"type":"multi","q":"Tap the six letters that take <span class='ar'>الإظهار</span>.","pool":["ء","ب","ح","خ","ع","غ","ل","م","ن","هـ","و","ي"],"answers":["ء","ح","خ","ع","غ","هـ"],"why":"<span class='ar'>ء ، هـ ، ع ، ح ، غ ، خ</span> - the throat. Of the 28 letters that can follow, six take <span class='ar'>إظهار</span>, six take <span class='ar'>إدغام</span>, one takes <span class='ar'>قلب</span>, and the remaining fifteen take <span class='ar'>إخفاء</span>."},{"type":"choice","q":"No letter is ever given two vowels at once. So what is the second fatḥa in a <span class='ar'>فتحتان</span>?","options":["The sign of the tanwīn","A lengthening of the first fatḥa","The vowel of the letter after it","A sign that you may stop here"],"answerIndex":0,"why":"The first ḥaraka belongs to the letter; the second only stands in for the nūn you say but never write. That is exactly why <span class='ar'>القلب</span> replaces the <em>second</em> ḥaraka with a small mīm and leaves the first alone."},{"type":"choice","q":"Two ḍammas sit stacked, one directly above the other, and the reciter carries straight on into the next word. What has the scribe told you?","options":["The next letter is a throat letter - إظهار","An إدغام or an إخفاء is coming","A قلب is coming","Nothing - it is only a style of writing"],"answerIndex":0,"why":"Stacked is <span class='ar'>متراكبتان</span>, and it marks <span class='ar'>إظهار</span>. When the two are offset and run one after the other - <span class='ar'>متتابعتان</span> - the scribe is warning you the tanwīn is about to be merged or hidden."},{"type":"choice","q":"A tanwīn meets <span class='ar'>ح</span> here. What is the ruling?","ayah":"ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ","ref":"Sūrat at-Tawba 9:110","options":["إظهار","إدغام بغنة","قلب","إخفاء"],"arabicOptions":true,"answerIndex":0,"why":"A tanwīn is a nūn sākina, so it takes the same rulings the nūn takes - and <span class='ar'>ح</span> is of the throat. In print you can see it: the two ḍammas are stacked, not offset."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span> from <span class='ar'>المقدمة الجزرية</span>:","verseStem":"فَعِنْدَ حَرْفِ الحَلْقِ: أَظْهِرْ، وَادَّغِمْ …","options":["فِي اللَّامِ وَالرَّا لَا بِغُنَّةٍ لَزِمْ","فِي الوَاوِ وَاليَا مَعَ غُنَّةٍ لَزِمْ","فِي النُّونِ وَالمِيمِ بِغُنَّةٍ لَزِمْ"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>ل</span> and <span class='ar'>ر</span> are the pair taken without <span class='ar'>غنة</span>. The other four of <span class='ar'>يرملون</span> keep it, and Ibn al-Jazarī gathers them in his next line as <span class='ar'>يُومِنُ</span>."},{"type":"choice","q":"The nūn sākina here is followed by <span class='ar'>ل</span>. How much of the nūn survives?","ayah":"بَأْسًۭا شَدِيدًۭا مِّن لَّدُنْهُ","ref":"Sūrat al-Kahf 18:2","options":["Nothing at all","Only its غنة","Only its tongue contact","All of it"],"answerIndex":0,"why":"Both halves of the nūn go - the tongue half and the nasal half alike - leaving a doubled <span class='ar'>ل</span>. Pinch your nose and the sound is unchanged, because nothing is coming out of it."},{"type":"choice","q":"This āya has two of them: a nūn sākina, then a tanwīn, each followed by a <span class='ar'>ي</span>. What survives of the nūn?","ayah":"فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ","ref":"Sūrat az-Zalzala 99:7","options":["Only its غنة","Nothing at all","Only its tongue contact","All of it"],"answerIndex":0,"why":"The tongue leaves the nūn's <span class='ar'>مخرج</span> for the yāʾ's, but the nasal half keeps sounding. Part of the first letter is still there - which is precisely why this <span class='ar'>إدغام</span> is called <span class='ar'>ناقص</span>, and why the mushaf leaves the following <span class='ar'>ي</span> without a shadda."},{"type":"choice","q":"The tanwīn here is followed by <span class='ar'>ن</span>. What is the ruling?","ayah":"إِلَىٰ شَىْءٍۢ نُّكُرٍ","ref":"Sūrat al-Qamar 54:6","options":["إدغام كامل بغنة","إدغام ناقص بغنة","إدغام بغير غنة","إظهار"],"arabicOptions":true,"answerIndex":0,"why":"Into <span class='ar'>ن</span> and <span class='ar'>م</span> the merge is complete - the first nūn leaves nothing of its own behind, and the <span class='ar'>غنة</span> you hear belongs to the doubled letter. The shadda on the <span class='ar'>ن</span> is the sign of a complete <span class='ar'>إدغام</span>."},{"type":"choice","q":"The first word carries a nūn sākina before a <span class='ar'>ب</span>. How is it read?","ayah":"أَنۢبِئْهُم بِأَسْمَآئِهِمْ","ref":"Sūrat al-Baqara 2:33","options":["As a mīm, held with غنة and hidden at the lips","As a clear nūn","As a doubled bāʾ","As a nūn with extra غنة"],"answerIndex":0,"why":"The mushaf tells you outright: a small mīm sits above the nūn in place of the sukūn. And once it is a mīm sākina before <span class='ar'>ب</span>, what <span class='ar'>القلب</span> actually ends in is <span class='ar'>إخفاء</span> of that mīm."},{"type":"choice","q":"A nūn sākina followed by <span class='ar'>و</span> or <span class='ar'>ي</span> <em>inside a single word</em> is not merged. How many such words occur in the Qur'an?","ayah":"وَنَخِيلٌۭ صِنْوَانٌۭ وَغَيْرُ صِنْوَانٍۢ","ref":"Sūrat ar-Raʿd 13:4","options":["2","3","4","6"],"answerIndex":2,"why":"<span class='ar'>صِنْوَان</span>، <span class='ar'>قِنْوَان</span>، <span class='ar'>الدُّنْيَا</span>، <span class='ar'>بُنْيَان</span> - and in all four the nūn is read clear. The exception holds only within one word; across two words the same meeting is <span class='ar'>إدغام</span> as normal."},{"type":"choice","q":"At the opening of Sūrat Yā-Sīn and of Sūrat al-Qalam, the nūn ending the opening letters is followed by a <span class='ar'>و</span>. How does Ḥafṣ by the ṭarīq of ash-Shāṭibiyya read it?","options":["إظهار - the nūn is kept clear","إدغام بغنة","إدغام بغير غنة","قلب"],"answerIndex":0,"why":"Two named places where this ṭarīq keeps the nūn clear instead of merging it into the <span class='ar'>و</span>. They are exceptions to be memorised, not a rule you can extend - every other nūn + <span class='ar'>و</span> across two words is <span class='ar'>إدغام بغنة</span>."}],"_state":"verified","url":"https://www.youtube.com/watch?v=LYOO-6f3s0U&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=25"},{"ep":26,"title_en":"The Hidden Nūn","title_ar":"أحكام النون الساكنة والتنوين ـ الإخفاء ومراتب الغنة","summary":"When a nūn sākina or tanwīn is neither merged nor kept clear, how is it hidden, and how long does each kind of ghunna last?","teach":[{"label_en":"Hidden","title_ar":"الإِخْفَاء","count":"15 letters","mnemonic":"صِفْ ذَا ثَنَا كَمْ جَادَ شَخْصٌ قَدْ سَمَا … دُمْ طَيِّبًا زِدْ فِي تُقًى ضَعْ ظَالِمَا","letters":"ص ذ ث ك ج ش ق س د ط ز ف ت ض ظ","tone":"brand","body":"Halfway between <span class='ar'>إظهار</span> and <span class='ar'>إدغام</span>: no <span class='ar'>شدة</span>, but the <span class='ar'>غنة</span> stays. The first letter of each word in the line gives the fifteen."},{"label_en":"Mouth goes first","title_ar":"تَهْيِئَةُ الفَم","tone":"flow","body":"While the <span class='ar'>غنة</span> sounds, the mouth is already shaped for the next letter, without pressing. Most of the sound comes from the nose with a faint sound from the mouth, except before <span class='ar'>ق</span> and <span class='ar'>ك</span>, where the back of the tongue seals the mouth and the nose carries it all."},{"label_en":"Heavy or light","title_ar":"التَّفْخِيمُ وَالتَّرْقِيق","letters":"ص ض ط ظ ق","tone":"stop","body":"The hidden nūn takes its weight from the letter after it: heavy before the five heavy letters among them, <span class='ar'>ص ض ط ظ ق</span>, as in <span class='ar'>مَنصُورًا</span>, light before the other ten, as in <span class='ar'>ٱلْإِنسَٰنَ</span>."},{"label_en":"Four lengths","title_ar":"مَرَاتِبُ الغُنَّة","tone":"between","body":"<span class='ar'>أكمل</span> in a doubled or merged ن or م, as in <span class='ar'>إِنَّ</span> and <span class='ar'>ثُمَّ</span>; <span class='ar'>كاملة</span> in a hidden one; <span class='ar'>ناقصة</span> in a sākin one said clearly; <span class='ar'>أنقص</span> in a voweled one. Recite faster and all four shrink together, keeping their proportions."}],"questions":[{"type":"multi","q":"A nūn sākina comes before each letter. Tap the ones that take <span class='ar'>الإخفاء</span>.","pool":["ص","ذ","ع","ك","ب","ج","ر","ط","خ","ف","ل","ز"],"answers":["ص","ذ","ك","ج","ط","ف","ز"],"why":"<span class='ar'>ع</span> and <span class='ar'>خ</span> are throat letters (<span class='ar'>إظهار</span>), <span class='ar'>ر</span> and <span class='ar'>ل</span> take <span class='ar'>إدغام</span>, and <span class='ar'>ب</span> takes <span class='ar'>قلب</span>. The other seven are all among the fifteen."},{"type":"choice","q":"Why is the nūn hidden before these fifteen letters instead of kept clear or merged?","options":["Its exit is neither close enough to them to merge nor far enough to stay clear","All fifteen are heavy letters","All fifteen are made in the throat","Hiding lets the reader lengthen the ghunna"],"answerIndex":0,"why":"Close exits lead to <span class='ar'>إدغام</span>, distant ones to <span class='ar'>إظهار</span>, and a middle distance to <span class='ar'>إخفاء</span>. The result is a sound between the two, and one movement where there would have been two."},{"type":"choice","q":"While the <span class='ar'>غنة</span> of the hidden nūn sounds here, where is the mouth?","ayah":"إِنَّهُۥ كَانَ مَنصُورًا","ref":"Sūrat al-Isrāʾ 17:33","options":["Already shaped for the ص, without pressing","Tongue tip pressed where a clear ن is made","Lips closed","In one neutral shape, moving to ص only afterwards"],"answerIndex":0,"why":"Giving every hidden nūn the same shape and only then moving to the next letter is a common error. It turns one movement into two, which defeats the point of hiding."},{"type":"choice","q":"Before which letter is the ghunna of a hidden nūn heavy?","options":["ق","ك","ت","س"],"arabicOptions":true,"answerIndex":0,"why":"The ghunna takes the weight of the letter that follows. Of the fifteen, only <span class='ar'>ص ض ط ظ ق</span> are heavy. <span class='ar'>ك</span> is also made at the back of the tongue, but it is light."},{"type":"choice","q":"The mouth is shaped for the ك while the nūn is hidden. Where does the sound come out?","ayah":"أَن كَانَ ذَا مَالٍ وَبَنِينَ","ref":"Sūrat al-Qalam 68:14","options":["Through the nose alone","Mostly the nose, with a faint sound from the mouth","Through the mouth alone","Equally through nose and mouth"],"answerIndex":0,"why":"With the other thirteen letters the mouth is left slightly open, so a faint sound escapes beside the ghunna. <span class='ar'>ك</span> and <span class='ar'>ق</span> are made by the back of the tongue sealing against the palate, so the nose carries it all."},{"type":"choice","q":"Hiding the nūn before ط, what does the tip of the tongue do during the ghunna?","ayah":"وَٱنطَلَقَ ٱلْمَلَأُ مِنْهُمْ","ref":"Sūrat Ṣād 38:6","options":["Comes very close to the ط's exit without touching it","Presses the ط's exit and holds there","Stays down behind the lower teeth","Taps the exit repeatedly"],"answerIndex":0,"why":"Touching the exit during the ghunna makes a clear nūn. Contact comes only with the <span class='ar'>ط</span> itself, and the same applies before <span class='ar'>د</span> and <span class='ar'>ت</span>."},{"type":"choice","q":"ط, د and ت get the same treatment in <span class='ar'>الإخفاء</span> because they share one exit. Complete the line from <span class='ar'>المقدمة الجزرية</span>:","verseStem":"وَالطَّاءُ وَالدَّالُ وَتَا: مِنْهُ وَمِنْ","options":["عُلْيَا الثَّنَايَا","أَقْصَى اللِّسَانِ","بَطْنِ الشَّفَهْ"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>مِنْهُ</span> means from the tip of the tongue, meeting <span class='ar'>عُلْيَا الثَّنَايَا</span>, the upper front teeth (at their roots)."},{"type":"choice","q":"Ibn al-Jazarī gives <span class='ar'>الإخفاء</span> its letters without listing them. Complete the line:","verseStem":"لِاخْفَا لَدَى:","options":["بَاقِي الحُرُوفِ","حَرْفِ الحَلْقِ","اللَّامِ وَالرَّا"],"arabicOptions":true,"answerIndex":0,"why":"He defines it by subtraction. Of the 28 letters that can follow, remove the six throat letters, the six of <span class='ar'>يَرْمَلُونَ</span> and <span class='ar'>ب</span>, and fifteen remain."},{"type":"choice","q":"How does Ḥafṣ read the tanwīn before the غ here?","ayah":"لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ","ref":"Sūrat Fuṣṣilat 41:8","options":["إظهار","إخفاء","إدغام","قلب"],"arabicOptions":true,"answerIndex":0,"why":"Hiding the nūn before <span class='ar'>غ</span> and <span class='ar'>خ</span> belongs to the reading of Abū Jaʿfar. In Ḥafṣ it is an error, so <span class='ar'>أَجْرٌ غَيْرُ</span> is read clearly, like <span class='ar'>مِنْ خَيْرٍ</span>."},{"type":"choice","q":"In the common Madinah-style mushaf, how is a hidden tanwīn marked?","options":["Staggered marks, and no shadda on the next letter","Stacked marks, one directly above the other","Staggered marks, and a shadda on the next letter","A small mīm in place of the second mark"],"answerIndex":0,"why":"Stacked marks mean <span class='ar'>إظهار</span>, staggered marks with a shadda after them mean full <span class='ar'>إدغام</span>, and the small mīm means <span class='ar'>قلب</span>. A hidden nūn sākina is likewise written bare, with no sukūn and no shadda on the next letter. The same marking is also used for the incomplete merge (<span class='ar'>إدغام ناقص</span>) before و and ي, so the letter that follows decides which one it is."},{"type":"choice","q":"Which of these has the longest ghunna?","ayah":"إِن كُنتُم مُّؤْمِنِينَ","ref":"Sūrat al-Baqara 2:93","options":["The ن of إِن","The ن inside كُنتُم","The doubled م at the start of مُّؤْمِنِينَ","All three are equal"],"answerIndex":2,"why":"Both nūns are hidden, so their ghunna is <span class='ar'>كاملة</span>. The mīm of <span class='ar'>كُنتُم</span> merges into the next mīm, which makes it <span class='ar'>أكمل</span>. The difference is small, but it is there."},{"type":"choice","q":"Which rank of ghunna does the نْ of <span class='ar'>أَنْعَمْتَ</span> get?","ayah":"صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ","ref":"Sūrat al-Fātiḥa 1:7","options":["أكمل","كاملة","ناقصة","أنقص"],"arabicOptions":true,"answerIndex":2,"why":"It is sākin and read clearly before the throat letter <span class='ar'>ع</span>, so it has a ghunna, but a short one that should not be held. The <span class='ar'>مْ</span> before <span class='ar'>ت</span> in the same word gets the same rank."}],"_state":"verified","url":"https://www.youtube.com/watch?v=1mydlMCh9eg&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=26"},{"ep":27,"title_en":"The Madd Family Tree","title_ar":"مدخل إلى باب المد والقصر","summary":"Which letters can stretch, what makes a madd grow past two ḥarakāt, and what is the unit used to measure it?","teach":[{"label_en":"Madd letters","title_ar":"حروف المد واللين","count":"3 letters","letters":"ا و ي","mnemonic":"نُوحِيهَا","tone":"flow","body":"<span class='ar'>ا</span> after a fatḥa, sākin <span class='ar'>و</span> after a ḍamma, sākin <span class='ar'>ي</span> after a kasra. They are called <span class='ar'>مد</span> because they can be stretched, and <span class='ar'>لين</span> because they leave the mouth without effort."},{"label_en":"Līn letters","title_ar":"حرفا اللين","count":"2 letters","letters":"و ي","tone":"between","body":"A sākin <span class='ar'>و</span> or <span class='ar'>ي</span> after a fatḥa, as in <span class='ar'>خَوْف</span> and <span class='ar'>بَيْت</span>. After the opening fatḥa, the teacher points out, the sound matches the madd letter. Only the ḥaraka before it is different."},{"label_en":"Two causes","title_ar":"سببا المد: الهمز والسكون","tone":"stop","body":"Any madd beyond the natural two, and any madd on a līn letter, needs a cause: a hamza or a sukūn. Hamza line: <span class='ar'>المتصل ← المنفصل ← الصلة الكبرى</span>. Sukūn line: <span class='ar'>اللازم ← العارض للسكون ← اللين</span>. Each madd follows the one before it because the two sound alike."},{"label_en":"The unit","title_ar":"الحَرَكَة","tone":"brand","body":"One ḥaraka is the time it takes to say one voweled letter. <span class='ar'>قَ</span>, <span class='ar'>قُ</span> and <span class='ar'>قِ</span> take the same time. The unit comes from the recitation itself, so it gets shorter as you read faster."}],"questions":[{"type":"multi","q":"Tap every letter that can be a <span class='ar'>حرف لين</span>.","pool":["ا","و","ي","ه","ن","ع","م","ء"],"answers":["و","ي"],"why":"<span class='ar'>ا</span> cannot be one. It is always sākin, and the letter before it always has a fatḥa, which is its matching ḥaraka. So it is always a madd letter."},{"type":"choice","q":"What is the <span class='ar'>و</span> in <span class='ar'>خَوْفٍۭ</span>?","ayah":"مِّنْ خَوْفٍۭ","ref":"Sūrat Quraysh 106:4","options":["حرف لين","حرف مد","ليس حرف مد ولا لين"],"arabicOptions":true,"answerIndex":0,"why":"It is a sākin <span class='ar'>و</span> after a fatḥa. Put a ḍamma before it and it becomes the madd letter of <span class='ar'>تَعْلَمُونَ</span>. The teacher points out that after the opening fatḥa, the two sound the same."},{"type":"choice","q":"A man recited this to Ibn Masʿūd without stretching it. Ibn Masʿūd objected and recited it again, stretching <span class='ar'>لِلْفُقَرَآءِ</span>. Which madd was he insisting on?","ayah":"إِنَّمَا ٱلصَّدَقَٰتُ لِلْفُقَرَآءِ وَٱلْمَسَٰكِينِ","ref":"Sūrat at-Tawba 9:60","options":["المتصل","المنفصل","اللازم","الطبيعي"],"arabicOptions":true,"answerIndex":0,"why":"The alif and the hamza are in the same word. Ibn Masʿūd said this was not how the Prophet ﷺ taught him to read it, so this report is the textual proof for <span class='ar'>المتصل</span>."},{"type":"choice","q":"Which two madds is no qāriʾ reported to have shortened to two ḥarakāt?","options":["المتصل واللازم","المنفصل واللازم","المتصل والمنفصل","العارض للسكون واللين"],"arabicOptions":true,"answerIndex":0,"why":"No qāriʾ is reported to have shortened either of them. That is why the lesson makes them the heads of the tree: <span class='ar'>المتصل</span> for hamza, <span class='ar'>اللازم</span> for sukūn. <span class='ar'>المنفصل</span>, <span class='ar'>العارض</span> and <span class='ar'>اللين</span> can each be read with two in some reading. (Where the lāzim sukūn itself changes to a ḥaraka in waṣl, as in <span class='ar'>الٓمٓ ۝ ٱللَّهُ</span>, shortening is allowed. That is a separate topic.)"},{"type":"choice","q":"Complete Ibn al-Jazarī's definition of <span class='ar'>اللازم</span>:","verseStem":"فَلَازِمٌ: إِنْ جَاءَ بَعْدَ حَرْفِ مَدْ … سَاكِنُ","options":["«حَالَيْنِ، وَبِالطُّولِ يُمَدْ»","«وَقْفاً، وَبِالطُّولِ يُمَدْ»","«وَصْلاً، وَبِالقَصْرِ يُمَدْ»"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>حالين</span> means both states, waṣl and waqf. The sukūn is original, as in <span class='ar'>ٱلضَّآلِّينَ</span>. When the sukūn appears only on stopping, the madd is <span class='ar'>العارض للسكون</span> instead."},{"type":"choice","q":"Complete the line.","verseStem":"وَجَائِزٌ: إِذَا أَتَى","options":["«مُنْفَصِلَا»","«مُتَّصِلَا»","«سَاكِنَ حَالَيْنِ»"],"arabicOptions":true,"answerIndex":0,"why":"In <span class='ar'>قُوٓا۟ أَنفُسَكُمْ</span> the hamza is in the next word, so some qurrāʾ shorten it. In Ḥafṣ by the Shāṭibiyya route, <span class='ar'>المنفصل</span> is read with 4 or 5. The second half of the verse, <span class='ar'>أَوْ عَرَضَ السُّكُونُ وَقْفاً مُسْجَلَا</span>, puts <span class='ar'>العارض للسكون</span> under <span class='ar'>جائز</span> as well."},{"type":"choice","q":"How long is the <span class='ar'>صلة</span> on <span class='ar'>مَالَهُۥٓ</span>?","ayah":"يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ","ref":"Sūrat al-Humaza 104:3","options":["As long as المنفصل","Two ḥarakāt, like الطبيعي","Six ḥarakāt, like اللازم"],"answerIndex":0,"why":"<span class='ar'>مَالَهُۥٓ أَخْلَدَهُۥ</span> sounds just like <span class='ar'>قُوٓا۟ أَنفُسَكُمْ</span>: a madd sound, then a hamza in the next word. That is why <span class='ar'>الصلة الكبرى</span> branches from <span class='ar'>المنفصل</span>."},{"type":"choice","q":"Stop on <span class='ar'>ٱلْبَيْتِ</span>. The madd on its <span class='ar'>ي</span> is directly modelled on which madd?","ayah":"فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ","ref":"Sūrat Quraysh 106:3","options":["العارض للسكون","المتصل","الطبيعي","المنفصل"],"arabicOptions":true,"answerIndex":0,"why":"Both have a sukūn that appears only when you stop. The difference is that <span class='ar'>ٱلْبَيْتِ</span> has a līn letter where the other has a madd letter. <span class='ar'>العارض</span> is in turn modelled on <span class='ar'>اللازم</span>."},{"type":"choice","q":"A reader stops on <span class='ar'>نَسْتَعِينُ</span> and gives the madd four ḥarakāt. What is the reasoning?","ayah":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","ref":"Sūrat al-Fātiḥa 1:5","options":["The temporary sukūn counts, but for less than an original one","The sukūn is treated exactly like the sukūn of اللازم","The sukūn is ignored because it disappears in waṣl"],"answerIndex":0,"why":"Six treats it like <span class='ar'>اللازم</span>. Two ignores a sukūn that disappears in waṣl. Four sits between them. Ḥafṣ may use any of the three."},{"type":"choice","q":"How does this lesson define one <span class='ar'>حركة</span>?","options":["The time it takes to say one voweled letter","One finger folded or unfolded","The length of a spoken alif","One second"],"answerIndex":0,"why":"Fatḥa, ḍamma and kasra take the same time, which is why the unit is called a ḥaraka and not a fatḥa. A spoken alif is two ḥarakāt. The lesson rejects finger counting as recent and imprecise."},{"type":"choice","q":"Read this slowly in <span class='ar'>التحقيق</span>, then quickly in <span class='ar'>الحدر</span>. What happens to one ḥaraka?","ayah":"كَتَبَ ٱللَّهُ لَأَغْلِبَنَّ أَنَا۠ وَرُسُلِىٓ","ref":"Sūrat al-Mujādila 58:21","options":["It gets shorter in الحدر","It stays exactly the same","It gets longer in الحدر"],"answerIndex":0,"why":"So four ḥarakāt in <span class='ar'>التحقيق</span> take longer than four in <span class='ar'>الحدر</span>. Think of floor tiles: four tiles can be 80 cm or 120 cm, depending on the size of the tile."},{"type":"choice","q":"Why does this lesson reject counting madd on the fingers?","options":["It changes from person to person, with age and mood, and ignores reading speed","It makes every madd too short","The early scholars forbade it"],"answerIndex":0,"why":"Finger counting is also a recent practice. The ḥaraka comes from the recitation itself, so it adjusts to each reciter and each reading speed."}],"_state":"verified","url":"https://www.youtube.com/watch?v=3tL5YYdjnTw&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=27"},{"ep":28,"title_en":"Counting the Madd","title_ar":"مقادير المدود","summary":"When an old book says a madd is \"three ألفات\", how many counts does it mean, and how long is one count?","teach":[{"label_en":"An old ألف = one count","title_ar":"الأَلِف عند المتقدمين","tone":"brand","body":"In older books a <span class='ar'>ألف</span> is one <span class='ar'>حركة</span>, and the count starts <strong>after</strong> the natural two. So \"three <span class='ar'>ألفات</span>\" means 2 + 3 = 5 <span class='ar'>حركات</span>."},{"label_en":"Five lengths","title_ar":"مقادير المدود الخمسة","count":"5 lengths","mnemonic":"2 · 3 · 4 · 5 · 6","tone":"flow","body":"<span class='ar'>القصر</span> 2, <span class='ar'>فويق القصر</span> 3, <span class='ar'>التوسط</span> 4, <span class='ar'>فويق التوسط</span> 5, <span class='ar'>الطول</span> 6. The diminutive <span class='ar'>فُوَيْق</span> means \"just above\"."},{"label_en":"Tempo sets the clock","title_ar":"التحقيق والتدوير والحدر","tone":"between","body":"A <span class='ar'>حركة</span> has no fixed clock time. It gets shorter as the reading speeds up, so 4 <span class='ar'>حركات</span> in <span class='ar'>التحقيق</span> last longer than 4 in <span class='ar'>التدوير</span>, and those last longer than 4 in <span class='ar'>الحدر</span>."},{"label_en":"Terms drift","title_ar":"الروم والإشمام","tone":"stop","body":"Read a term the way its author used it. For the Basrans, <span class='ar'>الروم</span> is part of the vowel and <span class='ar'>الإشمام</span> is rounding the lips. The Kufans used the two words the other way round."}],"questions":[{"type":"choice","q":"In the older books on qirāʾāt, what does one <span class='ar'>ألف</span> of madd mean?","options":["One حركة","One pronounced alif, i.e. two حركات","A full madd of six حركات"],"answerIndex":0,"why":"A pronounced alif, as in <span class='ar'>قَالَ</span>, takes two <span class='ar'>حركات</span>. Mix the two meanings up and each old <span class='ar'>ألف</span> gets counted as two <span class='ar'>حركات</span> instead of one."},{"type":"choice","q":"When an older author counts <span class='ar'>ألفات</span>, where does his count begin?","options":["After the natural two حركات","From zero, including the natural length","After four حركات"],"answerIndex":0,"why":"They did not count the natural two as madd at all. That length was called <span class='ar'>القصر</span>, and only what is added on top of it was counted."},{"type":"choice","q":"An older book says a reciter lengthened a madd by <strong>three</strong> <span class='ar'>ألفات</span>. Read as the older author meant it, how many <span class='ar'>حركات</span> is that in total?","options":["3","5","6","8"],"answerIndex":1,"why":"Three added <span class='ar'>حركات</span> plus the natural two makes 5."},{"type":"choice","q":"The <span class='ar'>ا</span> after the <span class='ar'>ق</span> here is a plain <span class='ar'>مد طبيعي</span>. How many <span class='ar'>حركات</span> does this one pronounced alif take?","ayah":"قَالُوا۟ سُبْحَٰنَكَ","ref":"Sūrat al-Baqarah 2:32","options":["1","2","4","6"],"answerIndex":1,"why":"Two. A reader who takes an old <span class='ar'>ألف</span> to mean a pronounced alif like this one counts each <span class='ar'>ألف</span> as two <span class='ar'>حركات</span> instead of one."},{"type":"choice","q":"A modern reader sees \"five <span class='ar'>ألفات</span>\" in an old book, takes each one as a pronounced alif, and arrives at 10. Read correctly, how many <span class='ar'>حركات</span> did the book mean?","options":["5","7","10","12"],"answerIndex":1,"why":"Five added <span class='ar'>حركات</span> plus the natural two makes 7. No one recites that length today, since the modern scale stops at <span class='ar'>الطول</span>, which is 6. As for 10, nobody ever meant it."},{"type":"choice","q":"Why is a two-count length called <span class='ar'>القصر</span>?","options":["The letter is held back from any increase","It is used only when stopping","It applies only to short vowels"],"answerIndex":0,"why":"In the language, <span class='ar'>القصر</span> means <span class='ar'>الحبس</span>, holding something back. The madd letter is kept from growing beyond its natural length."},{"type":"choice","q":"An old book says someone read <span class='ar'>بالتمكين من غير مد</span>. What does that mean?","options":["Natural length only, with nothing added","The madd letter dropped altogether","The full six حركات"],"answerIndex":0,"why":"<span class='ar'>التمكين</span> gives the madd letter its natural length and no less. The contrasting phrase <span class='ar'>بالتمكين والمد</span> means extra length is added on top."},{"type":"choice","q":"A madd held for exactly <strong>5</strong> <span class='ar'>حركات</span>: which <span class='ar'>مقدار</span> is it?","options":["القصر","فويق القصر","التوسط","فويق التوسط"],"arabicOptions":true,"answerIndex":3,"why":"<span class='ar'>التوسط</span> is 4, and one count above it is <span class='ar'>فويق التوسط</span>. Its partner, <span class='ar'>فويق القصر</span>, sits one count above 2, which gives 3."},{"type":"choice","q":"Why did the scholars say <span class='ar'>فُوَيْق</span> rather than <span class='ar'>فَوْق</span>?","options":["The diminutive means only slightly above the level before it","It means double the level before it","It marks a length below the level named"],"answerIndex":0,"why":"<span class='ar'>فُوَيْق</span> is the diminutive form of <span class='ar'>فَوْق</span>. <span class='ar'>فويق القصر</span> goes only just past two counts. It does not reach <span class='ar'>التوسط</span>."},{"type":"choice","q":"Four <span class='ar'>حركات</span> are recited at each of these speeds. Which lasts longest in real time?","options":["التحقيق","التدوير","الحدر"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>التحقيق</span> is the slowest tempo, so its <span class='ar'>حركة</span> is the longest. What stays the same is the ratio: at any speed, four counts are twice as long as two."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span> from <span class='ar'>المقدمة الجزرية</span>:","verseStem":"وَحَاذِرِ الوَقْفَ بِكُلِّ الحَرَكَهْ …","options":["إِلَّا إِذَا رُمْتَ فَبَعْضُ الحَرَكَهْ","إِلَّا إِذَا أَشْمَمْتَ فَبَعْضُ الحَرَكَهْ","إِلَّا إِذَا رُمْتَ فَضَمُّ الشَّفَهْ"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>رُمْتَ</span> comes from <span class='ar'>الروم</span>, and Ibn al-Jazarī uses it in the Basran sense: sounding part of the vowel when you stop."},{"type":"choice","q":"In Kufan usage, what did the word <span class='ar'>الروم</span> refer to?","options":["Rounding the lips with no sound","Sounding part of the vowel","Stopping with the full vowel"],"answerIndex":0,"why":"The Basrans call that <span class='ar'>الإشمام</span>, and so does Ibn al-Jazarī in the line after the one on <span class='ar'>الروم</span>: <span class='ar'>وَأَشِمْ إِشَارَةً بِالضَّمِّ</span>. The words are the same but the meanings are swapped, so always check whose terminology a book follows."}],"_state":"verified","url":"https://www.youtube.com/watch?v=bfbB-YxuDpw&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=28"},{"ep":29,"title_en":"The Two-Count Family","title_ar":"المد الطبيعي وما يلحق به: البدل والعوض والصلة","summary":"Which madds are held two counts like the natural madd, and when does the صلة grow longer?","teach":[{"label_en":"Two counts, no cause","title_ar":"المد الطبيعي","count":"2 حركات","tone":"brand","body":"A madd letter after its matching vowel, with no hamza or sukūn causing it. Hold it two counts; cut it shorter and the letter is gone, leaving a bare vowel."},{"label_en":"Hamza, then madd","title_ar":"مد البدل","count":"2 حركات","tone":"flow","body":"A hamza followed by a madd letter. Many such words, like <span class='ar'>ءَامَنُوا۟</span>, began as two hamzas with the second sākin, and Arabic turned that second one into a madd letter. Others, like <span class='ar'>جَآءُو</span> and <span class='ar'>يُرَآءُونَ</span>, have a different origin but are counted the same way. Ḥafṣ holds all of them two counts."},{"label_en":"Tanwīn becomes alif","title_ar":"مد العوض","count":"2 حركات","tone":"stop","body":"Stopping on <span class='ar'>تنوين النصب</span>, drop the tanwīn and put an alif of two counts in its place: <span class='ar'>رَحِيمًا</span> → <span class='ar'>رَحِيمَا</span>. Never on <span class='ar'>ة</span>: <span class='ar'>جَنَّةً</span> is stopped on as <span class='ar'>جَنَّهْ</span>."},{"label_en":"The pronoun's link","title_ar":"مد الصلة","tone":"between","body":"<span class='ar'>هاء الضمير</span> for one absent male (“him”, “his”), between two voweled letters, gets a <span class='ar'>و</span> if it has ḍamma and a <span class='ar'>ي</span> if kasra, in waṣl only. Before a <span class='ar'>همزة قطع</span> it is <span class='ar'>الصلة الكبرى</span>, as long as <span class='ar'>المد المنفصل</span>; otherwise <span class='ar'>الصلة الصغرى</span>, two counts. Ḥafṣ has two exceptions: <span class='ar'>فِيهِۦ مُهَانًا</span> and <span class='ar'>يَرْضَهُ</span>."}],"questions":[{"type":"choice","q":"The teacher's spoken example: say <span class='ar'>يَٰمُوسَىٰ</span> but cut the long ā after the <span class='ar'>ي</span> below two counts. What is left of it?","bigArabic":"يَٰمُوسَىٰ","options":["Only a fatḥa: the alif has disappeared","A shorter alif, still an alif","A hamza"],"answerIndex":0,"why":"That is what <span class='ar'>لا تقوم ذات الحرف إلا به</span> means: without its two counts the madd letter does not exist at all. Nothing causes this madd; it is just how the word is spoken."},{"type":"choice","q":"You stop at the end of this quotation. What happens to the tanwīn on the last word?","ayah":"وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا","ref":"Sūrat an-Nisāʾ 4:17","options":["It becomes an alif held 2 counts","It is dropped and the word ends on sukūn","The nūn sound is kept","It becomes an alif held 4 counts"],"answerIndex":0,"why":"That alif is <span class='ar'>مد العوض</span>. It happens only on a stop: if you joined <span class='ar'>حَكِيمًا</span> to the next āya, its tanwīn would be pronounced. <span class='ar'>تنوين الرفع</span> and <span class='ar'>تنوين الجر</span> just drop to sukūn."},{"type":"choice","q":"You stop on the first word. How is it read?","ayah":"وَشَجَرَةً تَخْرُجُ مِن طُورِ سَيْنَآءَ","ref":"Sūrat al-Muʾminūn 23:20","options":["وَشَجَرَهْ","وَشَجَرَتَا","وَشَجَرَتْ"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>هاء التأنيث</span> is the exception to <span class='ar'>مد العوض</span>: even with <span class='ar'>تنوين النصب</span>, the <span class='ar'>ة</span> becomes a sākin <span class='ar'>ه</span> on the stop and no alif is added."},{"type":"choice","q":"Stop at the end of this quotation. The alif you add after the hamza of <span class='ar'>وَنِدَآءً</span> looks like <span class='ar'>مد البدل</span>. What is it really?","ayah":"إِلَّا دُعَآءً وَنِدَآءً","ref":"Sūrat al-Baqarah 2:171","options":["مد العوض","مد البدل","المد المتصل","مد الصلة"],"arabicOptions":true,"answerIndex":0,"why":"The alif stands in for the tanwīn, so it is <span class='ar'>مد العوض</span> even though a hamza comes before it. In waṣl there is no alif at all: the tanwīn is pronounced."},{"type":"choice","q":"Which madd is the long ā right after the hamza?","bigArabic":"ءَامَنُوا۟","options":["مد البدل","المد المتصل","مد العوض","مد الصلة"],"arabicOptions":true,"answerIndex":0,"why":"The hamza comes <strong>before</strong> the madd letter. In <span class='ar'>المد المتصل</span> the hamza comes after it, in the same word."},{"type":"choice","q":"Arabic replaces a sākin hamza that follows another hamza. In <span class='ar'>أُؤْتُوا</span>, which letter takes its place?","options":["و","ا","ي"],"arabicOptions":true,"answerIndex":0,"why":"The new letter matches the first hamza's vowel. Ḍamma gives <span class='ar'>أُوتُوا۟</span>, fatḥa gives <span class='ar'>ءَامَنُوا۟</span>, and kasra gives <span class='ar'>إِيمَٰنًا</span>. All three are <span class='ar'>مد البدل</span>."},{"type":"choice","q":"This āya has two <span class='ar'>هاء الضمير</span>. Which one takes a صلة?","ayah":"مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ","ref":"Sūrat al-Masad 111:2","options":["<span class='ar'>مَالُهُۥ</span> only","<span class='ar'>عَنْهُ</span> only","both","neither"],"answerIndex":0,"why":"In <span class='ar'>عَنْهُ</span> the <span class='ar'>ن</span> before the ha is sākin, so there is no صلة. In <span class='ar'>مَالُهُۥ</span> the ha sits between the voweled <span class='ar'>ل</span> and <span class='ar'>و</span>, so it gets <span class='ar'>الصلة الصغرى</span>: two counts."},{"type":"choice","q":"How long is the صلة on <span class='ar'>مَالَهُۥٓ</span>?","ayah":"يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ","ref":"Sūrat al-Humazah 104:3","options":["2 حركات","As long as <span class='ar'>المد المنفصل</span>","6 حركات","There is no صلة"],"answerIndex":1,"why":"A <span class='ar'>همزة قطع</span> follows, so this is <span class='ar'>الصلة الكبرى</span>. The mushaf shows it with the madd sign over the small <span class='ar'>و</span>. The last ha, in <span class='ar'>أَخْلَدَهُۥ</span>, gets sukūn when you stop there."},{"type":"choice","q":"The <span class='ar'>ي</span> before the ha of <span class='ar'>فِيهِۦ</span> is sākin, which normally rules out صلة. How does Ḥafṣ read it here?","ayah":"وَيَخْلُدْ فِيهِۦ مُهَانًا","ref":"Sūrat al-Furqān 25:69","options":["With صلة, two counts","Short kasra, no صلة","With صلة, as long as المنفصل"],"answerIndex":0,"why":"This is one of Ḥafṣ's two exceptions. It is <span class='ar'>الصلة الصغرى</span> because <span class='ar'>م</span> follows, not a hamza."},{"type":"choice","q":"The ha of <span class='ar'>يَرْضَهُ</span> is <span class='ar'>هاء الضمير</span>, has ḍamma, and sits between two voweled letters. How does Ḥafṣ read it?","ayah":"وَإِن تَشْكُرُوا۟ يَرْضَهُ لَكُمْ","ref":"Sūrat az-Zumar 39:7","options":["Short ḍamma, no صلة","With صلة, two counts","With a sākin ha"],"answerIndex":0,"why":"This is Ḥafṣ's other exception, the reverse of <span class='ar'>فِيهِۦ مُهَانًا</span>: every condition is met, yet there is no صلة."},{"type":"choice","q":"Why does the ha of <span class='ar'>ٱسْمُهُ</span> have no صلة?","ayah":"ٱسْمُهُ ٱلْمَسِيحُ","ref":"Sūrat Āl ʿImrān 3:45","options":["A sākin letter follows it","A sākin letter comes before it","It is not هاء الضمير","It refers to a feminine noun"],"answerIndex":0,"why":"The hamzat al-waṣl drops in waṣl, so the ha runs straight into the sākin <span class='ar'>ل</span>. The ha must sit between two <strong>voweled</strong> letters."},{"type":"choice","q":"The ha of <span class='ar'>هَٰذِهِ</span> is not <span class='ar'>هاء الضمير</span>, but it is treated like one. How is it read here?","ayah":"إِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ","ref":"Sūrat al-Anbiyāʾ 21:92","options":["<span class='ar'>الصلة الكبرى</span>, as long as <span class='ar'>المنفصل</span>","<span class='ar'>الصلة الصغرى</span>, two counts","No صلة"],"answerIndex":0,"why":"A <span class='ar'>همزة قطع</span> follows, so the same rule applies as for a pronoun. <span class='ar'>هَٰذِهِۦ بِضَٰعَتُنَا</span> gets <span class='ar'>الصلة الصغرى</span>, and <span class='ar'>هَٰذِهِ ٱلشَّجَرَةَ</span> gets none because a sākin follows."}],"_state":"verified","url":"https://www.youtube.com/watch?v=d_W1cbLbwM0&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=29"},{"ep":30,"title_en":"Split, Joined, Locked","title_ar":"المد المنفصل والمتصل واللازم","summary":"Where does the hamza or sukūn sit after the madd letter, and how far does that let you stretch it?","teach":[{"label_en":"Split","title_ar":"المد الجائز المنفصل","count":"4 or 5 counts","tone":"between","body":"The madd letter <strong>ends</strong> one word and a <span class='ar'>همزة قطع</span> <strong>starts</strong> the next: <span class='ar'>بِمَآ أُنزِلَ</span>. It is <span class='ar'>جائز</span> because reciters differ: some stretch it, some shorten it. In Ḥafṣ it takes 4 or 5 counts."},{"label_en":"Joined","title_ar":"المد الواجب المتصل","count":"4 or 5 counts","tone":"brand","body":"The madd letter is followed by a hamza <strong>in the same word</strong>: <span class='ar'>جَآءَ</span>. It is <span class='ar'>واجب</span> because no reciter shortens it to 2. In Ḥafṣ, keep it matched with the <span class='ar'>منفصل</span>: 4 with 4, or 5 with 5."},{"label_en":"Locked","title_ar":"المد اللازم","count":"6 counts","tone":"stop","body":"The madd letter is followed by a <span class='ar'>سكون أصلي</span>, one that is there whether you continue or stop. Every type is stretched 6 counts."},{"label_en":"Name it in full","title_ar":"كلمي وحرفي ـ مخفف ومثقل","mnemonic":"لازم + كلمي/حرفي + مخفف/مثقل","tone":"flow","body":"<span class='ar'>كلمي</span> if it is in a word, <span class='ar'>حرفي</span> if it is in the name of an opening letter. <span class='ar'>مخفف</span> if the sukūn is plain, <span class='ar'>مثقل</span> if it merges into a shadda. Just saying <span class='ar'>لازم</span> is only part of the answer."}],"questions":[{"type":"choice","q":"What kind of madd is on <span class='ar'>بِمَآ</span>?","ayah":"وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ","ref":"Sūrat al-Baqara 2:4","options":["منفصل","متصل","لازم"],"arabicOptions":true,"answerIndex":0,"why":"The alif ends <span class='ar'>بِمَآ</span> and the <span class='ar'>همزة قطع</span> opens <span class='ar'>أُنزِلَ</span>. The madd and its hamza sit in two words."},{"type":"choice","q":"What kind of madd is on <span class='ar'>جَآءَ</span>?","ayah":"إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ","ref":"Sūrat an-Naṣr 110:1","options":["منفصل","متصل","لازم"],"arabicOptions":true,"answerIndex":1,"why":"The hamza comes straight after the alif, inside the same word. That is why it is called <span class='ar'>واجب</span>: every reciter stretches it past 2 counts, and they differ only on how far."},{"type":"choice","q":"<span class='ar'>يَٰٓأَيُّهَا</span> is written as one word. What kind of madd is on its <span class='ar'>يا</span>?","ayah":"يَٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ","ref":"Sūrat al-Baqara 2:21","options":["منفصل","متصل","طبيعي"],"arabicOptions":true,"answerIndex":0,"why":"It is really two words, the <span class='ar'>يا</span> of calling plus <span class='ar'>أَيُّهَا</span>. The mushaf drops the alif of <span class='ar'>يا</span> and joins it on, but the madd is still counted as <span class='ar'>منفصل</span>."},{"type":"choice","q":"<span class='ar'>هَٰٓؤُلَآءِ</span> has two madds. How is each one classified?","ayah":"هَٰٓؤُلَآءِ قَوْمُنَا","ref":"Sūrat al-Kahf 18:15","options":["1st منفصل, 2nd متصل","both متصل","both منفصل","1st متصل, 2nd منفصل"],"answerIndex":0,"why":"It is <span class='ar'>ها</span> (the particle that calls attention) plus <span class='ar'>أُو۟لَآءِ</span>, a word that also stands alone. The first madd crosses that hidden word boundary. The second has its hamza inside <span class='ar'>أُو۟لَآءِ</span>."},{"type":"choice","q":"What kind of madd is on <span class='ar'>هَآؤُمُ</span>?","ayah":"هَآؤُمُ ٱقْرَءُوا۟ كِتَٰبِيَهْ","ref":"Sūrat al-Ḥāqqa 69:19","options":["منفصل","متصل"],"arabicOptions":true,"answerIndex":1,"why":"This <span class='ar'>ها</span> is not the attention particle. <span class='ar'>هَآؤُمُ</span> is a single word meaning “here, take!”, and no separate word <span class='ar'>ؤُمُ</span> exists. So the madd letter and hamza are in one word."},{"type":"choice","q":"Complete the <span class='ar'>بيت</span> from <span class='ar'>المقدمة الجزرية</span>.","verseStem":"كَذَا مِنَ «الْ» وَ «هَا» وَ «يَا»؛","options":["لَا تَفْصِلِ","فَافْصِلِ","لَا تَصِلِ"],"arabicOptions":true,"answerIndex":0,"why":"The first half of the line says <span class='ar'>وَزَنُوهُمُ</span> and <span class='ar'>كَالُوهُمْ</span> are written joined, not split. So too <span class='ar'>ال</span>, <span class='ar'>ها</span> and <span class='ar'>يا</span>: each is written joined to the word after it. That is why <span class='ar'>يَٰٓأَيُّهَا</span> and <span class='ar'>هَٰٓؤُلَآءِ</span> look like single words."},{"type":"choice","q":"Which definition of <span class='ar'>المد المنفصل</span> lets in every real case and nothing else?","options":["A madd letter at the end of one word, and a همزة قطع at the start of the next","A madd letter in one word, and a hamza in another word","A madd letter at the end of one word, and any hamza in the next word"],"answerIndex":0,"why":"Each phrase rules something out. “End” rules out a madd letter in the middle of a word. “قطع” rules out <span class='ar'>همزة الوصل</span>, which drops when you join words. “Start of the next” rules out a hamza in the middle or at the end of the next word."},{"type":"choice","q":"This word has a madd letter and a hamza in it. Why is it <strong>not</strong> <span class='ar'>متصل</span>?","bigArabic":"ءَامَنَ","options":["The hamza comes before the madd letter, not after it","The hamza here is a همزة وصل","A madd letter and hamza can never be in the same word"],"answerIndex":0,"why":"<span class='ar'>المتصل</span> means a madd letter <strong>followed by</strong> a hamza in the same word. Saying only “in one word” would wrongly include words like this one."},{"type":"choice","q":"Reading Ḥafṣ, which pairing of lengths is <strong>not</strong> allowed?","options":["منفصل 4, متصل 4","منفصل 5, متصل 5","منفصل 5, متصل 4"],"answerIndex":2,"why":"In Ḥafṣ the <span class='ar'>منفصل</span> and <span class='ar'>متصل</span> are kept equal: 4 with 4 (<span class='ar'>الشاطبية</span>) or 5 with 5 (<span class='ar'>التيسير</span>). Mixing 4 and 5 is not done, in either direction."},{"type":"choice","q":"Give the full name of the madd on <span class='ar'>ٱلضَّآلِّينَ</span>.","ayah":"وَلَا ٱلضَّآلِّينَ","ref":"Sūrat al-Fātiḥa 1:7","options":["لازم كلمي مثقل","لازم كلمي مخفف","لازم حرفي مثقل","لازم حرفي مخفف"],"arabicOptions":true,"answerIndex":0,"why":"It is inside a word, so <span class='ar'>كلمي</span>. The letter after the alif is a sākin <span class='ar'>لام</span>, the first half of the shadda, merged into the second <span class='ar'>لام</span>, so <span class='ar'>مثقل</span>. Stretch it 6 counts."},{"type":"choice","q":"In <span class='ar'>الٓمٓ</span>, what is the full name of the madd on the letter-name <span class='ar'>لام</span>?","ayah":"الٓمٓ","ref":"Sūrat al-Baqara 2:1","options":["لازم حرفي مثقل","لازم حرفي مخفف","لازم كلمي مثقل","لازم كلمي مخفف"],"arabicOptions":true,"answerIndex":0,"why":"<span class='ar'>لام</span> ends in a sākin <span class='ar'>م</span> that merges into the <span class='ar'>م</span> of <span class='ar'>ميم</span>, so it is <span class='ar'>مثقل</span>. The final <span class='ar'>ميم</span> merges into nothing, so it is <span class='ar'>حرفي مخفف</span>."},{"type":"multi","q":"In <span class='ar'>طسٓمٓ</span>, tap each letter whose name is stretched to 6 counts.","ayah":"طسٓمٓ","ref":"Sūrat ash-Shuʿarāʾ 26:1","pool":["ط","س","م"],"answers":["س","م"],"why":"<span class='ar'>طا</span> ends on its madd letter with nothing after it, so it gets only 2 counts. <span class='ar'>سين</span> and <span class='ar'>ميم</span> each have a sukūn after the madd letter. The mushaf puts the madd sign over exactly those two."}],"_state":"verified","url":"https://www.youtube.com/watch?v=VVoZxsr8uiQ&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=30"},{"ep":31,"title_en":"Kept In Ink","title_ar":"الحروف المقطَّعة في القرآن الكريم","summary":"What is our share of the disjointed letters, and how did the written muṣḥaf keep the recited Qur'an safe?","teach":[{"label_en":"Our share","title_ar":"الحروف المقطَّعة","count":"29 sūras","tone":"brand","body":"Allah knows best what He meant by them. Our share: believe they are His speech, and recite them exactly as they reached us. Every letter earns a <span class='ar'>حسنة</span>, and a <span class='ar'>حسنة</span> counts tenfold."},{"label_en":"Written, never read","title_ar":"رسم المصحف","tone":"stop","body":"Some letters are written in the muṣḥaf but pronounced by no reader, like the alif in <span class='ar'>لِشَا۟ىْءٍ</span>. We keep them because the text was first written that way, and we do not respell it."},{"label_en":"Three copyings","title_ar":"مراحل كتابة المصحف","tone":"flow","body":"Pieces written in front of the Prophet ﷺ, then gathered into the <span class='ar'>صحف</span> under Abū Bakr, then copied into the maṣāḥif under ʿUthmān."},{"label_en":"Two guards","title_ar":"المكتوب والمنطوق","tone":"between","body":"The Qur'an was passed on both written and recited. The recitation shows how to read the writing, and the writing protects the recitation from <span class='ar'>التصحيف السمعي</span>, which means mishearing."}],"questions":[{"type":"choice","q":"How many sūras of the Qur'an open with <span class='ar'>الحروف المقطَّعة</span>?","options":["14","29","30","114"],"answerIndex":1,"why":"Twenty-nine sūras. Fourteen is the number of different letters used in them, exactly half the alphabet."},{"type":"choice","q":"Going by the ḥadīth he cites, how many <span class='ar'>حسنات</span> does reciting this earn?","ayah":"الٓمٓ","ref":"Sūrat al-Baqarah 2:1","options":["1","3","10","30"],"answerIndex":3,"why":"The Prophet ﷺ said he does not call <span class='ar'>الم</span> one letter: alif is a letter, lām is a letter and mīm is a letter. That makes three letters at ten <span class='ar'>حسنات</span> each."},{"type":"choice","q":"He cites this āya for text whose meaning Allah has not shown us. Who says these words?","ayah":"يَقُولُونَ ءَامَنَّا بِهِۦ كُلٌّ مِّنْ عِندِ رَبِّنَا","ref":"Sūrat Āl ʿImrān 3:7","options":["وَٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ","ٱلَّذِينَ فِى قُلُوبِهِمْ زَيْغٌ"],"arabicOptions":true,"answerIndex":0,"why":"The same āya says those with deviation in their hearts chase the unclear verses looking for <span class='ar'>فتنة</span>. Those firm in knowledge believe in all of it, the clear and the unclear."},{"type":"multi","q":"Look at the word after <span class='ar'>تَقُولَنَّ</span>. Tap the letter that is written but never pronounced.","ayah":"وَلَا تَقُولَنَّ لِشَا۟ىْءٍ إِنِّى فَاعِلٌ ذَٰلِكَ غَدًا","ref":"Sūrat al-Kahf 18:23","pool":["ل","ش","ا","ى","ء"],"answers":["ا"],"why":"It is read <span class='ar'>لِشَيْءٍ</span>, and no reader pronounces the alif. In the Madinah muṣḥaf, the small round zero over it marks a letter that is never pronounced, whether you continue or stop."},{"type":"choice","q":"Look at the last word. How many yāʾs are written, and how many are pronounced?","ayah":"وَٱلسَّمَآءَ بَنَيْنَٰهَا بِأَيْي۟دٍ","ref":"Sūrat adh-Dhāriyāt 51:47","options":["Two written, one pronounced","One written, two pronounced","Two written, two pronounced"],"answerIndex":0,"why":"It is read <span class='ar'>بِأَيْدٍ</span>, and no reader has ever pronounced two yāʾs. The second yāʾ carries the same round zero as the alif of <span class='ar'>لِشَا۟ىْءٍ</span>."},{"type":"choice","q":"What is unusual about the spelling of <span class='ar'>سَمَٰوَاتٍ</span> here?","ayah":"فَقَضَىٰهُنَّ سَبْعَ سَمَٰوَاتٍ","ref":"Sūrat Fuṣṣilat 41:12","options":["Its second alif is written in full, the only place in the Qur'an","Both of its alifs are written in full","Nothing: the word is spelled like this everywhere"],"answerIndex":0,"why":"Everywhere else the word is written <span class='ar'>سَمَٰوَٰت</span>, with both alifs left out of the line. It is pronounced the same way in every place. Only the spelling differs."},{"type":"choice","q":"Imām Mālik was asked whether a muṣḥaf may be written in the new spellings people had adopted. What did he say?","options":["No, only as it was first written (<span class='ar'>الكتبة الأولى</span>)","Yes, if it makes the text easier to read","Yes, but only in copies made for children"],"answerIndex":0,"why":"Scholars like Mālik held to the first spelling, which is why <span class='ar'>لِشَا۟ىْءٍ</span> still has its alif about fourteen centuries later. The spelling is passed on as carefully as the recitation."},{"type":"choice","q":"What were the ʿUthmānic maṣāḥif copied from?","options":["The <span class='ar'>صحف</span> compiled under Abū Bakr","What reciters in the garrison towns remembered","Each region's own local copies"],"answerIndex":0,"why":"ʿUthmān asked Ḥafṣa to send him the <span class='ar'>صحف</span> so they could be copied and then returned to her."},{"type":"choice","q":"Zayd ibn Thābit wrote down revelation for the Prophet ﷺ, then read it back to him. What happened if a word had been left out (<span class='ar'>سَقْط</span>)?","options":["The Prophet ﷺ corrected it, and only then did Zayd take it out to the people","Zayd fixed it later from his own memory","It was left for the next scribe to catch"],"answerIndex":0,"why":"The text was written, checked aloud at its source and corrected before anyone else saw it. Zayd went on to write the Qur'an again under Abū Bakr and under ʿUthmān."},{"type":"choice","q":"In the story he tells, two soldiers argued over how this āya ends. Which ending is in the muṣḥaf? <span class='ar'>وَأَتِمُّوا۟ ٱلْحَجَّ وَٱلْعُمْرَةَ ...</span>","options":["لِلَّهِ","لِلْبَيْتِ"],"arabicOptions":true,"answerIndex":0,"why":"The āya begins <span class='ar'>وَأَتِمُّوا۟ ٱلْحَجَّ وَٱلْعُمْرَةَ لِلَّهِ</span> (al-Baqarah 2:196). Disputes like this one, reported by Ḥudhayfa, led ʿUthmān to have the maṣāḥif copied and sent out, so readers could check against the written text."},{"type":"choice","q":"What protects the recited Qur'an from <span class='ar'>التصحيف السمعي</span>?","options":["The written text","Reciting faster","Learning its tafsīr"],"answerIndex":0,"why":"When people rely on memory, words get misheard. That is why a single line of pre-Islamic poetry can come down in six or seven versions. The Qur'an was written down as soon as it was revealed."},{"type":"choice","q":"As he explains it, what does <span class='ar'>عَزِيز</span> mean in this āya? The next āya shows it.","ayah":"وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٌ","ref":"Sūrat Fuṣṣilat 41:41","options":["Protected, so that nothing harmful can reach it","Revealed all at once","Easy to memorize"],"answerIndex":0,"why":"The next āya says <span class='ar'>لَّا يَأْتِيهِ ٱلْبَٰطِلُ مِنۢ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِۦ</span>: falsehood cannot reach it from in front or from behind."}],"_state":"verified","url":"https://www.youtube.com/watch?v=5za4w-bg6-U&list=PLJi21Zen45zQ-p3e38-Wb94LhDKIZ7sac&index=31"}];
window.GLOSSARY=[{"id":"makhraj","ar":"مَخْرَج","tr":"makhraj","en":"Point of articulation","def":"The place a letter’s sound comes from: the open space of mouth and throat, the throat, the tongue, the lips or the nasal passage. Plural مَخارِج.","forms":["مخرج","مخارج","مخرجان","مخارج الحروف"]},{"id":"sifa","ar":"صِفَة","tr":"ṣifa","en":"Characteristic","def":"How a letter behaves once it leaves its makhraj: whether sound or breath runs on, whether it is heavy or light, and so on. Letters that share a makhraj are told apart by their ṣifāt. Plural صِفات.","forms":["صفة","صفات"]},{"id":"halq","ar":"الحَلْق","tr":"al-ḥalq","en":"The throat","def":"Three points of articulation for six letters: ء and هـ lowest, ع and ح in the middle, غ and خ nearest the mouth.","forms":["الحلق","حلق"]},{"id":"jawf","ar":"الجَوْف","tr":"al-jawf","en":"The open space of mouth and throat","def":"The hollow inside the mouth and throat. It is where the three madd letters come from: ا, and و and ي when they lengthen.","forms":["الجوف","جوف","جوفية"]},{"id":"aqsa","ar":"أَقْصى اللِّسان","tr":"aqṣā al-lisān","en":"The back of the tongue","def":"The rearmost part of the tongue, against the soft palate. ق comes from here, and ك just forward of it.","forms":["اقصى اللسان"]},{"id":"khayshum","ar":"الخَيْشوم","tr":"al-khayshūm","en":"The nasal passage","def":"The passage at the back of the nose where ghunna is made. Pinch your nose and the ghunna stops.","forms":["خيشوم"]},{"id":"ghunna","ar":"غُنَّة","tr":"ghunna","en":"Nasal sound","def":"The hum that comes through the nose. It belongs to ن and م only and is always part of them; what changes from rule to rule is how long it is held.","forms":["غنة"]},{"id":"hams","ar":"الهَمْس","tr":"al-hams","en":"Breathed (whispered)","def":"Breath runs out with the letter, because it leans only lightly on its makhraj. Ten letters, gathered in فَحَثَّهُ شَخْصٌ سَكَتْ.","forms":["همس","مهموس","مهموسة"]},{"id":"fahaththahu","ar":"فَحَثَّهُ شَخْصٌ سَكَتْ","tr":"faḥaththahu shakhṣun sakat","en":"The breathed letters","def":"Memory phrase for the ten hams letters: ف ح ث ه ش خ ص س ك ت.","forms":["فحثه شخص سكت"]},{"id":"jahr","ar":"الجَهْر","tr":"al-jahr","en":"Voiced","def":"The breath is held back, because the letter leans firmly on its makhraj. Every letter not in فَحَثَّهُ شَخْصٌ سَكَتْ.","forms":["جهر","مجهور","مجهورة"]},{"id":"shidda","ar":"الشِّدَّة","tr":"ash-shidda","en":"Stopped (shadīd)","def":"The sound is locked at the makhraj and cannot run on. Eight letters, gathered in أَجِدْ قَطٍ بَكَتْ.","forms":["الشدة","شديد","شديدة"]},{"id":"ajid","ar":"أَجِدْ قَطٍ بَكَتْ","tr":"ajid qaṭin bakat","en":"The stopped letters","def":"Memory phrase for the eight shadīd letters: ء ج د ق ط ب ك ت.","forms":["اجد قط بكت"]},{"id":"rikhwa","ar":"الرَّخاوة","tr":"ar-rakhāwa","en":"Flowing (rikhw)","def":"The sound runs on freely while the letter is held. Every letter that is neither in أَجِدْ قَطٍ بَكَتْ nor in لِنْ عُمَرْ.","forms":["رخاوة","رخو","رخوة"]},{"id":"bayniyya","ar":"البَيْنِيَّة","tr":"al-bayniyya","en":"In-between","def":"Between stopped and flowing: the sound neither locks completely nor runs on freely. Five letters, gathered in لِنْ عُمَرْ.","forms":["بينية","البينية","متوسط","متوسطة"]},{"id":"lanumar","ar":"لِنْ عُمَرْ","tr":"lin ʿumar","en":"The in-between letters","def":"Memory phrase for the five in-between letters: ل ن ع م ر. It is a real sentence, “be gentle, ʿUmar!”","forms":["لن عمر"]},{"id":"istila","ar":"الاسْتِعْلاء","tr":"al-istiʿlāʾ","en":"Raised","def":"The back of the tongue rises toward the palate, which makes the letter heavy. Seven letters, gathered in خُصَّ ضَغْطٍ قِظْ.","forms":["استعلاء","مستعل","مستعلي","مستعلية"]},{"id":"istifal","ar":"الاسْتِفال","tr":"al-istifāl","en":"Lowered","def":"The tongue stays low, away from the palate. Every letter not in خُصَّ ضَغْطٍ قِظْ.","forms":["استفال","مستفل","مستفلة"]},{"id":"itbaq","ar":"الإطْباق","tr":"al-iṭbāq","en":"Tongue pressed to the palate","def":"The tongue presses up against the palate and the sound is enclosed between them. Four letters: ص ض ط ظ.","forms":["اطباق","مطبق","مطبقة"]},{"id":"infitah","ar":"الانْفِتاح","tr":"al-infitāḥ","en":"Tongue apart from the palate","def":"The tongue does not press against the palate, leaving a gap between them. Every letter except ص ض ط ظ.","forms":["انفتاح","منفتح","منفتحة"]},{"id":"safir","ar":"الصَّفير","tr":"aṣ-ṣafīr","en":"Whistling","def":"A sharp, whistle-like sound. Three letters: ص ز س.","forms":["صفير","حروف الصفير"]},{"id":"qalqala","ar":"قَلْقَلَة","tr":"qalqala","en":"Echo","def":"A slight rebound of sound on one of the letters قُطْبُ جَدٍ when it has a sukūn, so the letter isn’t swallowed. It is a characteristic of the letter, not a vowel.","forms":["قلقلة"]},{"id":"qutb","ar":"قُطْبُ جَدٍ","tr":"quṭbu jadin","en":"The echoing letters","def":"Memory phrase for the five qalqala letters: ق ط ب ج د.","forms":["قطب جد"]},{"id":"lin","ar":"اللِّين","tr":"al-līn","en":"Soft letters","def":"و or ي with a sukūn after a fatḥa, as in خَوْف and بَيْت. They are said easily, with no effort.","forms":["لين","حرف لين","حرفا اللين"]},{"id":"inhiraf","ar":"الانْحِراف","tr":"al-inḥirāf","en":"Veering","def":"The sound veers from its own makhraj toward another. Two letters: ل and ر.","forms":["انحراف","منحرف"]},{"id":"takrir","ar":"التَّكْرير","tr":"at-takrīr","en":"Trilling","def":"The tip of the tongue tends to flutter on ر. It belongs to ر, and it is learned so as not to overdo it.","forms":["تكرير"]},{"id":"tafashshi","ar":"التَّفَشِّي","tr":"at-tafashshī","en":"Spreading","def":"The air spreads out through the mouth. It belongs to ش.","forms":["تفشي"]},{"id":"istitala","ar":"الاسْتِطالة","tr":"al-istiṭāla","en":"Stretching along the tongue","def":"The sound of ض stretches along the edge of the tongue, from back to front. It is about where the sound travels, not about holding it longer.","forms":["استطالة"]},{"id":"tafkhim","ar":"التَّفْخيم","tr":"at-tafkhīm","en":"Heavy","def":"A full, heavy sound that fills the mouth. The raised letters are always heavy; ا, ل and ر are heavy only in certain positions.","forms":["تفخيم","مفخم","مفخمة"]},{"id":"tarqiq","ar":"التَّرْقيق","tr":"at-tarqīq","en":"Light","def":"A thin, light sound that does not fill the mouth. The lowered letters are light, except where ا, ل or ر turn heavy.","forms":["ترقيق","مرقق","مرققة"]},{"id":"haraka","ar":"حَرَكة","tr":"ḥaraka","en":"Vowel","def":"A short vowel on a letter: fatḥa (a), ḍamma (u) or kasra (i). Each is its madd letter cut short. A letter carrying one is mutaḥarrik. Plural حَرَكات.","forms":["حركة","حركات","متحرك","متحركة"]},{"id":"fatha","ar":"فَتْحَة","tr":"fatḥa","en":"Short a","def":"The short vowel a, written as a stroke above the letter: بَ.","forms":["فتحة"]},{"id":"damma","ar":"ضَمَّة","tr":"ḍamma","en":"Short u","def":"The short vowel u, written as a small و above the letter: بُ. The lips round for it.","forms":["ضمة"]},{"id":"kasra","ar":"كَسْرَة","tr":"kasra","en":"Short i","def":"The short vowel i, written as a stroke below the letter: بِ.","forms":["كسرة"]},{"id":"sukun","ar":"سُكون","tr":"sukūn","en":"No vowel","def":"A letter with no vowel on it is sākin, marked with a small circle: بْ.","forms":["سكون","ساكن","ساكنة"]},{"id":"shadda","ar":"شَدَّة","tr":"shadda","en":"Doubled letter","def":"The sign ّ over a letter. It stands for the letter twice: first with a sukūn, then with its vowel. A letter carrying it is mushaddad.","forms":["شدة","مشدد","مشددة"]},{"id":"tanwin","ar":"تَنْوين","tr":"tanwīn","en":"Nunation","def":"A doubled vowel sign at the end of a word, pronounced as a sākin ن: ـٌ is -un, ـً is -an, ـٍ is -in.","forms":["تنوين"]},{"id":"madd","ar":"مَدّ","tr":"madd","en":"Lengthening","def":"Stretching a vowel sound. The madd letters are ا, و with sukūn after a ḍamma, and ي with sukūn after a kasra.","forms":["مد","حرف مد","حروف المد","حروف مد"]},{"id":"tabii","ar":"المَدّ الطَّبيعي","tr":"al-madd aṭ-ṭabīʿī","en":"Natural madd","def":"A madd letter after its matching vowel, with no hamza or sukūn after it. Held two counts; cut shorter, the letter is lost.","forms":["مد طبيعي","المد الطبيعي","طبيعي"]},{"id":"badal","ar":"مَدّ البَدَل","tr":"madd al-badal","en":"Hamza, then madd","def":"A hamza followed by a madd letter, as in ءَامَنُوا۟. In Ḥafṣ it is held two counts, like the natural madd.","forms":["مد البدل","بدل"]},{"id":"iwad","ar":"مَدّ العِوَض","tr":"madd al-ʿiwaḍ","en":"Alif in place of tanwīn","def":"Stopping on a word ending in tanwīn with fatḥa: the tanwīn drops and an alif of two counts replaces it, رَحِيمًا → رَحِيمَا. Never on ة.","forms":["مد العوض","عوض"]},{"id":"hadamir","ar":"هاء الضَّمير","tr":"hāʾ aḍ-ḍamīr","en":"The pronoun hā’","def":"The ه meaning “him” or “his” for one absent male, as in لَهُۥ and بِهِۦ.","forms":["هاء الضمير"]},{"id":"sila","ar":"الصِّلة","tr":"aṣ-ṣila","en":"The pronoun’s link","def":"The و or ي heard after هاء الضمير when it sits between two voweled letters, in waṣl only: و after its ḍamma, ي after its kasra.","forms":["صلة"]},{"id":"silasughra","ar":"الصِّلة الصُّغْرى","tr":"aṣ-ṣila aṣ-ṣughrā","en":"Minor link","def":"The pronoun’s link when no همزة قطع follows. Held two counts, like the natural madd.","forms":["الصلة الصغرى","صلة صغرى"]},{"id":"silakubra","ar":"الصِّلة الكُبْرى","tr":"aṣ-ṣila al-kubrā","en":"Major link","def":"The pronoun’s link when a همزة قطع follows. It is lengthened like the separated madd: 4 or 5 counts in Ḥafṣ.","forms":["الصلة الكبرى","صلة كبرى"]},{"id":"munfasil","ar":"المَدّ المُنْفَصِل","tr":"al-madd al-munfaṣil","en":"Separated madd","def":"A madd letter ends one word and a همزة قطع starts the next: بِمَآ أُنزِلَ. In Ḥafṣ 4 or 5 counts, always the same length as the joined madd: 4 with 4, or 5 with 5.","forms":["منفصل","المد المنفصل","مد منفصل"]},{"id":"muttasil","ar":"المَدّ المُتَّصِل","tr":"al-madd al-muttaṣil","en":"Joined madd","def":"A madd letter followed by a hamza in the same word: جَآءَ. In Ḥafṣ 4 or 5 counts, always the same length as the separated madd.","forms":["متصل","المد المتصل","مد متصل"]},{"id":"lazim","ar":"المَدّ اللازِم","tr":"al-madd al-lāzim","en":"Locked madd","def":"A madd letter followed by a sukūn that is there whether you stop or carry on. Always 6 counts.","forms":["لازم","المد اللازم","مد لازم"]},{"id":"kalimi","ar":"كَلِمِيّ","tr":"kalimī","en":"In a word","def":"A locked madd inside an ordinary word. Its opposite, ḥarfī, is one inside the name of an opening letter such as الٓمٓ.","forms":["كلمي"]},{"id":"harfi","ar":"حَرْفِيّ","tr":"ḥarfī","en":"In a letter’s name","def":"A locked madd inside the name of one of the opening letters, such as the mīm of الٓمٓ.","forms":["حرفي"]},{"id":"mukhaffaf","ar":"مُخَفَّف","tr":"mukhaffaf","en":"Light (plain sukūn)","def":"A locked madd whose sukūn stays plain, with no shadda after it.","forms":["مخفف"]},{"id":"muthaqqal","ar":"مُثَقَّل","tr":"muthaqqal","en":"Heavy (into a shadda)","def":"A locked madd whose sukūn merges into the next letter as a shadda, as in ٱلضَّآلِّينَ.","forms":["مثقل"]},{"id":"arid","ar":"العارِض لِلسُّكون","tr":"al-ʿāriḍ lis-sukūn","en":"Madd before a stopping sukūn","def":"A madd letter before a sukūn that appears only because you stop, as when نَسْتَعِينُ is stopped on. 2, 4 or 6 counts.","forms":["العارض للسكون","عارض للسكون","العارض","عارض"]},{"id":"jaiz","ar":"جائِز","tr":"jāʾiz","en":"Optional","def":"A madd the reciters differ on, some lengthening it and some shortening it, such as the separated madd.","forms":["جائز"]},{"id":"wajib","ar":"واجِب","tr":"wājib","en":"Required","def":"The joined madd: every reciter lengthens it beyond two counts.","forms":["واجب"]},{"id":"qasr","ar":"القَصْر","tr":"al-qaṣr","en":"Short: 2 counts","def":"Reading a madd at its shortest, two counts.","forms":["القصر","قصر"]},{"id":"fuwayqqasr","ar":"فُوَيْق القَصْر","tr":"fuwayq al-qaṣr","en":"Just above short: 3 counts","def":"One count above the shortest: three counts.","forms":["فويق القصر"]},{"id":"tawassut","ar":"التَّوَسُّط","tr":"at-tawassuṭ","en":"Middle length: 4 counts","def":"In the madd, the middle length: four counts.","forms":["التوسط","توسط"]},{"id":"fuwayqtawassut","ar":"فُوَيْق التَّوَسُّط","tr":"fuwayq at-tawassuṭ","en":"Just above middle: 5 counts","def":"One count above the middle length: five counts.","forms":["فويق التوسط"]},{"id":"tul","ar":"الطُّول","tr":"aṭ-ṭūl","en":"Full length: 6 counts","def":"The longest madd: six counts.","forms":["الطول","طول"]},{"id":"hamzaqat","ar":"هَمْزة القَطْع","tr":"hamzat al-qaṭʿ","en":"Hamza that is always said","def":"A hamza pronounced whether you start on it or join it to what comes before.","forms":["همزة قطع","همزة القطع"]},{"id":"hamzawasl","ar":"هَمْزة الوَصْل","tr":"hamzat al-waṣl","en":"Hamza that drops when joined","def":"A hamza pronounced only when you start on it; joined to what comes before, it drops, as the ٱ of ٱلْحَمْدُ does.","forms":["همزة وصل","همزة الوصل"]},{"id":"muqattaa","ar":"الحُروف المُقَطَّعة","tr":"al-ḥurūf al-muqaṭṭaʿa","en":"The disjoined letters","def":"Letters read by their names, like الٓمٓ, that open 29 sūras. Allah knows best what He meant by them.","forms":["الحروف المقطعة","حروف مقطعة"]},{"id":"rawm","ar":"الرَّوْم","tr":"ar-rawm","en":"A trace of the vowel","def":"When stopping, saying part of the final vowel in a faint voice instead of dropping it entirely.","forms":["الروم","روم"]},{"id":"ishmam","ar":"الإشْمام","tr":"al-ishmām","en":"Lips rounded, no sound","def":"When stopping on a ḍamma, rounding the lips as if to say it, with no sound.","forms":["الاشمام","اشمام"]},{"id":"mutamathilan","ar":"مُتَماثِلان","tr":"mutamāthilān","en":"Identical letters","def":"The same letter twice in a row, the first sākin, as in اضْرِب بِّعَصَاكَ.","forms":["متماثلان","متماثلين"]},{"id":"mutajanisan","ar":"مُتَجانِسان","tr":"mutajānisān","en":"Same-point letters","def":"Two letters from one makhraj that differ in some ṣifāt, like د and ت.","forms":["متجانسان","متجانسين"]},{"id":"mutaqariban","ar":"مُتَقارِبان","tr":"mutaqāribān","en":"Close letters","def":"Two letters close in makhraj, in ṣifāt, or both, without being identical, like ق and ك, or ل and ر.","forms":["متقاربان","متقاربين"]},{"id":"idgham","ar":"إدْغام","tr":"idghām","en":"Merging","def":"Running one letter into the next so that both are said as a single doubled letter. The muṣḥaf usually marks it with a shadda on the second letter.","forms":["ادغام","مدغم","مدغمة","ادغام بغنة","مدغمة بغنة"]},{"id":"ikhfa","ar":"إخْفاء","tr":"ikhfāʾ","en":"Hiding","def":"Saying a sākin ن or م in a state between clear and merged, while the ghunna is held.","forms":["اخفاء","مخفى","مخفاة"]},{"id":"izhar","ar":"إظْهار","tr":"iẓhār","en":"Clear pronunciation","def":"Saying a letter plainly from its own makhraj, with no merging or hiding.","forms":["اظهار","مظهر","مظهرة"]},{"id":"iqlab","ar":"إقْلاب","tr":"iqlāb","en":"Turning into mīm","def":"A sākin ن or tanwīn before ب turns into a hidden م. The muṣḥaf marks it with a small م.","forms":["اقلاب","قلب","مقلوبة"]},{"id":"shamsiyya","ar":"الحروف الشَّمْسِيَّة","tr":"sun letters","en":"Sun letters","def":"The fourteen letters that the ل of ال merges into, so it isn’t heard, as in الشَّمْس.","forms":["شمسية"]},{"id":"qamariyya","ar":"الحروف القَمَرِيَّة","tr":"moon letters","en":"Moon letters","def":"The fourteen letters before which the ل of ال is pronounced clearly, as in الْقَمَر.","forms":["قمرية"]},{"id":"lamtarif","ar":"لام التَّعْريف","tr":"lām at-taʿrīf","en":"The l of “al-”","def":"The ل of the definite article ال. It is pronounced before moon letters and merged into sun letters.","forms":["لام التعريف"]},{"id":"waqf","ar":"الوَقْف","tr":"al-waqf","en":"Stopping","def":"Cutting off the sound at the end of a word to take a breath, intending to carry on reciting.","forms":["وقف"]},{"id":"ibtida","ar":"الابْتِداء","tr":"al-ibtidāʾ","en":"Starting again","def":"Resuming after a stop, from a place that keeps the meaning sound.","forms":["ابتداء"]},{"id":"ikhtiyari","ar":"وَقْف اخْتِياري","tr":"ikhtiyārī","en":"Chosen stop","def":"A stop the reciter chooses to make. It is the only kind graded as complete, sufficient, good or bad.","forms":["اختياري"]},{"id":"idtirari","ar":"وَقْف اضْطِراري","tr":"iḍṭirārī","en":"Forced stop","def":"A stop forced on the reciter by a cough, a sneeze or running out of breath.","forms":["اضطراري"]},{"id":"ikhtibari","ar":"وَقْف اخْتِباري","tr":"ikhtibārī","en":"Test stop","def":"A stop made because a teacher asks how a word is stopped on.","forms":["اختباري"]},{"id":"tamm","ar":"وَقْف تامّ","tr":"tāmm","en":"Complete stop","def":"Stopping where the next words are linked to this one neither in grammar nor in meaning. Stop, then start from the next word.","forms":["تام"]},{"id":"hasan","ar":"وَقْف حَسَن","tr":"ḥasan","en":"Good stop","def":"The sense is already complete, but the next words are linked to it. Stop, then go back and reconnect, unless you stopped at the end of an āya.","forms":["حسن"]},{"id":"qabih","ar":"وَقْف قَبيح","tr":"qabīḥ","en":"Bad stop","def":"Stopping where the meaning breaks. Never on purpose; if forced to, go back and read again.","forms":["قبيح"]},{"id":"jali","ar":"اللَّحْن الجَلِيّ","tr":"al-laḥn al-jalī","en":"Obvious error","def":"A mistake that changes a letter or a vowel, so the word itself changes. Corrected for every reader.","forms":["الجلي","لحن جلي","اللحن الجلي"]},{"id":"khafi","ar":"اللَّحْن الخَفِيّ","tr":"al-laḥn al-khafī","en":"Subtle error","def":"Breaking a rule of tajwīd while the word stays intact, such as cutting a ghunna short.","forms":["الخفي","لحن خفي","اللحن الخفي"]},{"id":"tahqiq","ar":"التَّحْقيق","tr":"at-taḥqīq","en":"Slow pace","def":"The slowest, most careful pace of recitation, used for teaching and learning.","forms":["تحقيق"]},{"id":"tadwir","ar":"التَّدْوير","tr":"at-tadwīr","en":"Middle pace","def":"A pace between the slow taḥqīq and the brisk ḥadr.","forms":["تدوير"]},{"id":"hadr","ar":"الحَدْر","tr":"al-ḥadr","en":"Brisk pace","def":"The quickest pace of recitation, still keeping every rule.","forms":["حدر"]},{"id":"jazariyya","ar":"المُقَدِّمة الجَزَرِيَّة","tr":"al-Muqaddima al-Jazariyya","en":"Ibn al-Jazarī’s poem","def":"The classic rhyming poem on tajwīd by Ibn al-Jazarī (d. 833 AH), memorised by students and quoted throughout this course.","forms":["المقدمة الجزرية","الجزرية"]},{"id":"bayt","ar":"بَيْت","tr":"bayt","en":"Line of verse","def":"One line of a poem such as the Jazariyya, made of two halves.","forms":["بيت","ابيات"]}];
